ഒരുനിവേദനത്തിൽ: "മൂന്ന്കാര്യങ്ങളുണ്ട്, ഒരു മുസ്ലിമിന്റെ ഹൃദയം അവയിൽ വഞ്ചിക്കപ്പെടുകയില്ല. കർമ്മങ്ങളിൽ അല്ലാഹുവിന് വേണ്ടിയുള്ള നിഷ്കളങ്കത, മുസ്ലിംകളുടെ നേതാക്കൻമാർക്ക് ഗുണകാംക്ഷിക്കൽ, അവരുടെ കൂട്ടത്തിൽ സ്ഥിരമായി നിൽക്കൽ എന്നിവയാണത്." (ജ)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
