insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (2, 16, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1021) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "بَيْنَا أَنَا نَائِمٌ أُتِيتُ بِقَدَحِ لَبَنٍ، فَشَرِبْتُ حَتَّى إِنِّي لَأَرَى الرِّيَّ يَخْرُجُ فِي أَظْفَارِي، ثُمَّ أَعْطَيْتُ فَضْلِي عُمَرَ بْنَ الْخَطَّابِ". قَالُوا: فَمَا أَوَّلْتَهُ يَا رَسُولَ اللهِ؟ قَالَ: "الْعِلْمَ". (خ)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഉറങ്ങിക്കൊണ്ടിരിക്കെ എനിക്ക് ഒരു പാൽപാത്രം നൽകപ്പെട്ടു. ഞാനത് കുടിച്ചു. ദാഹം തീർന്ന കുളിർമ എന്റെ നഖങ്ങൾ വരെ വ്യാപിച്ചു കൊണ്ടിരിക്കുന്നത് ഞാൻ അറിഞ്ഞു. അവസാനം മിച്ചമായത് ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന് കൊടുത്തു." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, അങ്ങ് എങ്ങനെയാണതിനെ വ്യാഖ്യാനിക്കുന്നത്? അവിടന്ന് പറഞ്ഞു: "അത് വിജ്ഞാനമാകുന്നു." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَثَلُ مَا بَعَثَنِي اللهُ بِهِ مِنَ الْهُدَى وَالْعِلْمِ كَمَثَلِ الْغَيْثِ الْكَثِيرِ أَصَابَ أَرْضًا، فَكَانَ مِنْهَا نَقِيَّةٌ قَبِلَتِ الْمَاءَ، فَأَنْبَتَتِ الْكَلَأَ وَالْعُشْبَ الْكَثِيرَ، وَكَانَتْ مِنْهَا أَجَادِبُ، أَمْسَكَتِ الْمَاءَ، فَنَفَعَ اللهُ بِهَا النَّاسَ، فَشَرِبُوا وَسَقَوْا وَزَرَعُوا، وَأَصَابَتْ مِنْهَا طَائِفَةً أُخْرَى، إِنَّمَا هِيَ قِيعَانٌ، لَا تُمْسِكُ مَاءً، وَلَا تُنْبِتُ كَلَأً، فَذَلِكَ مَثَلُ مَنْ فَقُهَ فِي دِينِ اللهِ وَنَفَعَهُ مَا بَعَثَنِي اللهُ بِهِ، فَعَلِمَ وَعَلَّمَ، وَمَثَلُ مَنْ لَمْ يَرْفَعْ بِذَلِكَ رَأْسًا، وَلَمْ يَقْبَلْ هُدَى اللهِ الَّذِي أُرْسِلْتُ بِهِ". (خ)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു എന്നെ ഭരമേൽപ്പിച്ചിരിക്കുന്ന നേർമാർഗത്തിന്റെയും വിജ്ഞാനത്തിന്റെയും സ്ഥിതി ഒരു പേമാരി പോലെയാണ്. അത് ഒരുസ്ഥലത്ത് വർഷിച്ചു. അവിടെ നല്ല ഭൂമി ഉണ്ടായിരുന്നു. അത് വെള്ളത്തെ വലിച്ചെടുത്തു. പുല്ലും ധാരാളം സസ്യങ്ങളും അതിൽ നിന്ന് മുളച്ചു. എന്നാൽ അവിടെ അത്യധികം ഉറച്ച സ്ഥലങ്ങളുമുണ്ടായിരുന്നു. അത് വെള്ളം തടഞ്ഞു നിർത്തി. അത് മുഖേന അല്ലാഹു മനുഷ്യർക്ക് പ്രയോജനം നൽകി. മനുഷ്യർ കുടിച്ചു. മൃഗങ്ങൾക്ക് കുടിക്കാൻ നൽകി. കൃഷി നനച്ചു. എന്നാൽ മഴയിൽ ഒരംശം പെയ്തത് സമനിരപ്പായിക്കിടക്കുന്ന ഭൂമിയിലാണ്. അതിനു വെള്ളം തടഞ്ഞു നിർത്താൻ കഴിവില്ല. അതിൽ പുല്ലു മുളക്കുകയുമില്ല. ഇതാണ് അല്ലാഹുവിന്റെ ദീനിന്റെ ആന്തരിക തത്വങ്ങൾ ഗ്രഹിക്കുകയും എന്നെ അല്ലാഹു ഭരമേൽപ്പിച്ചയച്ച മാർഗദർശനം മുഖേന പ്രയോജനം ലഭിക്കുകയും ചെയ്തവന്റെ ഉദാഹരണം (ആദ്യം പറഞ്ഞ ഭൂമിയുടേത് പോലെ). അവൻ സ്വയം പഠിച്ച് മറ്റുള്ളവർക്ക് പഠിപ്പിച്ച് കൊടുത്തു. ഇതാണ് അല്ലാഹു നൽകിയ വിദ്യയുടെയും മാർഗദർശനത്തിന്റെയും നേരെ തലയുയർത്തി നോക്കുക പോലും ചെയ്യാതിരിക്കുകയും ഏതു മാർഗ ദർശനവും കൊണ്ട് അല്ലാഹു എന്നെ അയച്ചിട്ടുണ്ടോ ആ മാർഗദർശനം സ്വീകരിക്കാതിരിക്കുകയും ചെയ്തവന്റെ ഉദാഹരണം (അവസാനം പറഞ്ഞ ഭൂമിയുടേതു പോലെ)." (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قال: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللهُ مَالًا فَسُلِّطَ عَلَى هَلَكَتِهِ فِي الْحَقِّ، وَرَجُلٌ آتَاهُ اللهُ الْحِكْمَةَ فَهُوَ يَقْضِي بِهَا وَيُعَلِّمُهَا". (خ)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "രണ്ടു കാര്യത്തിൽ മാത്രമേ അസൂയയുള്ളൂ. ഒരാൾ, അയാൾക്ക് അല്ലാഹു ധനം നൽകി, സത്യ മാർഗ്ഗത്തിൽ ചെലവഴിക്കാൻ അതവൻ നീക്കിവെച്ചു. ഒരാൾ, അയാൾക്ക് അല്ലാഹു വിദ്യ നൽകി, ആ വിദ്യയെ ഉപയോഗപ്പെടുത്തിക്കൊണ്ട് അവൻ മനുഷ്യർക്കിടയിൽ വിധി കൽപ്പിക്കുന്നു, മനുഷ്യർക്കത് പഠിപ്പിക്കുന്നു." (ബു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 838, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ لَهُمْ أَجْرَانِ، رَجُلٌ مِنْ أَهْلِ الْكِتَابِ آمَنَ بِنَبِيِّهِ وَآمَنَ بِمُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَالْعَبْدُ الْمَمْلُوكُ إِذَا أَدَّى حَقَّ اللهِ وَحَقَّ مَوَالِيهِ، وَرَجُلٌ كَانَتْ عِنْدَهُ أَمَةٌ فَأَدَّبَهَا فَأَحْسَنَ تَأْدِيبَهَا وَعَلَّمَهَا فَأَحْسَنَ تَعْلِيمَهَا ثُمَّ أَعْتَقَهَا فَتَزَوَّجَهَا، فَلَهُ أَجْرَانِ". (خ)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് പേർക്ക് ഇരട്ടി പ്രതിഫലം ലഭിക്കും: പൂർവ്വ വേദക്കാരിൽ പെട്ടൊരു മനുഷ്യൻ; അയാൾ തന്റെ നബിയിൽ വിശ്വസിച്ചു, മുഹമ്മദ് നബി(സ)യിലും വിശ്വസിച്ചു. മറ്റൊരുത്തന്റെ ഉടമസ്ഥതയിൽ ജീവിക്കുന്ന അടിമ; അല്ലാഹുവിനോടും തന്റെ യജമാനനോടുമുള്ള ബാധ്യതകൾ അവൻ നിറവേറ്റിയാൽ. ഒരു മനുഷ്യൻ; അവന്റെ അധീനതയിൽ ഒരു അടിമസ്ത്രീയുണ്ട്. അവളെ അവൻ മര്യാദ പഠിപ്പിച്ചു. നല്ല നിലക്ക് വിദ്യ അഭ്യസിപ്പിച്ചു. അവളെ അടിമത്വത്തിൽ നിന്നു മോചിപ്പിക്കുകയും, അവളെ വിവാഹം കഴിക്കുകയും ചെയ്തു. അവനും ഇരട്ടി പ്രതിഫലമുണ്ട്." (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 838, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: بَيْنَمَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَجْلِسٍ يُحَدِّثُ الْقَوْمَ، جَاءَهُ أَعْرَابِيٌّ فقال: مَتَى السَّاعَةُ؟ فَمَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُحَدِّثُ فَقَالَ بَعْضُ الْقَوْمِ: سَمِعَ مَا قَالَ فَكَرِهَ مَا قَالَ، وَقَالَ بَعْضُهُمْ: بَلْ لَمْ يَسْمَعْ، حَتَّى إِذَا قَضَى حَدِيثَهُ قَالَ: "أَيْنَ أُرَاهُ السَّائِلُ عَنِ السَّاعَةِ؟" قَالَ: هَا أَنَا يَا رَسُولَ اللهِ، قَالَ: "فَإِذَا ضُيِّعَتِ الْأَمَانَةُ فَانْتَظِرِ السَّاعَةَ". فقال: كَيْفَ إِضَاعَتُهَا؟ قَالَ: "إِذَا وُسِّدَ الْأَمْرُ إِلَى غَيْرِ أَهْلِهِ، فَانْتَظِرِ السَّاعَةَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരു സദസ്സിൽ ജനങ്ങളോട് സംസാരിച്ചുകൊണ്ടിരിക്കുമ്പോൾ ഒരു നാടനറബി വന്ന് നബി(സ)യോട് ചോദിച്ചു: അന്ത്യനാൾ എപ്പോഴാണ്? റസൂൽ(സ) സംസാരിച്ച് കൊണ്ടിരുന്നു. ചിലർ പറഞ്ഞു: അയാൾ പറഞ്ഞത് തിരുമേനി(സ) കേട്ടിട്ടുണ്ട്. പക്ഷേ, ചോദിച്ചത് നബി(സ)ക്ക് ഇഷ്ടമായില്ല. ചിലർ പറഞ്ഞു: നബി(സ) അത് കേട്ടിട്ടില്ല. തന്റെ സംസാരം കഴിഞ്ഞപ്പോൾ "അന്ത്യദിനത്തെക്കുറിച്ച് ചോദിച്ചവനെവിടെ" എന്ന് നബി(സ) അന്വേഷിച്ചു. അല്ലാഹുവിന്റെ റസൂലേ, ഞാനിതാ ഇവിടെയുണ്ട്, അയാൾ പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അമാനത് (സൂക്ഷിപ്പുസ്വത്തുകൾ) നഷ്ടപ്പെടുത്തായാൽ നീ അന്ത്യദിനത്തെ കാത്തിരുന്നുകൊള്ളുക." അമാനത് നഷ്ടുപ്പെടുന്നതെങ്ങനെ? അയാൾ ചോദിച്ചു. നബി(സ) അരുളി: "ഓരോ കാര്യങ്ങളുടെയും നിയന്ത്രണാധികാരം അതിനർഹതയില്ലാത്തവരെ ഏൽപ്പിച്ചു കഴിഞ്ഞാൽ, നീ അന്ത്യദിനം പ്രതീക്ഷിച്ചുകൊള്ളുക." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 838, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قال: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ يُرِدِ اللهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ، وَإِنَّمَا أَنَا قَاسِمٌ وَاللهُ يُعْطِي، وَلَنْ تَزَالَ هَذِهِ الْأُمَّةُ قَائِمَةً عَلَى أَمْرِ اللهِ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللهِ". (خ,ت)', 'മുആവിയ(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹു വല്ലവനും നന്മ ഉദ്ദേശിച്ചാൽ മതത്തിന്റെ ആന്തരിക തത്വങ്ങൾ അവനെ അല്ലാഹു ഗ്രഹിപ്പിക്കും. ഞാൻ വീതിച്ച് കൊടുക്കുന്നവൻ മാത്രമാണ്. അല്ലാഹുവാണ് നൽകുന്നത്. ഈ സമൂഹം അല്ലാഹുവിന്റെ കൽപ്പനയിൽ ഉറച്ച് നിൽക്കും. അവർക്ക് ഒരു ദോഷവും വരുത്തി വെക്കാൻ ശത്രുക്കൾക്ക് കഴിയുകയില്ല, അല്ലാഹുവിന്റെ കൽപ്പന വരുന്നത് വരെ." (ബു,തു)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 838, 839, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَقِيهٌ أَشَدُّ عَلَى الشَّيْطَانِ مِنْ أَلْفِ عَابِدٍ". (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആയിരം ആരാധകരെക്കാൾ ഒരു ജ്ഞാനിയാണ് ചെകുത്താന്റെയടുത്ത് ശക്തൻ." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 839, 839, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ قَيْسِ بْنِ كَثِيرٍ قال: قَدِمَ رَجُلٌ مِنَ الْمَدِينَةِ عَلَى أَبِي الدَّرْدَاءِ -رَضِيَ اللهُ عَنْهُ- وَهُوَ بِدِمَشْقَ، فَقَالَ: مَا أَقْدَمَكَ يَا أَخِي؟ فَقَالَ: حَدِيثٌ بَلَغَنِي أَنَّكَ تُحَدِّثُهُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: أَمَا جِئْتَ لِحَاجَةٍ؟ قال: لَا. قال: أَمَا قَدِمْتَ لِتِجَارَةٍ؟ قال: لَا. قال مَا جِئْتُ إِلَّا فِي طَلَبِ هَذَا الْحَدِيثِ. قال: فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ سَلَكَ طَرِيقًا يَبْتَغِي فِيهِ عِلْمًا سَلَكَ اللهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَإِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا رِضَاءً لِطَالِبِ الْعِلْمِ، وَإِنَّ الْعَالِمَ لَيَسْتَغْفِرُ لَهُ مَنْ فِي السَّمَوَاتِ وَمَنْ فِي الْأَرْضِ، حَتَّى الْحِيتَانُ فِي الْمَاءِ. وَفَضْلُ الْعَالِمِ عَلَى الْعَابِدِ كَفَضْلِ الْقَمَرِ عَلَى سَائِرِ الْكَوَاكِبِ، إِنَّ الْعُلَمَاءَ وَرَثَةُ الْأَنْبِيَاءِ، إِنَّ الْأَنْبِيَاءَ لَمْ يُوَرِّثُوا دِينَارًا وَلَا دِرْهَمًا، إِنَّمَا وَرَّثُوا الْعِلْمَ، فَمَنْ أَخَذَ بِهِ أَخَذَ بِحَظٍّ وَافِرٍ". (د,ت,جه)', 'ഖൈസുബ്നു കസീർ(റ): മദീനയിൽ നിന്ന് ഒരാൾ അബുദ്ദർദാഅ്(റ)വിന്റെ അടുത്തു വന്നു. അദ്ദേഹം അപ്പോൾ ഡമസ്കസിലായിരുന്നു. അദ്ദേഹം ആഗതനോട് ചോദിച്ചു: സഹോദരാ, നിങ്ങളെ ഇവിടെ വരാൻ പ്രേരിപ്പിച്ച വസ്തുവെന്താണ്? ആഗതൻ പറഞ്ഞു: താങ്കൾ റസൂൽ(സ)യുടെ ഹദീസ് പറഞ്ഞ് കൊടുക്കുന്നുണ്ടെന്നുള്ള വാർത്തയാണ്. അബുദ്ദർദാഅ്(റ) ചോദിച്ചു: നീ വല്ല ആവശ്യത്തിനും വന്നതാണോ. ആഗതൻ പറഞ്ഞു: അല്ല. അദ്ദേഹം വീണ്ടും ചോദിച്ചു: നീ വല്ല കച്ചവടത്തിനും വന്നതാണോ? അയാൾ പറഞ്ഞു: അല്ല, ഹദീസ് തേടി മാത്രമാണ് ഞാൻ വന്നത്. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. "വിജ്ഞാനം ആഗ്രഹിച്ച് കൊണ്ട് ആരെങ്കിലും വല്ല വഴിയിലും പ്രവേശിച്ചാൽ അവനെ അല്ലാഹു സ്വർഗത്തിലേക്കുള്ള വഴിയിൽ പ്രവേശിപ്പിക്കും. വിദ്യാർത്ഥിക്ക് മാലാഖമാർ തൃപ്തിപൂർവ്വം ചിറക് വിരിച്ച് കൊടുക്കും. ആകാശ ഭൂമിയിലുള്ളവർ ജ്ഞാനിക്കു വേണ്ടി പാപമോചനം തേടും, വെള്ളത്തിലുള്ള മത്സ്യം വരെ. ആരാധനകനെക്കാൾ ജ്ഞാനിക്കുള്ള ശ്രേഷ്ഠത ചന്ദ്രന് മറ്റു നക്ഷത്രങ്ങളേക്കാളുള്ള ശ്രേഷ്ഠത പോലെയാണ്. ജ്ഞാനികൾ പ്രവാചകന്മാരുടെ അനന്തരാവകാശികളാണ്. പ്രവാചകന്മാർ ദീനാറോ ദിർഹമോ അനന്തരമായി ഇട്ടേച്ചു പോയിട്ടില്ല. അവർ അനന്തരമാക്കിയത് വിജ്ഞാനമാണ്. ആരെങ്കിലും അത് സ്വീകരിക്കുകയാണെങ്കിൽ പരിപൂർണ്ണമായ വിഹിതം തന്നെയാണ് അവൻ സ്വീകരിച്ചിരിക്കുന്നത്." (ദ,തു,ജ)', 'قَيْسِ بْنِ كَثِيرٍ قال', 'ഖൈസുബ്നു കസീർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 839, 839, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ يَزِيدَ بْنِ سَلَمَةَ الْجُعْفِيِّ رَضِيَ اللهُ عَنْهُ قال: قُلْتُ: يَا رَسُولَ اللهِ، إِنِّي قَدْ سَمِعْتُ مِنْكَ حَدِيثًا كَثِيرًا، أَخَافُ أَنْ يُنْسِيَنِي أَوَّلَهُ آخِرُهُ، فَحَدِّثْنِي بِكَلِمَةٍ تَكُونُ جِمَاعًا. قَالَ: "اتَّقِ اللهَ فِيمَا تَعْلَمُ". (ت)', 'യസീദുബ്നു സലമതൽ ജുഅ്ഫി(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞാൻ അങ്ങിൽ നിന്ന് ഒരു പാട് ഹദീസ് കേട്ടിട്ടുണ്ട്. അവയിൽ ആദ്യം കേട്ടതിനെ അവസാനം കേട്ടത് മറപ്പിക്കുമോ എന്ന് ഞാൻ ഭയക്കുന്നു. അപ്പോൾ എനിക്ക് നബി(സ) സമ്പൂർണ്ണമായ ഒരു വാക്ക് പഠിപ്പിച്ചുതന്നു. നബി(സ) പറഞ്ഞു: "നീ അറിയുന്നതിൽ അല്ലാഹുവിനെ സൂക്ഷിക്കുക." (തു)', 'يَزِيدَ بْنِ سَلَمَةَ الْجُعْفِيِّ', 'യസീദുബ്നു സലമതൽ ജുഅ്ഫി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 839, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَصْلَتَانِ لَا تَجْتَمِعَانِ فِي مُنَافِقٍ: حُسْنُ سَمْتٍ، وَلَا فِقْهٌ فِي الدِّينِ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കപട വിശ്വാസിയിൽ രണ്ട് കാര്യങ്ങൾ ഒരുമിച്ചുണ്ടാകില്ല: നല്ല മൗനവും മതത്തിലെ ആന്തരജ്ഞാനം." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 840, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللهُ عَنْهُ قال: ذُكِرَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلَانِ: أَحَدُهُمَا عَابِدٌ، وَالْآخَرُ عَالِمٌ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَضْلُ الْعَالِمِ عَلَى الْعَابِدِ كَفَضْلِي عَلَى أَدْنَاكُمْ". ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ وَمَلَائِكَتَهُ وَأَهْلَ السَّمَوَاتِ وَالْأَرْضِ، حَتَّى النَّمْلَةَ فِي جُحْرِهَا، وَحَتَّى الْحُوتَ، لَيُصَلُّونَ عَلَى مُعَلِّمِ النَّاسِ الْخَيْرَ". حَسَنٌ صَحِيحٌ (ت)', 'അബൂഉമാമതൽ ബാഹിലി(റ): നബി(സ)യോട് രണ്ടാളുകളെക്കുറിച്ച് പറഞ്ഞു: അതിൽ ഒരാൾ ആരാധന ചെയ്യുന്നവനും മറ്റെയാൾ ജ്ഞാനിയുമാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ജ്ഞാനിക്ക് ആരാധകനെക്കാളുമുള്ള ശ്രേഷതത എനിക്ക് നിങ്ങളിൽ ഏറ്റവും താഴ്ന്നവനെക്കാളുമുള്ള ശ്രേഷ്ഠത പോലെയാണ്. പിന്നെ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവും മാലാഖമാരും ആകാശ നിവാസികളും ഭൂനിവാസികളും മാളത്തിലെ ഉറുമ്പുകളും മത്സ്യങ്ങൾ പോലും ജനങ്ങൾക്ക് നന്മ പഠിപ്പിക്കുന്നവർക്ക് വേണ്ടി പ്രാർത്ഥിക്കും." (തു)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമതൽ ബാഹിലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 840, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "لَنْ يَشْبَعَ الْمُؤْمِنُ مِنْ خَيْرٍ يَسْمَعُهُ حَتَّى يَكُونَ مُنْتَهَاهُ الْجَنَّةُ". حَسَنٌ. (ت)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു വിശ്വാസിക്ക് നന്മ കേട്ട് വയർ നിറയുകയില്ല, അതിന്റെ പര്യവസാനം സ്വർഗമാവുന്നത് വരെ." (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 840, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْكَلِمَةُ الْحِكْمَةُ ضَالَّةُ الْمُؤْمِنِ، فَحَيْثُ وَجَدَهَا فَهُوَ أَحَقُّ بِهَا". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "യുക്തി നിറഞ്ഞ വചനം വിശ്വാസിയുടെ നഷ്ടപ്പെട്ടുപോയ സ്വത്താണ്. അതെവിടെ വെച്ച് കിട്ടിയാലും അവനാണതിന് ഏറ്റവും അർഹൻ." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 840, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ كَثِيرِ بْنِ قَيْسٍ قال: كُنْتُ جَالِسًا مَعَ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ فِي مَسْجِدِ دِمَشْقَ، فَجَاءَهُ رَجُلٌ فَقَالَ: يَا أَبَا الدَّرْدَاءِ، إِنِّي جِئْتُكَ مِنْ مَدِينَةِ الرَّسُولِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِحَدِيثٍ بَلَغَنِي أَنَّكَ تُحَدِّثُهُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مَا جِئْتُ لِحَاجَةٍ. قال: فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ سَلَكَ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا سَلَكَ اللهُ بِهِ طَرِيقًا مِنْ طُرُقِ الْجَنَّةِ، وَإِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا رِضًا لِطَالِبِ الْعِلْمِ، وَإِنَّ الْعَالِمَ لَيَسْتَغْفِرُ لَهُ مَنْ فِي السَّمَوَاتِ وَمَنْ فِي الْأَرْضِ وَالْحِيتَانُ فِي جَوْفِ الْمَاءِ، وَإِنَّ فَضْلَ الْعَالِمِ عَلَى الْعَابِدِ كَفَضْلِ الْقَمَرِ لَيْلَةَ الْبَدْرِ عَلَى سَائِرِ الْكَوَاكِبِ، وَإِنَّ الْعُلَمَاءَ وَرَثَةُ الْأَنْبِيَاءِ، وَإِنَّ الْأَنْبِيَاءَ لَمْ يُوَرِّثُوا دِينَارًا وَلَا دِرْهَمًا، وَرَّثُوا الْعِلْمَ، فَمَنْ أَخَذَهُ أَخَذَ بِحَظٍّ وَافِرٍ". (د,ت,جه)', 'കസീറുബ്നു ഖൈസ്(റ): ഞാൻ അബുദ്ദർദാഅ്(റ)വിന്റെ കൂടെ ഡമസ്കസിലെ പള്ളിയിൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ അദ്ദേഹത്തിന്റെ അടുത്ത് ഒരാൾ വന്നുകൊണ്ട് പറഞ്ഞു: അബുദ്ദർദാഅ് എന്നവരേ, ഞാൻ റസൂൽ(സ)യുടെ മദീനയിൽ നിന്നാണ് വരുന്നത്. താങ്കൾ റസൂൽ(സ)യിൽ നിന്നുള്ള ഹദീസ് പറയുന്നുണ്ടെന്ന് എനിക്ക് വിവരം ലഭിച്ചിരിക്കുന്നു. മറ്റൊരാവശ്യത്തിനും വേണ്ടിയല്ല ഞാൻ വന്നത്. അബുദ്ദർദാഅ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "വിദ്യ തേടിക്കൊണ്ട് ആരെങ്കിലും വല്ല വഴിയിലും പ്രവേശിച്ചാൽ അല്ലാഹു അവനെ സ്വർഗത്തിലേക്കുള്ള വഴികളിലൊന്നിൽ പ്രവേശിപ്പിക്കും. വിദ്യ തേടുന്നവന് മാലാഖമാർ തൃപ്തിയോടെ ചിറകുകൾ വിരിച്ച് നൽകും. ജ്ഞാനിക്ക് വേണ്ടി ആകാശ ഭൂമിയിലുള്ളവർ മുഴുവനും വെള്ളത്തിലെ മത്സ്യങ്ങളും പൊറുക്കലിനെ തേടും. ആരാധിക്കുന്നവനേക്കാൾ ജ്ഞാനിക്കുള്ള ശ്രേഷ്ഠത ചാന്ദ്രികരാത്രിയിൽ ചന്ദ്രന് മറ്റുള്ള നക്ഷത്രങ്ങളേക്കാളുള്ള ശ്രേഷ്ഠത പോലെയാണ്. ജ്ഞാനികൾ പ്രവാചകരുടെ അനന്തരാവകാശികളാണ്. പ്രവാചകർ ദിർഹമോ ദീനാറോ അനന്തരമായി നൽകിയിട്ടില്ല. വിജ്ഞാനമാണ് അവർ അനന്തരമായി നൽകിയത്. ആരെങ്കിലും അത് സ്വീകരിച്ചുവെങ്കിൽ നല്ല ഓഹരി തന്നെയാണ് അവൻ സ്വീകരിച്ചത്." (ദ,തു,ജ)', 'كَثِيرِ بْنِ قَيْسٍ قال', 'കസീറുബ്നു ഖൈസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 840, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ رَجُلٍ يَسْلُكُ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا إِلَّا سَهَّلَ اللهُ لَهُ بِهِ طَرِيقَ الْجَنَّةِ، وَمَنْ أَبْطَأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ". (م,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിജ്ഞാനം തേടി ആരെങ്കിലും വല്ല വഴിയിൽ പ്രവേശിച്ചാൽ അല്ലാഹു അവന് സ്വർഗ്ഗവഴി എളുപ്പമാക്കിക്കൊടുക്കുക തന്നെ ചെയ്യും. ആരുടെയെങ്കിലും കർമ്മം അവനെ പിന്തിച്ചാൽ അവന്റെ കുടുംബ പാരമ്പര്യം അവനെ ഉപകരിക്കുകയില്ല." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَنَسِ ابْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ خَرَجَ فِي طَلَبِ الْعِلْمِ كَانَ فِي سَبِيلِ اللهِ حَتَّى يَرْجِعَ". حَسَنٌ. (خ)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "വിജ്ഞാനം തേടി ആരെങ്കിലും പുറപ്പെട്ടാൽ തിരിച്ചു വരുന്നതു വരെ അവൻ അല്ലാഹുവിന്റെ മാർഗത്തിലാണ്." (ബു)', 'أَنَسِ ابْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ سَخْبَرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "مَنْ طَلَبَ الْعِلْمَ كَانَ كَفَّارَةً لِمَا مَضَى". (ت)', 'സഖ്ബറ(റ): നബി(സ) പറയുന്നു: "ആരെങ്കിലും വിജ്ഞാനം തേടിയാൽ അത് അവന്റെ കഴിഞ്ഞു പോയ പാപങ്ങൾക്ക് പ്രായശ്ചിത്തമാണ്. (തു)', 'سَخْبَرَةَ', 'സഖ്ബറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي هَارُونَ الْعَبْدِيِّ قال: كُنَّا نَأْتِي أَبَا سَعِيدٍ رَضِيَ اللهُ عَنْهُ فَيَقُولُ: مَرْحَبًا بِوَصِيَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ النَّاسَ لَكُمْ تَبَعٌ، وَإِنَّ رِجَالًا يَأْتُونَكُمْ مِنْ أَقْطَارِ الْأَرَضِينَ يَتَفَقَّهُونَ فِي الدِّينِ، فَإِذَا أَتَوْكُمْ فَاسْتَوْصُوا بِهِمْ خَيْرًا". وَفِي رِوَايَةٍ: "يَأْتِيكُمْ رِجَالٌ مِنْ قِبَلِ الْمَشْرِقِ يَتَعَلَّمُونَ، فَإِذَا جَاءُوكُمْ فَاسْتَوْصُوا بِهِمْ خَيْرًا". (ت,جه)', 'അബൂഹാറൂനുൽ അബ്ദി(റ): ഞങ്ങൾ അബൂസഈദ്(റ)വിന്റെ അരികിൽ പോകാറുണ്ടായിരുന്നു. അപ്പോൾ അദ്ദേഹം പറയും: റസൂൽ(സ)യുടെ വസിയ്യതിന് സ്വാഗതം. നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾ നിങ്ങളെ പിൻപറ്റുന്നവരാണ്. ഭൂമിയുടെ ഭാഗങ്ങളിൽ അവർ മതത്തിലെ വിദ്യ തേടിക്കൊണ്ട് വരും. അവർ നിങ്ങളുടെ അടുത്ത് വന്നാൽ അവർക്ക് നന്മ ഉപദേശിക്കുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=11 and h.hadith_no=18), 1, 'وَفِي رِوَايَةٍ: "يَأْتِيكُمْ رِجَالٌ مِنْ قِبَلِ الْمَشْرِقِ يَتَعَلَّمُونَ، فَإِذَا جَاءُوكُمْ فَاسْتَوْصُوا بِهِمْ خَيْرًا". (ت,جه)', 'മറ്റൊരു നിവേദനം: "വിദ്യ തേടിക്കൊണ്ട് കിഴക്കിൽ നിന്ന് നിങ്ങളിലേക്ക് ആളുകൾ വരും. അവർ നിങ്ങളുടെ അടുത്ത് വന്നാൽ നിങ്ങൾ അവർക്ക് നന്മ ഉപദേശിക്കുക." (തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَعَلَّمَ عِلْمًا مِمَّا يُبْتَغَى بِهِ وَجْهُ اللهِ عَزَّ وَجَلَّ، لَا يَتَعَلَّمُهُ إِلَّا لِيُصِيبَ بِهِ عَرَضًا مِنَ الدُّنْيَا، لَمْ يَجِدْ عَرْفَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ" يَعْنِي رِيحَهَا. (د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ തൃപ്തി തേടപ്പെടേണ്ട വിജ്ഞാനം ആരെങ്കിലും ദുനിയാവിലെ വല്ല വസ്തുവിനും വേണ്ടി തേടിയാൽ അവന് അന്ത്യദിനത്തിൽ സ്വർഗത്തിന്റെ പരിമളം ലഭിക്കുകയില്ല." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قال: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ طَلَبَ الْعِلْمَ لِيُجَارِيَ بِهِ الْعُلَمَاءَ، أَوْ لِيُمَارِيَ بِهِ السُّفَهَاءَ، أَوْ يَصْرِفَ بِهِ وُجُوهَ النَّاسِ إِلَيْهِ، أَدْخَلَهُ اللهُ النَّارَ". (ت)', 'കഅബുബ്നു മാലിക്(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു. "ആരെങ്കിലും പണ്ഡിതരോട് കിടപിടിക്കാനോ വിഡ്ഢികളോട് തർക്കിക്കാനോ അല്ലെങ്കിൽ ജനങ്ങളുടെ മുഖം തന്നിലേക്ക് തിരിക്കാനോ വിദ്യ അഭ്യസിച്ചാൽ അല്ലാഹു അവനെ നരകത്തിൽ പ്രവേശിപ്പിക്കും." (തു)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅബുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "مَنْ تَعَلَّمَ عِلْمًا لِغَيْرِ اللهِ، أَوْ أَرَادَ بِهِ غَيْرَ اللهِ، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് വേണ്ടിയല്ലാതെ ആരെങ്കിലും വിദ്യ തേടിയാൽ അല്ലെങ്കിൽ വിദ്യ കൊണ്ട് അല്ലാഹു അല്ലാത്തത് ആഗ്രഹിച്ചാൽ അവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قال: كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأُتِيَ بِجُمَّارٍ، فَقَالَ: "إِنَّ مِنَ الشَّجَرِ شَجَرَةً". وَذَكَرَ الْحَدِيثَ وَزَادَ فِي هَذِهِ الرِّوَايَةِ: فَإِذَا أَنَا أَصْغَرُ الْقَوْمِ فَسَكَتُّ. (خ)', 'ഇബ്നുഉമർ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ നബി(സ)ക്ക് ഈത്തപ്പഴത്തിന്റെ നെയ്യ് കൊണ്ടുവരപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മരങ്ങളിൽപ്പെട്ടതാണ് ഇന്ന മരം." നിവേദകൻ ഹദീസ് പറഞ്ഞു. ഈ റിപ്പോർട്ടിൽ ഇത് അധികരിപ്പിച്ചിരിക്കുന്നു: ഞാൻ കൂട്ടത്തിൽ ഏറ്റവും ചെറിയവനാണ്. അതു കൊണ്ട് ഞാൻ മൗനം ദീക്ഷിച്ചു. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قال: ضَمَّنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "اللَّهُمَّ عَلِّمْهُ الْكِتَابَ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): എന്നെ നബി(സ) കൂട്ടിപ്പിടിച്ച്കൊണ്ട് പറഞ്ഞു: "അല്ലാഹുവേ, ഇവന് നീ ഗ്രന്ഥം പഠിപ്പിക്കേണമേ." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَبْدِاللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قال: أَقْبَلْتُ رَاكِبًا عَلَى حِمَارٍ أَتَانٍ وَأَنَا يَوْمَئِذٍ قَدْ نَاهَزْتُ الِاحْتِلَامَ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِمِنًى إِلَى غَيْرِ جِدَارٍ، فَمَرَرْتُ بَيْنَ يَدَيْ بَعْضِ الصَّفِّ وَأَرْسَلْتُ الْأَتَانَ تَرْتَعُ فَدَخَلْتُ فِي الصَّفِّ فَلَمْ يُنْكَرْ ذَلِكَ عَلَيَّ. (خ)', 'അബ്ദുല്ലാഹിബ്നുഅബ്ബാസ്(റ): പെൺകഴുതപ്പുറത്ത് യാത്ര ചെയ്ത് ഞാൻ ചെന്നു. ആ ദിവസം ഞാൻ പ്രായപൂർത്തിയോട് അടുത്തിരുന്നു. റസൂൽ(സ) അപ്പോൾ മിനയിൽ വെച്ച് മറയില്ലാതെ നിസ്കരിക്കുകയായിരുന്നു. ഞാൻ കുറച്ചു സ്വഫ്ഫുകളുടെ മുമ്പിലൂടെ നടന്നു. കഴുതയെ മേയാൻ വിട്ടു. എന്നിട്ട് സ്വഫ്ഫിൽ പ്രവേശിച്ചു. റസൂൽ(സ) അത് എന്റെ മേൽ വെറുപ്പായി കണ്ടില്ല. (ബു)', 'عَبْدِاللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 842, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ مَحْمُودِ بْنِ الرَّبِيعِ رَضِيَ اللهُ عَنْهُ قال: عَقَلْتُ مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَجَّةً مَجَّهَا فِي وَجْهِي وَأَنَا ابْنُ خَمْسِ سِنِينَ مِنْ دَلْوٍ. (خ)', 'മഹ്മൂദുബ്നു റബീഅ്(റ): എനിക്ക് അഞ്ച് വയസ്സുള്ളപ്പോൾ തൊട്ടിലിൽ വെച്ച് നബി(സ) അവിടത്തെ ഉമിനീരിൽ നിന്ന് എന്റെ മുഖത്ത് തെളിച്ചത് ഞാനോർക്കുന്നു. (ബു)', 'مَحْمُودِ بْنِ الرَّبِيعِ', 'മഹ്മൂദുബ്നു റബീഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: قُلْتُ يَا رَسُولَ اللهِ مَنْ أَسْعَدُ النَّاسِ بِشَفَاعَتِكَ يَوْمَ الْقِيَامَةِ؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ ظَنَنْتُ يَا أَبَا هُرَيْرَةَ أَنْ لَا يَسْأَلَنِي عَنْ هَذَا الْحَدِيثِ أَحَدٌ أَوَّلُ مِنْكَ لِمَا رَأَيْتُ مِنْ حِرْصِكَ عَلَى الْحَدِيثِ، أَسْعَدُ النَّاسِ بِشَفَاعَتِي يَوْمَ الْقِيَامَةِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ خَالِصًا مِنْ قَلْبِهِ أَوْ نَفْسِهِ". (خ)', 'അബൂഹുറൈറ(റ): ഞാൻ റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, അന്ത്യനാളിൽ അങ്ങയുടെ ശിപാർശകൊണ്ട് ഏറ്റവും വലിയ വിജയം കൈവരിക്കുന്നവനാരാണ്? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്നിൽ ഹദീസിനോടുള്ള സ്നേഹം കണ്ട കാരണത്താൽ ഈ വിഷയത്തെ കുറിച്ച് നിന്റെ മുമ്പ് ആരും ചോദിക്കില്ലെന്ന് അബൂഹുറൈറൊ, ഞാൻ വിചാരിച്ചിരുന്നു. അന്ത്യ ദിനത്തിൽ എന്റെ ശഫാഅത്തു കൊണ്ട് ഏറ്റവും വലിയ വിജയം കൈവരിച്ചവൻ ലാഇലാഹ ഇല്ലല്ലാഹു എന്ന് ഹൃദയത്തിൽ നിഷ്കളങ്കമായി പറഞ്ഞവനാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: مَنْ حُوسِبَ عُذِّبَ، قَالَتْ عَائِشَةُ: فَقُلْتُ: أَوَلَيْسَ يَقُولُ اللهُ عَزَّ وَجَلَّ {فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا} فَقَالَ: إِنَّمَا ذَلِكَ الْعَرْضُ وَلَكِنْ مَنْ نُوقِشَ الْحِسَابَ يَهْلِكْ. (خ)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "വിചാരണ ചെയ്യപ്പെടുന്നവൻ ശിക്ഷിക്കപ്പെടും." ആഇശ(റ) പറയുന്നു: അപ്പോൾ ഞാൻ ചോദിച്ചു: അല്ലാഹു പറയുന്നില്ലേ ''അപ്പോൾ അവൻ നിസ്സാരമായ വിചാരണ ചെയ്യപ്പെടും'' എന്ന്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇത് വെളിപ്പെടുത്തൽ മാത്രമാണ്. പക്ഷേ, വിചാരണയിൽ ആരോടെങ്കിലും തർക്കിക്കപ്പെട്ടാൽ അവൻ നശിക്കും." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: إِنَّ النَّاسَ يَقُولُونَ أَكْثَرَ أَبُو هُرَيْرَةَ وَلَوْلَا آيَتَانِ فِي كِتَابِ اللهِ مَا حَدَّثْتُ حَدِيثًا، ثُمَّ يَتْلُو {إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى} إِلَى قَوْلِهِ {الرَّحِيمُ} إِنَّ إِخْوَانَنَا مِنَ الْمُهَاجِرِينَ كَانَ يَشْغَلُهُمُ الصَّفْقُ بِالْأَسْوَاقِ، وَإِنَّ إِخْوَانَنَا مِنَ الْأَنْصَارِ كَانَ يَشْغَلُهُمُ الْعَمَلُ فِي أَمْوَالِهِمْ، وَإِنَّ أَبَا هُرَيْرَةَ كَانَ يَلْزَمُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِشِبَعِ بَطْنِهِ، وَيَحْضُرُ مَا لَا يَحْضُرُونَ وَيَحْفَظُ مَا لَا يَحْفَظُونَ. (خ)', 'അബൂഹുറൈറ(റ): ജനങ്ങൾ പറയുന്നു: അബൂഹുറൈറ(റ) ഒരുപാട് ഹദീസുകൾ ഹൃദിസ്ഥമാക്കിയിരിക്കുന്നു. അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലെ രണ്ട് സൂക്തങ്ങളില്ലായിരുന്നുവെങ്കിൽ ഞാൻ ഒരു ഹദീസും പറയുമായിരുന്നില്ല. പിന്നെ അദ്ദേഹം ഓതാൻ തുടങ്ങി: ''സൻമാർഗത്താലും വ്യക്തമായ ദൃഷ്ടാന്തങ്ങളാലും നാം ഇറക്കിയത് മറച്ചു വെക്കുന്നവർ....................റഹീം'' എന്നത് വരെ. മുഹാജിറുകളായ നമ്മുടെ സഹോദരങ്ങളെ അങ്ങാടിയിലെ കച്ചവടം വ്യാപൃതരാക്കിയിരിക്കുന്നു. അൻസാറുകളെ അവരുടെ സമ്പത്തിൽ വ്യാപൃതരാക്കിയിരിക്കുന്നു. അബൂഹുറൈറ വയർ നിറയാൻ എപ്പോഴും റസൂലിന്റെ കൂടെയുണ്ടാകുമായിരുന്നു. അവർ സന്നിഹിതരാകാത്തിടത്തൊക്കെ അദ്ദേഹം സന്നിഹിതനായിരുന്നു. അവർ ഹൃദിസ്ഥമാക്കാത്തത് അദ്ദേഹം ഹൃദിസ്ഥമാക്കിയിരുന്നു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 843, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: قُلْتُ: يَا رَسُولَ اللهِ إِنِّي أَسْمَعُ مِنْكَ حَدِيثًا كَثِيرًا أَنْسَاهُ، قَالَ: ابْسُطْ رِدَاءَكَ فَبَسَطْتُهُ، قَالَ فَغَرَفَ بِيَدَيْهِ ثُمَّ قَالَ ضُمَّهُ فَضَمَمْتُهُ، فَمَا نَسِيتُ شَيْئًا بَعْدَهُ. (خ)', 'അബൂഹുറൈറ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകരെ, ഞാൻ അങ്ങയിൽ നിന്ന് ഒരുപാട് ഹദീസ് കേട്ട് മറന്നു പോകുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ വിരിപ്പ് വിരിക്കുക." ഞാനത് വിരിച്ചു. റസൂൽ(സ) അവിടത്തെ രണ്ട് കരങ്ങൾ കൊണ്ടത് പിടിച്ചു. പിന്നെ അവിടന്ന് പറഞ്ഞു: "നീ അത് ചേർത്തു പിടിക്കുക." അപ്പോൾ ഞാനത് ചേർത്തു പിടിച്ചു. പിന്നീട് ഞാനൊന്നും മറന്നിട്ടില്ല. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: حَفِظْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وِعَاءَيْنِ، فَأَمَّا أَحَدُهُمَا فَبَثَثْتُهُ، وَأَمَّا الْآخَرُ فَلَوْ بَثَثْتُهُ قُطِعَ هَذَا الْبُلْعُومُ. (خ)', 'അബൂഹുറൈറ(റ): ഞാൻ നബി(സ)യിൽ നിന്ന് രണ്ട് പാത്രം വിജ്ഞാനങ്ങൾ ഹൃദിസ്ഥമാക്കി. അതിലൊന്ന് ഞാൻ പരസ്യം ചെയ്തു. മറ്റേത് പരസ്യമാക്കിയാൽ ഈ കണ്ഠനാളം ഛേദിക്കപ്പെടും. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عُرْوَةَ قال: جَلَسَ أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ إِلَى جَنْبِ حُجْرَةِ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، وَهِيَ تُصَلِّي، فَجَعَلَ يَقُولُ: اسْمَعِي يَا رَبَّةَ الْحُجْرَةِ، مَرَّتَيْنِ، فَلَمَّا قَضَتْ صَلَاتَهَا قَالَتْ: أَلَا تَعْجَبُ إِلَى هَذَا وَحَدِيثِهِ، إِنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيُحَدِّثُ الْحَدِيثَ لَوْ شَاءَ الْعَادُّ أَنْ يُحْصِيَهُ أَحْصَاهُ. (ق,د)', 'ഉർവ്വ(റ): അബൂഹുറൈറ(റ) ആഇശ(റ)യുടെ റൂമിന്റെ ഭാഗത്ത് ഇരുന്നു. ആഇശ(റ) അപ്പോൾ നിസ്കരിക്കുകയായിരുന്നു. റൂമിൽ വസിക്കുന്നവരേ, എന്ന് അബൂഹുറൈറ(റ) രണ്ട് പ്രാവശ്യം വിളിച്ചു. ആഇശ(റ) നമസ്കാരം കഴിഞ്ഞപ്പോൾ പറഞ്ഞു: ഇദ്ദേഹത്തോടും ഇദ്ദേഹത്തിന്റെ ഹദീസിനോടും നിങ്ങൾക്ക് അത്ഭുതം തോന്നുന്നില്ലേ. റസൂൽ(സ)യാണ് ഹദീസ് ഉദ്ധരിക്കുന്നതെങ്കിൽ എണ്ണിത്തിട്ടപ്പെടുത്തുന്നയാൾക്ക് അവനുദ്ദേശിച്ചാൽ ക്ലിപ്തപ്പെടുത്താമായിരുന്നു. (ബു,മു,ദ)', 'عُرْوَةَ قال', 'ഉർവ്വ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ: أَنَّ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَلَا يُعْجِبُكَ أَبُو هُرَيْرَةَ؟ جَاءَ فَجَلَسَ إِلَى جَانِبِ حُجْرَتِي يُحَدِّثُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يُسْمِعُنِي ذَلِكَ، وَكُنْتُ أُسَبِّحُ، فَقَامَ قَبْلَ أَنْ أَقْضِيَ سُبْحَتِي، وَلَوْ أَدْرَكْتُهُ لَرَدَدْتُ عَلَيْهِ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ يَسْرُدُ الْحَدِيثَ مِثْلَ سَرْدِكُمْ. (م,د,ت)', 'ഉർവ്വ(റ): ആഇശ(റ) പറഞ്ഞു: അബൂഹുറൈറ(റ) നിങ്ങളെ അത്ഭുതപ്പെടുത്തുന്നില്ലേ. അദ്ദേഹം വന്ന് എന്റെ റൂമിന്റെ ഭാഗത്ത് ഇരുന്ന് റസൂൽ(സ)യിൽ നിന്നുള്ള ഹദീസ് പറഞ്ഞ് എന്നെ കേൾപ്പിച്ചുകൊണ്ടിരുന്നു. ഞാൻ നിസ്കരിക്കുകയായിരുന്നു. എന്റെ നിസ്കാരത്തിനു മുമ്പ് അദ്ദേഹം എണീറ്റ് പോയി. ഞാനദ്ദേഹത്തെ കണ്ടിരുന്നെങ്കിൽ മറുപടി നൽകുമായിരുന്നു. നിങ്ങൾ ഹദീസ് പറയുന്നത് പോലെ റസൂൽ(സ) ഹദീസ് പറയുമായിരുന്നില്ല. (മു,ദ,തു)', 'عُرْوَةَ بْنِ الزُّبَيْرِ', 'ഉർവ്വ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 844, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: أَتَيْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا وَهِيَ تُصَلِّي، فَقُلْتُ مَا شَأْنُ النَّاسِ فَأَشَارَتْ إِلَى السَّمَاءِ، فَإِذَا النَّاسُ قِيَامٌ فَقَالَتْ: سُبْحَانَ اللهِ! قُلْتُ: آيَةٌ؟ فَأَشَارَتْ بِرَأْسِهَا، أَيْ نَعَمْ، فَقُمْتُ، حَتَّى عَلَانِي الْغَشْيُ، فَجَعَلْتُ أَصُبُّ عَلَى رَأْسِي الْمَاءَ فَحَمِدَ اللهَ عَزَّ وَجَلَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "مَا مِنْ شَيْءٍ لَمْ أَكُنْ أُرِيتُهُ إِلَّا رَأَيْتُهُ فِي مَقَامِي حَتَّى الْجَنَّةَ وَالنَّارَ فَأُوحِيَ إِلَيَّ أَنَّكُمْ تُفْتَنُونَ فِي قُبُورِكُمْ مِثْلَ أَوْ قَرِيبًا مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ يُقَالُ: مَا عِلْمُكَ بِهَذَا الرَّجُلِ؟ فَأَمَّا الْمُؤْمِنُ أَوِ الْمُوقِنُ، فَيَقُولُ: هُوَ مُحَمَّدٌ رَسُولُ اللهِ جَاءَنَا بِالْبَيِّنَاتِ وَالْهُدَى، فَأَجَبْنَا وَاتَّبَعْنَا هُوَ مُحَمَّدٌ ثَلَاثًا، فَيُقَالُ: نَمْ صَالِحًا قَدْ عَلِمْنَا إِنْ كُنْتَ لَمُوقِنًا بِهِ، وَأَمَّا الْمُنَافِقُ أَوِ الْمُرْتَابُ فَيَقُولُ: لَا أَدْرِي سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُهُ". (خ)', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ): അവർ പറഞ്ഞു: ആഇശ(റ) നിസ്കരിച്ചുകൊണ്ടിരിക്കെ ഞാൻ അവരുടെ അടുത്ത് പോയി. ഞാൻ ചോദിച്ചു: എന്താണ് ജനങ്ങളുടെ അവസ്ഥ? ആഇശബീവി(റ) ആകാശത്തേക്ക് ആംഗ്യം കാണിച്ചു. അപ്പോൾ ജനങ്ങൾ നിസ്കരിക്കുകയായിരുന്നു. ആഇശ(റ) പറഞ്ഞു: സുബ്ഹാനല്ലാഹ്. ഞാൻ ചോദിച്ചു: വല്ല ദൈവ ദൃഷ്ടാന്തവുമാണോ? അതെ, എന്ന് സൂചിപ്പിച്ച് അവർ തലയാട്ടി. ഉടനെ ഞാനും നമസ്കാരത്തിൽ പ്രവേശിച്ചു. അങ്ങനെ എനിക്ക് തളർച്ച ബാധിച്ചു. വെള്ളമെടുത്ത് ഞാൻ എന്റെ തലയിൽ വീഴ്ത്തി. പിന്നീട് റസൂൽ(സ) പ്രസംഗമാരംഭിച്ചുകൊണ്ട് അല്ലാഹുവിനെ സ്തുതിച്ചു. നബി(സ) പറഞ്ഞു: "ഇതിനു മുമ്പ് എനിക്ക് കാണിച്ചു തന്നിട്ടില്ലാത്ത ഒരു വസ്തുവിനെയും എന്റെ ഈ നിൽപ്പിൽ ഞാൻ കാണാതിരുന്നിട്ടില്ല. സ്വർഗം, നരകം എന്നിവ കൂടി ഇവിടെ വെച്ച് ഞാൻ കണ്ടു. എനിക്ക് അല്ലാഹുവിങ്കൽ നിന്ന് ഇങ്ങനെ സന്ദേശം ലഭിച്ചു. നിങ്ങൾ ഖബറുകളിൽ വെച്ച് പരീക്ഷണ വിധേയരാകും. ദജ്ജാലിന്റെ പരീക്ഷണങ്ങൾ പോലെ, അല്ലെങ്കിൽ അതിനോടടുത്തത്. എന്നിട്ട് ഈ മനുഷ്യനെക്കുറിച്ചുള്ള (മുഹമ്മദ് നബി(സ)യെക്കുറിച്ചുള്ള) നിന്റെ അറിവെന്താണെന്ന് ചോദിക്കപ്പെടും. വിശ്വാസി അല്ലെങ്കിൽ ദൃഢവിശ്വാസി പറയും: ഇത് ഞങ്ങൾക്ക് വ്യക്തമായ ദൃഷ്ടാന്തങ്ങളും സൻമാർഗവും കൊണ്ട് വന്ന അല്ലാഹുവിന്റെ ദൂതരായ മുഹമ്മദ് നബി(സ)യാണ്. ഞങ്ങൾ അവർക്ക് ഉത്തരം നൽകി. അവരെ പിൻപറ്റി. ഇത് മുഹമ്മദ് നബി(സ) തന്നെയാണ്. അവർ മൂന്ന് പ്രാവശ്യം പറയും. അപ്പോൾ അദ്ദേഹത്തോട് പറയപ്പെടും: നീ സുഖമായി ഉറങ്ങിക്കൊള്ളുക. നീ ഇവരിൽ ദൃഢമായി വിശ്വസിച്ചവരായിരുന്നെന്ന് ഞങ്ങൾക്കറിവുണ്ട്. കപടവിശ്വാസിയും സംശയാലുവും പറയും. എനിക്കറിയില്ല. ജനങ്ങളെന്തോ പറയുന്നത് ഞാൻ കേട്ടു. അപ്പോൾ ഞാനും അത് പറഞ്ഞു." (ബു)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 845, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ -رَفَعَهُ- قال: "لَا أُلْفِيَنَّ أَحَدَكُمْ مُتَّكِئًا عَلَى أَرِيكَتِهِ، يَأْتِيهِ أَمْرٌ مِمَّا أَمَرْتُ بِهِ أَوْ نَهَيْتُ عَنْهُ، فَيَقُولُ: لَا أَدْرِي، مَا وَجَدْنَا فِي كِتَابِ اللهِ اتَّبَعْنَاهُ". حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'അബൂറാഫിഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങളിലൊരുത്തനെ ആഡംബര കസേരയിൽ ചാഞ്ഞിരിക്കുന്നവനായി കണ്ടുമുട്ടരുത്. ഞാൻ കൽപ്പിച്ചതും ഞാൻ വിരോധിച്ചതും അവന് വന്നെത്തും. അപ്പോൾ അവൻ പറയും. എനിക്കറിയില്ല. അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ കണ്ടത് ഞങ്ങൾ പിൻപറ്റും." (ദ,തു,ജ)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 845, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا هَلْ عَسَى رَجُلٌ يَبْلُغُهُ الْحَدِيثُ عَنِّي، وَهُوَ مُتَّكِئٌ عَلَى أَرِيكَتِهِ، فَيَقُولُ: بَيْنَنَا وَبَيْنَكُمْ كِتَابُ اللهِ، فَمَا وَجَدْنَا فِيهِ حَلَالًا اسْتَحْلَلْنَاهُ، وَمَا وَجَدْنَا فِيهِ حَرَامًا حَرَّمْنَاهُ، وَإِنَّ مَا حَرَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَمَا حَرَّمَ اللهُ". حَسَنٌ. (د,ت,جه)', 'മിഖ്ദാദുബ്നു മഅ്ദീ കരിബ(റ): റസൂൽ(സ) പറഞ്ഞു: "അറിയുക, ഒരാൾക്ക് എന്നിൽ നിന്നുള്ള ഹദീസ് വന്നേക്കാം. അവൻ തന്റെ ചാരു കസേരയിൽ ചാരി ഇരിക്കുന്നുണ്ടാകും. അവൻ പറയും: നിങ്ങൾക്കും ഞങ്ങൾക്കുമിടയിൽ അല്ലാഹുവിന്റെ ഗ്രന്ഥമുണ്ട്. അതിൽ ഞങ്ങൾ അനുവദനീയമായിക്കണ്ടത് ഞങ്ങൾ അനുവദനീയമാക്കും. അതിൽ നിഷിദ്ധമായിക്കണ്ടത് ഞങ്ങൾ നിഷിദ്ധമാക്കും. അറിയുക, റസൂൽ(സ) നിഷിദ്ധമാക്കിയത് അല്ലാഹു നിഷിദ്ധമാക്കിയത് പോലെയാണ്." (ദ,തു,ജ)', 'الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ', 'മിഖ്ദാദുബ്നു മഅ്ദീ കരിബ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 846, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "إِنَّ اللهَ حَبَسَ عَنْ مَكَّةَ الْقَتْلَ أَوِ الْفِيلَ وَسَلَّطَ عَلَيْهِمْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالْمُؤْمِنِينَ أَلَا وَإِنَّهَا لَمْ تَحِلَّ لِأَحَدٍ قَبْلِي وَلَمْ تَحِلَّ لِأَحَدٍ بَعْدِي أَلَا وَإِنَّهَا حَلَّتْ لِي سَاعَةً مِنْ نَهَارٍ أَلَا وَإِنَّهَا سَاعَتِي هَذِهِ حَرَامٌ لَا يُخْتَلَى شَوْكُهَا وَلَا يُعْضَدُ شَجَرُهَا وَلَا تُلْتَقَطُ سَاقِطَتُهَا إِلَّا لِمُنْشِدٍ فَمَنْ قُتِلَ فَهُوَ بِخَيْرِ النَّظَرَيْنِ إِمَّا أَنْ يُعْقَلَ وَإِمَّا أَنْ يُقَادَ أَهْلُ الْقَتِيلِ". فَجَاءَ رَجُلٌ مِنْ أَهْلِ الْيَمَنِ فَقَالَ: اكْتُبْ لِي يَا رَسُولَ اللهِ، فَقَالَ: "اكْتُبُوا لِأَبِي فُلَانٍ". فَقَالَ رَجُلٌ مِنْ قُرَيْشٍ: إِلَّا الْإِذْخِرَ يَا رَسُولَ اللهِ فَإِنَّا نَجْعَلُهُ فِي بُيُوتِنَا وَقُبُورِنَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِلَّا الْإِذْخِرَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മക്കയിൽ നിന്ന് കൊലയെ അല്ലെങ്കിൽ ആനയെ, അല്ലാഹു തടഞ്ഞു നിർത്തിയിരിക്കുകയാണ്. നബി(സ)യും സത്യവിശ്വാസികളും മക്കയെ ജയിച്ചടക്കിയിരിക്കുന്നു. നിങ്ങളറിയണം. മക്കയെ അനാദരിക്കാൻ മുമ്പ് ആരെയും അനുവദിച്ചിട്ടില്ല. എന്റെ ശേഷവും ആരെയും അനുവദിക്കുകയില്ല. നിങ്ങൾ ഓർക്കണം. പകൽ ഒരു നാഴിക നേരം മാത്രമാണ് അല്ലാഹു എനിക്ക് മക്കയിൽ യുദ്ധം ചെയ്യാൻ അനുവദിച്ചത്. നിങ്ങളോർക്കണം ഈ സമയത്ത് മക്ക ആദരണീയം തന്നെയാണ്. മക്കയിലെ ഒരു ചെടിയിൽ നിന്ന് മുള്ള് പൊട്ടിച്ചെടുക്കാനോ വൃക്ഷം മുറിക്കാനോ പാടില്ല. വീണുകിട്ടിയ വസ്തു മറ്റുള്ളവരെ അറിയിക്കാൻ വേണ്ടിയല്ലാതെ, ആരും എടുക്കാൻ പാടില്ല. അപ്പോൾ വല്ലവനും (മക്കയിൽ വെച്ച്) വധിക്കപ്പെട്ടാൽ അവന്റെ അവകാശികൾക്ക് രണ്ടിൽ ഉത്തമമെന്നു തോന്നുന്ന ഒരു മാർഗം സ്വീകരിക്കാം. ഒന്നുകിൽ നഷ്ട പരിഹാരം വാങ്ങുക. അല്ലെങ്കിൽ ശിക്ഷാ നടപടികളെടുക്കുക. അപ്പോൾ യമൻകാരനായ ഒരു മനുഷ്യൻ വന്നു അപേക്ഷിച്ചു: ഇപ്പറഞ്ഞ വിധികൾ എനിക്ക് എഴുതിത്തന്നാലും. "ഇന്നവന് അത് എഴുതിക്കൊടുക്കുക." എന്ന് നബി(സ) പറഞ്ഞു. അപ്പോൾ ഖുറൈശികളിൽ പെട്ട ഒരാൾ നബി(സ)യോട് അപേക്ഷിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഇദ്ഖർ (ഒരുതരം പുല്ല്) ഒഴിവാക്കിയാൽ കൊള്ളാം. അതുകൊണ്ട് ഞങ്ങൾ പുര മേയുകയും അത് ഖബറുകളിൽ വെക്കുകയും ചെയ്യാറുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇദ്ഖർ ഒഴികെ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 846, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قال: لَمَّا اشْتَدَّ بِالنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَجَعُهُ قَالَ: "ائْتُونِي بِكِتَابٍ أَكْتُبْ لَكُمْ كِتَابًا لَا تَضِلُّوا بَعْدَهُ". قَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَلَبَهُ الْوَجَعُ وَعِنْدَنَا كِتَابُ اللهِ حَسْبُنَا، فَاخْتَلَفُوا وَكَثُرَ اللَّغَطُ، فَقَالَ: "قُومُوا عَنِّي، وَلَا يَنْبَغِي عِنْدِي التَّنَازُعُ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): മരണ വേദന വർദ്ധിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ എഴുതാനുള്ള ഗ്രന്ഥം കൊണ്ടു വരിക. ഞാൻ നിങ്ങൾക്ക് ചിലത് എഴുതിത്തരാം. അതിനു ശേഷം നിങ്ങൾക്ക് പിഴക്കില്ല." ഉമർ(റ) പറഞ്ഞു: നബി(സ) വേദന മൂലം അവശനായിരിക്കുന്നു. നമ്മുടെ അടുക്കൽ അല്ലാഹുവിന്റെ കിതാബുണ്ട്. നമുക്കത് മതി. അന്നേരം നബി(സ)യുടെ അനുചരർ അഭിപ്രായഭിന്നരായി. ശബ്ദ കോലാഹലങ്ങൾ പുറപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഇവിടം വിട്ടു പോവുക. എന്റെ മുമ്പിൽ വെച്ച് തർക്കിക്കുന്നത് ശരിയല്ല." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "لَا تَكْتُبُوا عَنِّي، وَمَنْ كَتَبَ عَنِّي غَيْرَ الْقُرْآنِ فَلْيَحْمِلْهُ، وَحَدِّثُوا عَنِّي وَ لَا حَرَجَ، وَمَنْ كَذَبَ عَلَيَّ -قَالَ هَمَّامٌ: أَحْسِبُهُ قَالَ- مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (م)', 'അബൂസഈദുൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്നെക്കുറിച്ചെഴുതരുത്. വല്ലവനും ഖുർആനല്ലാതെ എന്നെക്കുറിച്ചെഴുതിയാൽ അവൻ മായ്ച്ചുകളയട്ടെ. നിങ്ങൾ എന്നിൽ നിന്ന് ഹദീസ് ഉദ്ധരിക്കുക. അതിൽ വിരോധമില്ല. ആരെങ്കിലും മനപ്പൂർവ്വം - ഹുമാം(റ) പറയുന്നു: റസൂൽ(സ) അങ്ങനെ പറഞ്ഞുവെന്ന് ഞാൻ കരുതുന്നു - എന്റെ മേൽ കളവ് പറഞ്ഞാൽ അവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ زَيْدِ ابْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ: دَخَلَ عَلَى مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ فَسَأَلَهُ عَنْ حَدِيثٍ، فَأَمَرَ إِنْسَانًا يَكْتُبُهُ، فَقَالَ لَهُ زَيْدٌ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَنَا أَنْ لَا نَكْتُبَ شَيْئًا مِنْ حَدِيثِهِ، فَمَحَاهُ. (د)', 'സൈദുബ്നു സാബിത്(റ): അദ്ദേഹം മുആവിയ(റ)യുടെ അടുത്ത് വന്ന് ഹദീസിനെക്കുറിച്ച് ചോദിച്ചു. മുആവിയ(റ) അത് ഒരാളോട് എഴുതാൻ പറഞ്ഞു. അദ്ദേഹത്തോട് സൈദ് (റ) പറഞ്ഞു: റസൂൽ(സ) ഞങ്ങളോട് അവിടത്തെ ഹദീസിൽ നിന്ന് ഒന്നും എഴുതരുതെന്ന് കൽപ്പിച്ചിട്ടുണ്ട്. അപ്പോൾ അത് മായ്ച്ചുകളഞ്ഞു. (ദ)', 'زَيْدِ ابْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قال: مَا كُنَّا نَكْتُبُ غَيْرَ التَّشَهُّدِ وَالْقُرْآنِ. (م,د,ت)', 'അബൂസഈദുൽഖുദ്രി(റ): ഖുർആനും തശഹ്ഹുദും(അത്തഹിയ്യാത്) അല്ലാത്തത് ഞങ്ങൾ എഴുതാറുണ്ടായിരുന്നില്ല. (മു,ദ,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽഖുദ്രി(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قال: اسْتَأْذَنَّا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْكِتَابَةِ، فَلَمْ يَأْذَنْ لَنَا. (د,ت)', 'അബൂസഈദുൽ ഖുദ്രി(റ): ഞങ്ങൾ നബി(സ)യോട് എഴുതാൻ സമ്മതം ചോദിച്ചു. നബി(സ) ഞങ്ങൾക്ക് സമ്മതം തന്നില്ല. (ദ,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قال: كُنْتُ أَكْتُبُ كُلَّ شَيْءٍ أَسْمَعُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُرِيدُ حِفْظَهُ، فَنَهَتْنِي قُرَيْشٌ، وَقَالُوا: أَتَكْتُبُ كُلَّ شَيْءٍ تَسْمَعُهُ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَشَرٌ يَتَكَلَّمُ فِي الْغَضَبِ وَالرِّضَا؟ فَأَمْسَكْتُ عَنِ الْكِتَابِ، فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَوْمَأَ بِأُصْبُعِهِ إِلَى فِيهِ فَقَالَ: "اكْتُبْ، فَوَالَّذِي نَفْسِي بِيَدِهِ مَا يَخْرُجُ مِنْهُ إِلَّا حَقٌّ". (د)', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ): ഞാൻ നബി(സ)യിൽ നിന്ന് കേൾക്കുന്നതെല്ലാം ഹൃദിസ്ഥമാക്കുക എന്ന ഉദ്ദേശ്യത്തോടെ എഴുതിവെക്കാറുണ്ടായിരുന്നു. ഖുറൈശികൾ അത് വിരോധിച്ചു. അവർ പറഞ്ഞു: മുഹമ്മദ് നബി(സ)യിൽ നിന്ന് കേൾക്കുന്നതെല്ലാം നീ എഴുതി വെക്കുകയാണോ? റസൂൽ(സ) മനുഷ്യനാണ്, തൃപ്തിയിലും ദേഷ്യത്തിലും സംസാരിക്കും. അപ്പോൾ ഞാൻ എഴുത്ത് നിർത്തി. ഇത് നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ നബി(സ) അവിടത്തെ വിരൽ കൊണ്ട് വായിലേക്ക് ആംഗ്യം കാണിച്ചുകൊണ്ട് പറഞ്ഞു. "നീ എഴുതിക്കൊള്ളുക. എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം! അതിൽ നിന്ന് സത്യമല്ലാതെ ഒന്നും പുറത്ത് വരില്ല." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 847, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: لَمَّا فُتِحَتْ مَكَّةُ قَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ الْخُطْبَةَ خُطْبَةَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: فَقَامَ رَجُلٌ مِنْ أَهْلِ الْيَمَنِ يُقَالُ لَهُ أَبُو شَاهَ، فَقَالَ: يَا رَسُولَ اللهِ، اكْتُبُوا لِي فَقَالَ: "اكْتُبُوا لِأَبِي شَاهَ". قِيلَ لِأَبِي عَمْرٍو الْأَوْزَاعِيِّ: مَا يَكْتُبُوهُ؟ قَالَ: الْخُطْبَةُ الَّتِي سَمِعَهَا يَوْمَئِذٍ مِنْهُ. (خ,د,ت)', 'അബൂഹുറൈറ(റ): മക്ക ജയിച്ചടക്കിയപ്പോൾ നബി(സ) എഴുന്നേറ്റ് നിന്നു. നബി(സ) അവിടത്തെ പ്രസംഗം നിർവ്വഹിച്ചു. യമൻ കാരനായ അബൂശാഹ് എന്നു പേരുള്ള ഒരാൾ എണീറ്റു കൊണ്ട് അപേക്ഷിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, എനിക്കെഴുതിത്തന്നാലും. നബി(സ) പറഞ്ഞു: "അബൂ ശാഹിക്ക് നിങ്ങൾ എഴുതിക്കൊടുക്കുക." അബൂഅംരിൽഔസാഈ(റ)വിനോട് ചോദിക്കപ്പെട്ടു: എന്താണ് എഴുതേണ്ടിയിരുന്നത്. അദ്ദേഹം പറഞ്ഞു: ആ ദിവസം നബി(സ)യിൽ നിന്ന് കേട്ട പ്രസംഗം. (ബു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: كَانَ رَجُلٌ مِنَ الْأَنْصَارِ يَجْلِسُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَيَسْمَعُ مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْحَدِيثَ فَيُعْجِبُهُ وَلَا يَحْفَظُهُ، فَشَكَا ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي أَسْمَعُ مِنْكَ الْحَدِيثَ فَيُعْجِبُنِي وَلَا أَحْفَظُهُ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْتَعِنْ بِيَمِينِكَ" وَأَوْمَأَ بِيَدِهِ لِلْخَطِّ. (ت)', 'അബൂഹുറൈറ(റ): അൻസാറുകളിൽ പെട്ട ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്നിരുന്ന് നബി(സ)യിൽ നിന്ന് ഹദീസ് കേൾക്കുമായിരുന്നു. അദ്ദേഹത്തിനെ ഹദീസ് സന്തോഷിപ്പിക്കുന്നു. പക്ഷേ അത് ഹൃദിസ്ഥമാക്കാൻ സാധിക്കുന്നില്ല. നബി(സ)യോട് വേവലാതി പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ഹദീസ് കേൾക്കുന്നു. അത് എന്നെ സന്തോഷിപ്പിക്കുന്നു. എനിക്കത് ഹൃദിസ്ഥമാക്കാൻ കഴിയുന്നില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ വലത് കൊണ്ട് നീ സഹായം തേടുക." നബി(സ) അവിടത്തെ കൈകൊണ്ട് എഴുതാൻ ആംഗ്യം കാണിച്ചു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قال: لَيْسَ أَحَدٌ مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَكْثَرَ حَدِيثًا عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنِّي، إِلَّا عَبْدَ اللهِ بْنَ عَمْرٍو، فَإِنَّهُ كَانَ يَكْتُبُ وَكُنْتُ لَا أَكْتُبُ. حَسَنٌ صَحِيحٌ. (خ,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)യുടെ അനുചരരിൽ അബ്ദുല്ലാഹിബ്നു അംറ്(റ)വിന് ശേഷം എന്നേക്കാൾ ഹദീസ് അറിയുന്ന ആരുമില്ല. അദ്ദേഹം എഴുതുമായിരുന്നു. ഞാൻ എഴുതുമായരുന്നില്ല. (ബു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ إِذَا تَكَلَّمَ بِكَلِمَةٍ أَعَادَهَا ثَلَاثًا حَتَّى تُفْهَمَ عَنْهُ وَإِذَا أَتَى عَلَى قَوْمٍ فَسَلَّمَ عَلَيْهِمْ سَلَّمَ عَلَيْهِمْ ثَلَاثًا. (خ,د)', 'അനസ്(റ): നബി(സ) ഒരു വാക്ക് പറഞ്ഞാൽ അത് മൂന്ന് പ്രാവശ്യം ആവർത്തിക്കും, അത് മനസ്സിലാക്കുന്നത് വരെ. നബി(സ) ഒരു സമൂഹത്തിന്റെ അടുത്ത് പോയി സലാം പറഞ്ഞാൽ മൂന്ന് പ്രാവശ്യം സലാം പറയും. (ബു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 849, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قال: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: "لَا تَكْذِبُوا عَلَيَّ فَإِنَّهُ مَنْ كَذَبَ عَلَيَّ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (خ)', 'അലി(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "നിങ്ങൾ എന്റെ മേൽ കളവ് പറയരുത്. ആരെങ്കിലും എന്റെ മേൽ കളവ് പറഞ്ഞാൽ അവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ബു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 849, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قال: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ يَقُلْ عَلَيَّ مَا لَمْ أَقُلْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (خ)', 'സലമതുബ്നു അക്വഅ്(റ): ഞാൻ റസൂൽ(സ) പറയുന്നതായി കേട്ടു: "ഞാൻ പറയാത്തത് ഞാൻ പറഞ്ഞു എന്ന് പറഞ്ഞവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ബു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നു അക്വഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 849, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "تَسَمَّوْا بِاسْمِي وَلَا تَكْتَنُوا بِكُنْيَتِي وَمَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ فِي صُورَتِي وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ എന്റെ പേര് ഇടുക, എന്റെ ഓമനപ്പേര് ഇടരുത്. ആരെങ്കിലും എന്നെ സ്വപ്നത്തിൽ കണ്ടാൽ നിശ്ചയം അവൻ എന്നെ കണ്ടു. നിശ്ചയം പിശാച് എന്റെ രൂപം പ്രാപിക്കുകയില്ല. ആരെങ്കിലും മനഃപ്പൂർവം എന്റെ മേൽ കളവ് പറഞ്ഞാൽ അവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 849, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قال: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: "إِنَّ كَذِبًا عَلَيَّ لَيْسَ كَكَذِبٍ عَلَى أَحَدٍ، فَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (م)', 'മുഈറതുബ്നുശുഅ്ബ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "എന്റെ മേലിലുള്ള കളവ് മറ്റാരുടെ മേലിലുമുള്ള കളവ് പോലെയല്ല. അത്കൊണ്ട് മനപ്പൂർവം എന്റെ മേൽ കളവ് പറഞ്ഞവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം തയ്യാറാകിക്കൊള്ളട്ടെ." (മു)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഈറതുബ്നുശുഅ്ബ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 849, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ وَعَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُمَا قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَدَّثَ عَنِّي بِحَدِيثٍ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبِينَ". (ق,ت,جه)', 'സമുറത്തുബ്നു ജുൻദുബ്(റ), മുഗീറത്തുബ്നു ശുഅ്ബ(റ): റസൂൽ(സ) പറഞ്ഞു: "കളവാണെന്ന് അറിഞ്ഞ്കൊണ്ട് എന്നിൽ നിന്ന് ആരെങ്കിലും ഒരു ഹദീസ് ഉദ്ധരിച്ചാൽ അവൻ കളവ് പറയുന്നവരിൽ ഒരാളാണ്." (ബു,മു,തു,ജ)', 'سَمُرَةَ بْنِ جُنْدُبٍ وَعَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ', 'സമുറത്തുബ്നു ജുൻദുബ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 849, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ قال: قُلْتُ لِلزُّبَيْرِ: مَا يَمْنَعُكَ أَنْ تُحَدِّثَ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَمَا يُحَدِّثُ عَنْهُ أَصْحَابُهُ؟ فَقَالَ: أَمَا وَاللهِ لَقَدْ كَانَ لِي مِنْهُ وَجْهٌ وَمَنْزِلَةٌ، وَلَكِنِّي سَمِعْتُهُ يَقُولُ: "مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (خ,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ഞാൻ സുബൈർ(റ)വിനോട് ചോദിച്ചു: പ്രവാചകർ(സ)യുടെ അനുചരർ ഹദീസ് ഉദ്ധരിക്കുന്നത് പോലെ നബി(സ)യിൽ നിന്ന് ഹദീസ് ഉദ്ധരിക്കാൻ താങ്കളെ എന്താണ് തടയുന്നത്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുതന്നെ സത്യം! എനിക്ക് പ്രവാചകന്റെയടുത്ത് സ്ഥാനവും മഹത്വവുമുണ്ടായിരുന്നു. പക്ഷേ, നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ആരെങ്കിലും മനപ്പൂർവ്വം എന്റെ മേൽ കളവ് പറഞ്ഞാൽ അവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ബു,ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 850, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَكْذِبُوا عَلَيَّ، فَإِنَّهُ مَنْ كَذَبَ عَلَيَّ يَلِجُ فِي النَّارِ". حَسَنٌ صَحِيحٌ. (ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ എന്റെ മേൽ കളവ് പറയരുത്. എന്റെ മേൽ കളവ് പറഞ്ഞവർ നരകത്തിൽ പ്രവേശിക്കുക തന്നെ ചെയ്യും." (തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 850, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَذَبَ عَلَيَّ -حَسِبْتُ أَنَّهُ قَالَ- مُتَعَمِّدًا فَلْيَتَبَوَّأْ بَيْتَهُ مِنَ النَّارِ". حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും എന്റെ മേൽ കളവ് പറഞ്ഞാൽ അവൻ നരകത്തിൽ തന്റെ ഭവനം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ബു,മു,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 850, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أَبِي نَمْلَةَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ بَيْنَمَا هُوَ جَالِسٌ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ رَجُلٌ مِنَ الْيَهُودِ مُرَّ بِجَنَازَةٍ، فَقَالَ: يَا مُحَمَّدُ، هَلْ تَتَكَلَّمُ هَذِهِ الْجَنَازَةُ؟ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللهُ أَعْلَمُ". فَقَالَ الْيَهُودِيُّ: إِنَّهَا تَتَكَلَّمُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا حَدَّثَكُمْ أَهْلُ الْكِتَابِ فَلَا تُصَدِّقُوهُمْ وَلَا تُكَذِّبُوهُمْ، وَقُولُوا: آمَنَّا بِاللهِ وَرُسُلِهِ، فَإِنْ كَانَ بَاطِلًا لَمْ تُصَدِّقُوهُ، وَإِنْ كَانَ حَقًّا لَمْ تُكَذِّبُوهُ". (د)', 'അബൂസലമതിൽ അൻസാരി(റ): അദ്ദേഹം പ്രവാചകൻ(സ)യുടെ കൂടെയിരിക്കുമ്പോൾ കൂടെ ഒരു ജൂതനുമുണ്ടായിരുന്നു. അപ്പോൾ ഒരു ജനാസ കൊണ്ടു പോയി. ജൂതൻ ചോദിച്ചു: മുഹമ്മദേ, ഈ ജനാസ സംസാരിക്കുമോ? നബി(സ) പ്രതിവചിച്ചു: "അല്ലാഹുവിനറിയാം." ജൂതൻ പറഞ്ഞു: അത് സംസാരിക്കും. അപ്പോൾ റസൂൽ (സ) പറഞ്ഞു: "വേദക്കാർ പറയുന്നത് നിങ്ങൾ വാസതവമാക്കുകയോ കളവാക്കുകയോ ചെയ്യരുത്. നിങ്ങൾ പറയുക: ഞങ്ങൾ അല്ലാഹുവിലും അവന്റെ പ്രവാചകരിലും വിശ്വസിച്ചിരിക്കുന്നു. അങ്ങനെ പറഞ്ഞാൽ അത് മിഥ്യയാണെങ്കിൽ നിങ്ങളത് വാസ്തവമാക്കുകയോ സത്യമാണെങ്കിൽ നിങ്ങളത് കളവാക്കുകയോ ചെയ്തിട്ടില്ല." (ദ)', 'أَبِي نَمْلَةَ الْأَنْصَارِيِّ', 'അബൂസലമതിൽ അൻസാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 850, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قال: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَتَعَلَّمْتُ لَهُ كِتَابَ يَهُودَ، وَقَالَ: "إِنِّي وَاللهِ مَا آمَنُ يَهُودَ عَلَى كِتَابِي". فَتَعَلَّمْتُهُ، فَلَمْ يَمُرَّ بِي إِلَّا نِصْفُ شَهْرٍ حَتَّى حَذَقْتُهُ، فَكُنْتُ أَكْتُبُ لَهُ إِذَا كَتَبَ، وَأَقْرَأُ لَهُ إِذَا كُتِبَ إِلَيْهِ. (د,ت)', 'സൈദുബ്നു സാബിത്(റ): എന്നോട് റസൂൽ(സ) ജൂതരുടെ എഴുത്ത് പഠിക്കാൻ പറഞ്ഞു. ഞാനത് പ്രവാചകന് വേണ്ടി പഠിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു തന്നെ സത്യം! എന്റെ കിതാബിൽ ഞാൻ ജൂതരെ ഭയക്കാതിരിക്കുന്നില്ല." അപ്പോൾ ഞാനത് പഠിച്ചു. ഒരു മാസം പകുതി കഴിഞ്ഞപ്പോൾ ഞാനതിൽ നിപുണനായി. ശേഷം നബി(സ) കത്തെഴുതുമ്പോൾ ഞാൻ എഴുതിക്കൊടുക്കുകയും നബി(സ)യിലേക്ക് വല്ല എഴുത്തും വന്നാൽ ഞാനത് വായിച്ച് കൊടുക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ദ,തു)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 851, 851, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَبْدِاللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قال: كَانَ النَّبِيُّ صَلَّى الله عليه وسلم يُحَدِّثُنَا عَنْ بَنِي إِسْرَائِيلَ حَتَّى يُصْبِحَ، مَا يَقُومُ إِلَّا إِلَى عُظْمِ صَلَاةٍ. (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) ഞങ്ങൾക്ക് ബനൂഇസ്റാഈലിനെക്കുറിച്ച് നേരം വെളുക്കുന്നത് വരെ പറഞ്ഞ് തന്നിരുന്നു. ഫർള് നിസ്കാരത്തിലേക്കല്ലാതെ അവിടന്ന് എണീക്കുമായിരുന്നില്ല. (ദ)', 'عَبْدِاللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 851, 851, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَلِّغُوا عَنِّي وَلَوْ آيَةً، وَحَدِّثُوا عَنْ بَنِي إِسْرَائِيلَ وَلَا حَرَجَ، وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". حَسَنٌ صَحِيحٌ. (خ,د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്നിൽ നിന്ന് ഒരു ആയത്തെങ്കിലും എത്തിച്ച് കൊടുക്കുക. നിങ്ങൾ ബനു ഇസ്റാഈലിൽ നിന്ന് ഹദീസ് ഉദ്ധരിക്കുക. അതിൽ കുഴപ്പമില്ല. ആരെങ്കിലും മനപ്പൂർവ്വം എന്റെ മേൽ കളവ് പറഞ്ഞാൽ അവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ബു,ദ,തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 851, 851, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: بَيْنَمَا هُوَ جَالِسٌ فِي الْمَسْجِدِ وَالنَّاسُ مَعَهُ إِذْ أَقْبَلَ ثَلَاثَةُ نَفَرٍ فَأَقْبَلَ اثْنَانِ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَذَهَبَ وَاحِدٌ، قَالَ: فَوَقَفَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَمَّا أَحَدُهُمَا فَرَأَى فُرْجَةً فِي الْحَلْقَةِ فَجَلَسَ فِيهَا، وَأَمَّا الْآخَرُ فَجَلَسَ خَلْفَهُمْ، وَأَمَّا الثَّالِثُ فَأَدْبَرَ ذَاهِبًا، فَلَمَّا فَرَغَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أُخْبِرُكُمْ عَنِ النَّفَرِ الثَّلَاثَةِ؟ أَمَّا أَحَدُهُمْ: فَأَوَى إِلَى اللهِ فَآوَاهُ اللهُ، وَأَمَّا الْآخَرُ: فَاسْتَحْيَا فَاسْتَحْيَا اللهُ مِنْهُ، وَأَمَّا الْآخَرُ: فَأَعْرَضَ فَأَعْرَضَ اللهُ عَنْهُ". (خ)', 'അബൂ വാഖിദുല്ലൈസി(റ): റസൂൽ(സ) ഒരു സംഘം ആളുകളോടൊപ്പം മദീനയിലെ പള്ളിയിൽ ഇരിക്കുമ്പോൾ മൂന്ന് പേർ അവിടെ വന്നു. അതിൽ രണ്ട് പേർ നബി(സ)യുടെ അടുത്തേക്ക് മുന്നിട്ട് വരികയും ഒരാൾ പോകുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവർ രണ്ടുപേരും അല്ലാഹുവിന്റെ റസൂലിന്റെ അടുത്ത് നിന്നു. അപ്പോൾ അവരിൽ ഒരാൾ സദസ്സിന്റെ ഒരു ഒഴിവ് കാണുകയും അവിടെ ഇരിക്കുകയും ചെയ്തു. മറ്റെയാൾ എല്ലാവരുടെയും പിന്നിലിരുന്നു. മൂന്നാമനാവട്ടെ, പിന്തിരിഞ്ഞ് പോയി. സംസാരം കഴിഞ്ഞപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഈ മൂന്നംഗ സംഘത്തെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് അറിയിച്ച്തരട്ടെയോ? അവരിൽ ഒരാൾ അല്ലാഹുവിൽ സങ്കേതം തേടി. അല്ലാഹു അവന് സങ്കേതം നൽകി. മറ്റവൻ ലജ്ജിച്ചു. അവനോട് അല്ലാഹുവും ലജ്ജിച്ചു. മൂന്നാമനാവട്ടെ പിന്തിരിഞ്ഞ് പോയി. അപ്പോൾ അവനെത്തൊട്ട് അല്ലാഹുവും പിന്തിരിഞ്ഞ് കളഞ്ഞു." (ബു)', 'أَبِي وَاقِدٍ اللَّيْثِيِّ', 'അബൂ വാഖിദുല്ലൈസി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 851, 852, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جَاءَتْ أُمُّ سُلَيْمٍ رَضِيَ اللهُ عَنْهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ إِنَّ اللهَ لَا يَسْتَحْيِي مِنَ الْحَقِّ فَهَلْ عَلَى الْمَرْأَةِ مِنْ غُسْلٍ إِذَا احْتَلَمَتْ؟ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا رَأَتِ الْمَاءَ". فَغَطَّتْ أُمُّ سَلَمَةَ -تَعْنِي وَجْهَهَا- وَقَالَتْ يَا رَسُولَ اللهِ: أَوَتَحْتَلِمُ الْمَرْأَةُ؟ قَالَ: "نَعَمْ، تَرِبَتْ يَمِينُكِ فَبِمَ يُشْبِهُهَا وَلَدُهَا". (خ)', 'ഉമ്മുസലമ(റ): ഉമ്മുസുലൈം(റ) നബി(സ)യുടെ അടുക്കൽ വന്നു ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹു സത്യം പറയാൻ ലജ്ജ കാണിക്കുകയില്ല. സ്വപ്ന സ്ഖലനമുണ്ടായാൽ സ്ത്രീ കുളിക്കേണ്ടതുണ്ടോ? നബി(സ) പറഞ്ഞു: "അവൾ ഇന്ദ്രിയം കണ്ടാൽ കുളിക്കണം." ഇത് കേട്ടപ്പോൾ ഉമ്മുസലമ(റ) വസ്ത്രം കൊണ്ട് മുഖം മൂടി. എന്നിട്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സ്ത്രീക്ക് സ്വപ്നസ്ഖലനമുണ്ടാകുമോ? നബി(സ) പറഞ്ഞു: "അതെ, ഉണ്ടാകും. പിന്നെങ്ങനെയാണ് അവളുടെ സന്താനം അവളോട് സാദൃശ്യമാകുന്നത്?" (ബു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 852, 852, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قال: كُنْتُ رَجُلًا مَذَّاءً فَأَمَرْتُ الْمِقْدَادَ أَنْ يَسْأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ، فَقَالَ: "فِيهِ الْوُضُوءُ". (خ)', 'അലി(റ): മദ്യ് അധികമുള്ള ഒരാളായിരുന്നു ഞാൻ. തന്നിമിത്തം അതിനെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കാൻ ഞാൻ മിഖ്ദാദിനോട് ആവശ്യപ്പെട്ടു. അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു. "അതുണ്ടാകുമ്പോൾ വുളു ചെയ്താൽ മതി" എന്ന് നബി(സ) പറഞ്ഞു. (ബു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 852, 852, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قال: كُنْتُ أَنَا وَجَارٌ لِي مِنَ الْأَنْصَارِ فِي بَنِي أُمَيَّةَ بْنِ زَيْدٍ وَهِيَ مِنْ عَوَالِي الْمَدِينَةِ وَكُنَّا نَتَنَاوَبُ النُّزُولَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْزِلُ يَوْمًا وَأَنْزِلُ يَوْمًا، فَإِذَا نَزَلْتُ جِئْتُهُ بِخَبَرِ ذَلِكَ الْيَوْمِ مِنَ الْوَحْيِ وَغَيْرِهِ وَإِذَا نَزَلَ فَعَلَ مِثْلَ ذَلِكَ فَنَزَلَ صَاحِبِي الْأَنْصَارِيُّ يَوْمَ نَوْبَتِهِ فَضَرَبَ بَابِي ضَرْبًا شَدِيدًا. فَقَالَ: أَثَمَّ هُوَ فَفَزِعْتُ فَخَرَجْتُ إِلَيْهِ. فَقَالَ: قَدْ حَدَثَ أَمْرٌ عَظِيمٌ. قَالَ: فَدَخَلْتُ عَلَى حَفْصَةَ فَإِذَا هِيَ تَبْكِي. فَقُلْتُ: طَلَّقَكُنَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: لَا أَدْرِي، ثُمَّ دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: -وَأَنَا قَائِمٌ- أَطَلَّقْتَ نِسَاءَكَ؟ قَالَ: "لَا" فَقُلْتُ: اللهُ أَكْبَرُ. (خ)', 'ഉമർ(റ): ഞാനും അൻസാരികൾപ്പെട്ട എന്റെ അയൽവാസിയും ബനൂഉമയ്യതുബ്നുസൈദ് ഗോത്രത്തിലാണ് താമസിച്ചിരുന്നത്. അത് മദീനയിലെ ഉയർന്ന ഭാഗങ്ങളിൽ പെട്ട ഒരു സ്ഥലമായിരുന്നു. ഞങ്ങൾ ഊഴമിട്ടാണ് നബി(സ)യുടെ അടുത്തേക്ക് ഇറങ്ങിച്ചെന്നിരുന്നത്. ഒരു ദിവസം അദ്ദേഹം ചെല്ലും. അടുത്ത ദിവസം ഞാനും. ഞാൻ പോയാൽ ആ ദിവസം തിരുമേനിക്ക് ലഭിച്ച വഹ്യ്, മുതലായ കാര്യങ്ങളെക്കുറിച്ചുള്ള റിപ്പോർട്ടുമായി അദ്ദേഹത്തിന്റെ അടുക്കൽ ചെല്ലും. അദ്ദേഹം പോയാലും അതേ പ്രകാരം പ്രവർത്തിക്കും. അങ്ങനെ ആ അൻസാരി തന്റെ ഊഴദിവസം നബി(സ)യുടെ അടുക്കലേക്ക് പോകുകയും (തിരിച്ചുവന്നിട്ട്) ''അദ്ദേഹം ഇവിടെയുണ്ടോ'' എന്ന് ചോദിച്ചുകൊണ്ട് എന്റെ വാതിലിൽ ശക്തിയായി മുട്ടുകയും ചെയ്തു. ഞാൻ ഭയന്ന് പുറത്തേക്ക് വന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഗൗരവമേറിയ ഒരു സംഭവം കഴിഞ്ഞിട്ടുണ്ട്. നിവേദകൻ പറയുന്നു: ഉടൻ ഞാൻ ഹഫ്സയെ ചെന്ന് കണ്ടപ്പോൾ അവർ കരയുകയാണ്. ഞാൻ ചോദിച്ചു: റസൂൽ(സ) നിങ്ങളുമായുള്ള വിവാഹബന്ധം വേർപെടുത്തിയോ? എനിക്കറിയില്ലെന്ന് ഹഫ്സ(റ) മറുപടി പറഞ്ഞു. പിന്നീട് ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്ന് എഴുന്നേറ്റ് നിന്ന് ചോദിച്ചു: അവിടുന്ന് സ്വപത്നിമാരുമായുള്ള ബന്ധം വേർപ്പെടുത്തിക്കളെഞ്ഞോ? നബി(സ) പറഞ്ഞു: "ഇല്ല." അപ്പോൾ ഞാൻ അല്ലാഹു അക്ബർ എന്ന് മൊഴിഞ്ഞു. (ബു)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 852, 853, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ جُلُوسٌ مَعَ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ دَخَلَ رَجُلٌ عَلَى جَمَلٍ فَأَنَاخَهُ فِي الْمَسْجِدِ ثُمَّ عَقَلَهُ ثُمَّ قَالَ: أَيُّكُمْ مُحَمَّدٌ؟ وَالنَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ مُتَّكِئٌ بَيْنَ ظَهْرَانَيْهِمْ فَقُلْنَا: هَذَا الرَّجُلُ الْأَبْيَضُ الْمُتَّكِئُ، فَقَالَ لَهُ الرَّجُلُ: ابْنَ عَبْدِالْمُطَّلِبِ؟ فَقَالَ لَهُ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "قَدْ أَجَبْتُكَ". فَقَالَ: إِنِّي سَائِلُكَ فَمُشَدِّدٌ عَلَيْكَ فِي الْمَسْأَلَةِ فَلَا تَجِدْ عَلَيَّ فِي نَفْسِكَ. قَالَ: "سَلْ عَمَّا بَدَا لَكَ". فَقَالَ: أَسْأَلُكَ بِرَبِّكَ وَرَبِّ مَنْ قَبْلَكَ أَللهُ أَرْسَلَكَ إِلَى النَّاسِ كُلِّهِمْ؟ فَقَالَ: "اللَّهُمَّ نَعَمْ". قَالَ: أَنْشُدُكَ بِاللهِ، آللهُ أَمَرَكَ أَنْ تُصَلِّيَ الصَّلَوَاتِ الْخَمْسَ فِي الْيَوْمِ وَاللَّيْلَةِ؟ قَالَ: "اللَّهُمَّ نَعَمْ". قَالَ: أَنْشُدُكَ بِاللهِ، آللهُ أَمَرَكَ أَنْ تَصُومَ هَذَا الشَّهْرَ مِنَ السَّنَةِ؟ قَالَ: "اللَّهُمَّ نَعَمْ". قَالَ: أَنْشُدُكَ بِاللهِ، آللهُ أَمَرَكَ أَنْ تَأْخُذَ هَذِهِ الصَّدَقَةَ مِنْ أَغْنِيَائِنَا فَتَقْسِمَهَا عَلَى فُقَرَائِنَا؟ فَقَالَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ : "اللَّهُمَّ نَعَمْ". فَقَالَ الرَّجُلُ: آمَنْتُ بِمَا جِئْتَ بِهِ، وَأَنَا رَسُولُ مَنْ وَرَائِي مِنْ قَوْمِي وَأَنَا ضِمَامُ بْنُ ثَعْلَبَةَ أَخُو بَنِي سَعْدِ بْنِ بَكْرٍ. (خ)', 'അനസ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം പള്ളിയിൽ ഇരിക്കുമ്പോൾ ഒരാൾ ഒട്ടകപ്പുറത്ത് വന്നു. ഒട്ടകത്തെ പള്ളിയിൽ മുട്ടുകുത്തിച്ച് അതിനെ കെട്ടിയിട്ടു. പിന്നെ അയാൾ ചോദിച്ചു: നിങ്ങളുടെ കൂട്ടത്തിൽ ആരാണ് മുഹമ്മദ്? നബി(സ) ഞങ്ങൾക്കിടയിൽ തന്നെ ചാരിയിരിക്കുന്നുണ്ടായിരുന്നു. ആ ചാരിയിരിക്കുന്ന വെളുത്ത മനുഷ്യനാണ് മുഹമ്മദ്(സ), ഞങ്ങൾ മറുപടി പറഞ്ഞു. അപ്പോൾ അബ്ദുൽ മുത്വലിബിന്റെ മകനേ, എന്ന് അദ്ദേഹം തിരുനബി(സ)യെ സംബോധന ചെയ്തു. "ഞാനിതാ നിങ്ങളുടെ വിളിക്ക് ഉത്തരം നൽകിയിരിക്കുന്നു."വെന്ന് നബി(സ) പറഞ്ഞു. അപ്പോൾ ആഗതൻ പറഞ്ഞു: ഞാൻ അങ്ങയോട് ചില ചോദ്യങ്ങൾ ചോദിക്കാൻ പോകുകയാണ്. ചോദിക്കുമ്പോൾ ഞാനൊരു പക്ഷേ അങ്ങയോട് കർശനമായി പെരുമാറിയേക്കാം. പക്ഷേ, അങ്ങയുടെ മനസ്സിൽ എന്നോട് ദേഷ്യമുണ്ടാവാരുതെന്ന് അപേക്ഷയുണ്ട്. നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ മനസ്സിൽ തോന്നുന്നതെന്തും ചോദിക്കുക." ആഗതൻ പറഞ്ഞു: അങ്ങയുടെയും അങ്ങയുടെ മുമ്പുള്ളവരുടേയും രക്ഷിതാവായ അല്ലാഹുവിനെ മുൻനിർത്തി ഞാൻ ചോദിക്കുന്നു: മനുഷ്യരിലേക്ക് ആകമാനം ദൈവദൂതനായി അങ്ങയെ നിയോഗിച്ചത് അല്ലാഹു തന്നെയാണോ? നബി(സ) പറഞ്ഞു: "അതെ, അല്ലാഹുവാണ് സത്യം." ആഗതൻ പറഞ്ഞു: അല്ലാഹുവിനെ മുൻനിർത്തി സത്യം ചെയ്തുകൊണ്ട് ഞാനിതാ ചോദിക്കുന്നു: ഒരു രാവും പകലുമായി അഞ്ചു നേരം നിസ്കാരം നിർവ്വഹിക്കാൻ അങ്ങയോട് കൽപ്പിച്ചത് അല്ലാഹുവാണോ? നബി (സ) പ്രതിവചിച്ചു: "അതെ, അല്ലാഹുവാണ് സത്യം!" ആഗതൻ പറഞ്ഞു: അല്ലാഹുവിനെ മുൻനിറുത്തി സത്യം ചെയ്ത് കൊണ്ട് ഞാൻ ചോദിക്കുന്നു: ഓരോ വർഷവും ഈ മാസത്തിൽ നോമ്പനുഷ്ഠിക്കാൻ അങ്ങയോട് കൽപ്പിച്ചത് അല്ലാഹുവാണോ? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിനെയാണ് സത്യം! അതെ." ആഗതൻ പറഞ്ഞു: അല്ലാഹുവിനെ മുൻനിർത്തി സത്യം ചെയ്ത് കൊണ്ട് ഞാനിതാ ചോദിക്കുന്നു: ഞങ്ങളിലെ ധനികരിൽ നിന്ന് സകാത്ത് വാങ്ങി ഞങ്ങളിലെ ദരിദ്രർക്ക് നൽകാൻ അങ്ങയോട് കൽപ്പിച്ചത് അല്ലാഹുവാണോ? നബി(സ) പറഞ്ഞു: "അതെ, അല്ലാഹുവാണ് സത്യം!" അപ്പോൾ ആ മനുഷ്യൻ പ്രഖ്യാപിച്ചു: അവിടുന്ന് പ്രബോധനം ചെയ്യുന്ന ആ മതത്തിൽ ഞാനിതാ വിശ്വസിച്ചിരിക്കുന്നു. എന്റെ പിന്നിലുള്ള ഒരു ജനതയുടെ ദൂതനാണ് ഞാൻ. ബനൂ സഅ്ദിബ്നു ബക്റിന്റെ സഹോദരനായ സഅ്ലബയുടെ മകൻ ളിമാമാണ് ഞാൻ. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 853, 854, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ بِكِتَابِهِ رَجُلًا وَأَمَرَهُ أَنْ يَدْفَعَهُ إِلَى عَظِيمِ الْبَحْرَيْنِ فَدَفَعَهُ عَظِيمُ الْبَحْرَيْنِ إِلَى كِسْرَى، فَلَمَّا قَرَأَهُ مَزَّقَهُ، قَالَ: فَدَعَا عَلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُمَزَّقُوا كُلَّ مُمَزَّقٍ. (خ)', 'ഇബ്‌നുഅബ്ബാസ്(റ): ബഹ്‌റൈനിലെ ഭരണാധിപന് നൽകണമെന്നാവശ്യപ്പെട്ട് റസൂൽ(സ) തന്റെ കത്തുമായി ഒരാളെ അയക്കുകയും ബഹ്‌റൈൻ ഭരണാധിപൻ ആ കത്ത് കിസ്‌റാ ചക്രവർത്തിക്ക് നൽകുകയും ചെയ്തു. വായിച്ചശേഷം കിസ്‌റാരാജാവ് കത്ത് പിച്ചിച്ചീന്തിക്കളഞ്ഞു. ഇബ്‌നുഅബ്ബാസ്(റ) പറയുന്നു: അവർ പൂർണ്ണമായി പിച്ചിച്ചീന്തപ്പെടട്ടെ, എന്ന് അപ്പോൾ നബി(സ) അവർക്കെതിരായി പ്രാർത്ഥിച്ചു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 854, 854, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَتَبَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كِتَابًا أَوْ أَرَادَ أَنْ يَكْتُبَ فَقِيلَ لَهُ إِنَّهُمْ لَا يَقْرَءُونَ كِتَابًا إِلَّا مَخْتُومًا فَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ نَقْشُهُ: مُحَمَّدٌ رَسُولُ اللَّهِ، كَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي يَدِهِ. (خ)', 'അനസ്(റ): നബി(സ) ഒരു കത്ത് എഴുതി. അല്ലെങ്കിൽ എഴുതാൻ ഉദ്ദേശിച്ചു. സീൽ വെച്ച കത്തല്ലാതെ ഭരണാധികാരികൾ വായിക്കില്ലെന്ന് നബി(സ)യെ ചിലർ ഓർമ്മപ്പെടുത്തി. ഉടനെ നബി(സ) മുഹമ്മദുർറസൂലുല്ലാഹി എന്ന് കൊത്തിവെച്ച ഒരു മോതിരം ഉണ്ടാക്കി. നബി(സ)യുടെ കയ്യിലെ മോതിരത്തിന്റെ വെള്ളയിലേക്ക് ഞാനിങ്ങനെ നോക്കുന്നത് പോലെയുണ്ട്. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 854, 854, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ الشَّجَرِ شَجَرَةً لَا يَسْقُطُ وَرَقُهَا وَإِنَّهَا مَثَلُ الْمُسْلِمِ فَحَدِّثُونِي مَا هِيَ". فَوَقَعَ النَّاسُ فِي شَجَرِ الْبَوَادِي قَالَ عَبْدُ اللَّهِ: وَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ فَاسْتَحْيَيْتُ، ثُمَّ قَالُوا: حَدِّثْنَا مَا هِيَ يَا رَسُولَ اللَّهِ، قَالَ: هِيَ النَّخْلَةُ. (خ)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മരങ്ങളിൽ ഒരു മരമുണ്ട്. അതിന്റെ ഇല പൊഴിയുകയില്ല. അത് ഒരു മുസ്‌ലിമിനെ പോലെയാണ്. ആ മരം ഏതാണെന്ന് നിങ്ങൾക്ക് പറഞ്ഞുതരാമോ?" ജനങ്ങൾ മലയോരങ്ങളിലെ മരങ്ങളെക്കുറിച്ച് ചിന്തിച്ചു. അബ്ദുല്ല(റ) പറയുന്നു: എനിക്ക് മനസ്സിലായി, അത് ഈത്തപ്പന തന്നെ. പക്ഷേ, എനിക്ക് പറയാൻ ലജ്ജ തോന്നി. പിന്നെ അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരെ, അത് ഏതാണ് എന്ന് അവിടുന്ന് പറഞ്ഞു തന്നാലും. നബി(സ) പറഞ്ഞു: "ഈത്തപ്പനയാണത്." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 854, 854, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَسْمَعُونَ وَيُسْمَعُ مِنْكُمْ، وَيُسْمَعُ مِمَّنْ سَمِعَ مِنْكُمْ". (د)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ കേൾക്കും. നിങ്ങളിൽ നിന്ന് കേൾക്കും. നിങ്ങളെ കേട്ടവരിൽ നിന്നും കേൾക്കും." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 854, 854, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ سَهْلٍ يَعْنِي ابْنَ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَاللَّهِ لَأَنْ يَهْدِيَ اللَّهُ بِهُدَاكَ رَجُلًا وَاحِدًا خَيْرٌ لَكَ مِنْ حُمُرِ النَّعَمِ". (ق,د)', 'സഹ്‌ലുബ്‌നു സഅ്ദ്(റ): നബി(സ) പറഞ്ഞു: "നിന്റെ സന്മാർഗം കൊണ്ട് അല്ലാഹു ഒരാളെ വഴി കാണിക്കുന്നത് ചുവന്ന ഒട്ടകത്തേക്കാൾ നിനക്ക് ഉത്തമമാണ്." (ബു,മു,ദ)', 'سَهْلٍ يَعْنِي ابْنَ سَعْدٍ', 'സഹ്‌ലുബ്‌നു സഅ്ദ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبَانَ بْنِ عُثْمَانَ قَالَ: خَرَجَ زَيْدُ بْنُ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُ مِنْ عِنْدِ مَرْوَانَ نِصْفَ النَّهَارِ، قُلْنَا: مَا بَعَثَ إِلَيْهِ فِي هَذِهِ السَّاعَةِ إِلَّا لِشَيْءٍ سَأَلَهُ عَنْهُ، فَسَأَلْنَاهُ فَقَالَ: نَعَمْ، سَأَلَنَا عَنْ أَشْيَاءَ سَمِعْنَاهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثًا فَحَفِظَهُ حَتَّى يُبَلِّغَهُ غَيْرَهُ، فَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ، وَرُبَّ حَامِلِ فِقْهٍ لَيْسَ بِفَقِيهٍ". حَسَنٌ. (د,ت,جه)', 'അബാനുബ്‌നു ഉസ്മാൻ(റ): പകൽ സമയത്ത് മർവാന്റെ അടുക്കൽ നിന്ന് സൈദുബ്‌നുസാബിത് പുറപ്പെട്ടു. ഞങ്ങൾ പറഞ്ഞു: വല്ലതിനെയും കുറിച്ച് ചോദിക്കാനല്ലാതെ ഇന്നേരത്ത് സൈദുബ്‌നുസാബിത്(റ)വിനെ മർവാൻ വിളിപ്പിക്കില്ല. ഞങ്ങൾ അദ്ദേഹത്തോട് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അതെ, റസൂൽ(സ)യിൽ നിന്ന് കേട്ട ചില കാര്യങ്ങളെക്കുറിച്ച് ഞാൻ ചോദിച്ചു. റസൂൽ(സ) പറയുന്നത് ഞങ്ങൾ കേട്ടിട്ടുണ്ട്: "നമ്മിൽ നിന്ന് ഒരു ഹദീസ് കേട്ട് അത് ഹൃദിസ്ഥമാക്കി മറ്റുള്ളവന് എത്തിച്ചുകൊടുക്കുന്നവനെ അല്ലാഹു പ്രകാശിപ്പിക്കട്ടെ. തന്നെക്കാൾ ഗ്രഹിക്കുന്നവനിലേക്ക് വിജ്ഞാനം വഹിക്കുന്നവർ എത്രയാണ്. ജ്ഞാനിയല്ലാതെ ജ്ഞാനത്തെ വഹിക്കുന്നവരും എത്രയാണ്." (ദ,തു,ജ)', 'أَبَانَ بْنِ عُثْمَانَ قَالَ', 'അബാനുബ്‌നു ഉസ്മാൻ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا شَيْئًا فَبَلَّغَهُ كَمَا سَمِعَهُ، فَرُبَّ مُبَلَّغٍ أَوْعَى مِنْ سَامِعٍ". حَسَنٌ، صَحِيحٌ. (ت)', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നമ്മിൽ നിന്ന് വല്ലതും കേട്ട് അത് പോലെ എത്തിച്ച് കൊടുത്ത വ്യക്തിയെ അല്ലാഹു പ്രകാശിപ്പിക്കട്ടെ. കേൾക്കുന്നവനേക്കാൾ ഗ്രഹിക്കുന്ന എത്ര എത്തിച്ചുകൊടുക്കുന്നവരുണ്ട്." (തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نَضَّرَ اللَّهُ امْرَأً سَمِعَ مَقَالَتِي فَوَعَاهَا وَحَفِظَهَا وَبَلَّغَهَا، فَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ. ثَلَاثٌ لَا يُغِلُّ عَلَيْهِنَّ قَلْبُ مُسْلِمٍ: إِخْلَاصُ الْعَمَلِ لِلَّهِ، وَمُنَاصَحَةُ أَئِمَّةِ الْمُسْلِمِينَ، وَلُزُومُ جَمَاعَتِهِمْ، فَإِنَّ الدَّعْوَةَ تُحِيطُ مِنْ وَرَائِهِمْ". (ت)', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "എന്റെ വാക്ക് കേട്ട് മനസ്സിലാക്കുകയും ഹൃദിസ്ഥമാക്കുകയും എത്തിച്ചു കൊടുക്കുകയും ചെയ്തവനെ അല്ലാഹു പ്രകാശിപ്പിക്കട്ടെ. തന്നെക്കാൾ ഗ്രഹിക്കുന്നവരിലേക്ക് വിജ്ഞാനം എത്തിക്കുന്നവർ എത്രയാണ്. മുസ്‌ലിമിന്റെ ഹൃദയം ചതിയിൽ പെടാത്ത മൂന്ന് കാര്യങ്ങളുണ്ട്. ആത്മാർത്ഥ പ്രവർത്തനം അല്ലാഹുവിന് വേണ്ടി മാത്രമാക്കുക. മുസ്‌ലിംകളുടെ ഇമാമുകളോട് നന്മ ഉപദേശിക്കുക. അവരുടെ സംഘത്തിൽ എപ്പോഴുമുണ്ടാവുക. സത്യത്തിലേക്കുള്ള വിളി അവരെ വലയം ചെയ്തിരിക്കുന്നു." (തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 855, 855, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي شُرَيْحٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَوْمَ الْفَتْحِ يَقُولُ قَوْلًا سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي وَأَبْصَرَتْهُ عَيْنَايَ حِينَ تَكَلَّمَ بِهِ حَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ: "إِنَّ مَكَّةَ حَرَّمَهَا اللَّهُ وَلَمْ يُحَرِّمْهَا النَّاسُ فَلَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ يَسْفِكَ بِهَا دَمًا وَلَا يَعْضِدَ بِهَا شَجَرَةً فَإِنْ أَحَدٌ تَرَخَّصَ لِقِتَالِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا فَقُولُوا إِنَّ اللَّهَ قَدْ أَذِنَ لِرَسُولِهِ وَلَمْ يَأْذَنْ لَكُمْ وَإِنَّمَا أُذِنَ لِي سَاعَةً مِنْ نَهَارٍ ثُمَّ عَادَتْ حُرْمَتُهَا الْيَوْمَ كَحُرْمَتِهَا بِالْأَمْسِ وَلْيُبَلِّغِ الشَّاهِدُ الْغَائِبَ". (خ)', 'അബൂശുറൈഹ്(റ): മക്ക ജയിച്ചടക്കിയ ദിവസം നബി(സ) പറഞ്ഞ ചില വാക്കുകൾ എന്റെ രണ്ടു കാതുകളും കേട്ടിട്ടുണ്ട്. പ്രത്യേകം മനഃപാഠമാക്കിയിട്ടുണ്ട്. നബി(സ) സംസാരിച്ചത് എന്റെ രണ്ട് കണ്ണും കണ്ടിട്ടുണ്ട്. നബി(സ) അല്ലാഹുവിനെ സ്തുതിച്ചു. അവന്റെ മഹത്വത്തെ പ്രകീർത്തിച്ചു. എന്നിട്ട് പറഞ്ഞു: "മക്കയെ ആദരണീയമാക്കിയത് മനുഷ്യരല്ല, അല്ലാഹുവാണ്. അതുകൊണ്ട് അല്ലാഹുവിലും അന്ത്യ ദിനത്തിലും വിശ്വസിക്കുന്ന മനുഷ്യന് ഒരിക്കലും മക്കയിൽ വെച്ച് വല്ലവരുടെയും രക്തം ഒഴുക്കാനോ മക്കയിലെ വല്ല വൃക്ഷം മുറിക്കാനോ പാടില്ല. റസൂൽ(സ) അവിടെ യുദ്ധം ചെയ്തിട്ടുണ്ടെന്നത് ആരെങ്കിലും അവിടെ യുദ്ധം ചെയ്യാൻ വേണ്ടി ഒഴിവു കഴിവായി പറഞ്ഞാൽ അവരോട് നിങ്ങൾ പറയുക: അല്ലാഹു സമ്മതം നൽകിയത് അവന്റെ പ്രവാചകന് മാത്രമാണ്. നിങ്ങൾക്കവൻ സമ്മതം തന്നിട്ടില്ല. അല്ലാഹു എനിക്ക് സമ്മതം നൽകിയത് തന്നെ പകൽ ഒരു നാഴിക നേരം മാത്രമാണ്. പിന്നീട് മക്കയുടെ ആദരണീയത അതിന്റെ ഇന്നലത്തെ ആദരണീയത പോലെത്തന്നെ ഇന്ന് തിരിച്ചുവന്നിരിക്കുന്നു. ഇവിടെ ഹാജറുള്ളവൻ ഹാജറില്ലാത്തവന് എത്തിച്ച് കൊടുക്കുക." (ബു)', 'أَبِي شُرَيْحٍ', 'അബൂശുറൈഹ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 855, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَعَدَ عَلَيْهِ السَّلَامُ عَلَى بَعِيرِهِ وَأَمْسَكَ إِنْسَانٌ بِخِطَامِهِ أَوْ بِزِمَامِهِ ثُمَّ قَالَ: "أَيُّ يَوْمٍ هَذَا؟" فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ سِوَى اسْمِهِ قَالَ: "أَلَيْسَ يَوْمَ النَّحْرِ؟" قُلْنَا: بَلَى، قَالَ: "فَأَيُّ شَهْرٍ هَذَا؟" فَسَكَتْنَا، حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ فَقَالَ: "أَلَيْسَ بِذِي الحِجَّةِ؟" قُلْنَا: بَلَى، قَالَ: "فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ بَيْنَكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا لِيُبَلِّغِ الشَّاهِدُ الْغَائِبَ، فَإِنَّ الشَّاهِدَ عَسَى أَنْ يُبَلِّغَ مَنْ هُوَ أَوْعَى لَهُ مِنْهُ". (خ)', 'അബൂബക്‌റ(റ): റസൂൽ(സ) ഒട്ടകപ്പുറത്ത് ഇരുന്നു. ഒരാൾ ഒട്ടകത്തിന്റെ കടിഞ്ഞാൺ പിടിച്ചിരിക്കുന്നു. പിന്നീട് നബി(സ) ചോദിച്ചു: "ഇത് ഏത് ദിവസമാണ്?" ഞങ്ങൾ മൗനം ദീക്ഷിച്ചു. റസൂൽ (സ) ദിവസത്തിന് വേറെ പേര് വെക്കുമെന്ന് ഞങ്ങൾ വിചാരിച്ചു. "ഇത് ബലിദിനമല്ലെയോ?", റസൂൽ(സ) ചോദിച്ചു. ഞങ്ങൾ പറഞ്ഞു: അതെ. നബി(സ) ചോദിച്ചു: "ഏത് മാസമാണിത്?" ഞങ്ങൾ മൗനം അവലംബിച്ചു. നബി(സ) മാസത്തിന് വേറെ പേര് വെക്കുമെന്ന് ഞങ്ങൾ നിനച്ചു. നബി(സ) പറഞ്ഞു: "ഇത് ദുൽഹിജ്ജയല്ലെയോ?" അതെ, ഞങ്ങൾ പ്രതിവചിച്ചു. നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ രക്തവും സമ്പത്തും അഭിമാനവും നിങ്ങൾക്കിടയിൽ നിഷിദ്ധമാണ്, നിങ്ങളുടെ ഈ നാട്ടിലെ നിങ്ങളുടെ ഈ മാസത്തിലെ നിങ്ങളുടെ ഈ ദിവസം നിഷിദ്ധമായത് പോലെ. ഇവിടെ ഹാജറായവൻ അസന്നിഹിതനായവന് എത്തിച്ചു കൊടുക്കുക. ഇവിടെ ഹാജറായവൻ അവനേക്കാൾ ഗ്രഹിക്കുന്നവനിലേക്ക് എത്തിച്ച് കൊടുത്തേക്കാം." (ബു)', 'أَبِي بَكْرَةَ', 'അബൂബക്‌റ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 856, 856, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَبْدِاللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: تَخَلَّفَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنَّا فِي سَفْرَةٍ سَافَرْنَاهَا فَأَدْرَكَنَا وَقَدْ أَرْهَقْنَا الصَّلَاةَ فَجَعَلْنَا نَتَوَضَّأُ وَنَمْسَحُ عَلَى أَرْجُلِنَا فَنَادَى بِأَعْلَى صَوْتِهِ وَيْلٌ لِلْأَعْقَابِ مِنَ النَّارِ مَرَّتَيْنِ أَوْ ثَلَاثًا. (خ)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഞങ്ങളുടെ ഒരു യാത്രയിൽ നബി(സ) ഞങ്ങളിൽ നിന്ന് പിന്നിലായി. തിരുമേനി(സ) ഞങ്ങളുടെ കൂടെ എത്തിച്ചേർന്നത് നമസ്കാരത്തിന്റെ സമയം സമീപിക്കുകയും ഞങ്ങൾ വുളൂ ചെയ്തു കൊണ്ടിരിക്കുകയും ചെയ്യുമ്പോഴാണ്. ഞങ്ങളുടെ കാലുകൾ ഞങ്ങൾ വെള്ളം കൊണ്ട് തടവാൻ തുടങ്ങി. "മടമ്പു കാലുകൾക്ക് അഗ്നിമൂലം വമ്പിച്ച നാശമാണ് അനുഭവപ്പെടുക." രണ്ടോ മൂന്നോ പ്രാവശ്യം തിരുമേനി(സ) ഇത് വിളിച്ചു പറഞ്ഞു. (ബു)', 'عَبْدِاللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 856, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سُئِلَ عَنْ عِلْمٍ عَلِمَهُ، ثُمَّ كَتَمَهُ، أُلْجِمَ يَوْمَ الْقِيَامَةِ بِلِجَامٍ مِنْ نَارٍ". حَسَنٌ. (د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "താൻ അറിയുന്ന വിഷയത്തെ കുറിച്ച് ചോദിക്കപ്പെടുമ്പോൾ അത് മറച്ചു വെച്ചാൽ അയാൾക്ക് നരകത്തിൽ നിന്നുള്ള കടിഞ്ഞാൺ ഇടപ്പെടും." (ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَبْدِاللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلًا قَامَ فِي الْمَسْجِدِ فَقَالَ يَا رَسُولَ اللَّهِ: مِنْ أَيْنَ تَأْمُرُنَا أَنْ نُهِلَّ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يُهِلُّ أَهْلُ الْمَدِينَةِ مِنْ ذِي الْحُلَيْفَةِ، وَيُهِلُّ أَهْلُ الشَّأْمِ مِنَ الْجُحْفَةِ، وَيُهِلُّ أَهْلُ نَجْدٍ مِنْ قَرْنٍ". وَقَالَ ابْنُ عُمَرَ: وَيَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَيُهِلُّ أَهْلُ الْيَمَنِ مِنْ يَلَمْلَمَ". وَكَانَ ابْنُ عُمَرَ يَقُولُ: لَمْ أَفْقَهُ هَذِهِ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഒരാൾ പള്ളിയിൽ എഴുന്നേറ്റ് നിന്ന് ചോദിച്ചു: എവിടെനിന്ന് ഇഹ്റാം ചെയ്യാനാണ് അങ്ങ് ഞങ്ങളോട് കൽപ്പിക്കുന്നത്? തിരുമേനി(സ) പറഞ്ഞു: "മദീന നിവാസികൾ ദുൽഹുലൈഫയിൽ വെച്ചും, സിറിയക്കാർ ജുഹ്ഫയിൽ വെച്ചും, നജ്ദുകാർ ഖർനിൽ വെച്ചുമാണ് ഇഹ്റാം ചെയ്യേണ്ടത്." ഇബ്നുഉമർ(റ) പറയുന്നു: "യമൻകാർ യലംലമിൽ വെച്ചുമാണ് ഇഹ്റാം ചെയ്യേണ്ടത്." എന്ന് തിരുമേനി(സ) അരുളിയതായി ജനങ്ങൾ പറയുന്നുണ്ട്. പക്ഷേ, ഇത് നബി(സ)യിൽ നിന്നും ഞാൻ മനസ്സിലാക്കിയിട്ടില്ല. (ബു)', 'عَبْدِاللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 857, 857, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عَبْدِاللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَفَ فِي حَجَّةِ الْوَدَاعِ بِمِنًى لِلنَّاسِ يَسْأَلُونَهُ، فَجَاءَهُ رَجُلٌ فَقَالَ: لَمْ أَشْعُرْ فَحَلَقْتُ قَبْلَ أَنْ أَذْبَحَ، فَقَالَ: "اذْبَحْ وَلَا حَرَجَ". فَجَاءَ آخَرُ فَقَالَ: لَمْ أَشْعُرْ فَنَحَرْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ: "ارْمِ وَلَا حَرَجَ". فَمَا سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَيْءٍ قُدِّمَ وَلَا أُخِّرَ إِلَّا قَالَ: "افْعَلْ وَلَا حَرَجَ". (خ)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): ഹജ്ജതുൽ വിദാഇൽ ജനങ്ങളുടെ ചോദ്യങ്ങൾക്കും സംശയങ്ങൾക്കും മറുപടി പറയാൻ നബി(സ) നിൽക്കുകയായിരുന്നു. ഒരാൾ വന്നിട്ട് പറഞ്ഞു: അറിവില്ലായ്മ മൂലം ഞാൻ മുടി കളഞ്ഞത് ബലിനടത്തും മുമ്പാണ്. തിരുമേനി(സ) അരുളി: "ഇനി പോയി ബലി കഴിച്ച് കൊള്ളുക. അതിൽ തെറ്റൊന്നുമില്ല." അപ്പോൾ മറ്റൊരാൾ വന്ന് പറഞ്ഞു: അറിവില്ലായ്മ മൂലം കല്ലെറിയും മുമ്പ് ഞാൻ ബലി നടത്തി. തിരുമേനി(സ) അരുളി: "ഇനി കല്ലെറിഞ്ഞുകൊള്ളുക. തെറ്റൊന്നുമില്ല." അബ്ദുല്ലാഹിബ്നു അംറ്(റ) പറയുന്നു: ഏതെങ്കിലും ഒരു കാര്യം മുന്തിച്ചു അല്ലെങ്കിൽ പിന്തിച്ചു എന്ന് പറഞ്ഞ് വരുന്നവരോടൊക്കെ "നീ അങ്ങനെ ചെയ്ത് കൊള്ളുക, കുറ്റമൊന്നുമില്ല." എന്നേ നബി(സ) പറഞ്ഞുള്ളൂ. (ബു)', 'عَبْدِاللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 857, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى الله عليه وسلَّم نَهَى عَنِ الْغُلُوطَاتِ. (د)', 'മുആവിയ(റ): നബി(സ) തെറ്റുകൾ പറയുന്നത് വിരോധിച്ചിരിക്കുന്നു. (ദ)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَنْ أُفْتِيَ بِغَيْرِ عِلْمٍ كَانَ إِثْمُهُ عَلَى مَنْ أَفْتَاهُ. وَمَنْ أَشَارَ عَلَى أَخِيهِ بِأَمْرٍ - يَعْلَمُ أَنَّ الرُّشْدَ فِي غَيْرِهِ - فَقَدْ خَانَهُ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അറിവില്ലാതെ ആരെങ്കിലും ഫത്വ നൽകപ്പെട്ടാൽ അവന്റെ പാപം ഫത്വ നൽകിയവനാണ്. സത്യം വേറെയാണെന്ന് അറിഞ്ഞു കൊണ്ട് അതല്ലാത്ത ഒരു വിഷയത്തിൽ, തന്റെ സഹോദരന് സൂചന നൽകിയവൻ, നിശ്ചയം ആ സഹോദരനെ വഞ്ചിച്ചിരിക്കുന്നു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ جُنْدُبِ بْنِ عَبْدِ اللهِ البَجَلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "مَنْ قَالَ فِي كِتَابِ اللهِ عَزَّ وَجَلَّ بِرَأْيِهِ فَأَصَابَ فَقَدْ أَخْطَأَ". (د,ت)', 'ജുൻദുബുബ്നു അബ്ദില്ലാഹിൽ ബജലീ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ സ്വന്തം അഭിപ്രായം പറഞ്ഞാൽ - അത് സത്യമായാലും - അവന് പിഴച്ചിരിക്കുന്നു." (ദ,തു)', 'جُنْدُبِ بْنِ عَبْدِ اللهِ البَجَلِيِّ', 'ജുൻദുബുബ്നു അബ്ദില്ലാഹിൽ ബജലീ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ لَهُ فِي حَجَّةِ الْوَدَاعِ: اسْتَنْصِتِ النَّاسَ، فَقَالَ: لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ. (خ)', 'ജരീറുബ്നു അബ്ദില്ല(റ): നബി(സ) വിടവാങ്ങൽ ഹജ്ജിൽ അദ്ദേഹത്തോട് പറഞ്ഞു: "നീ ജനങ്ങളോട് മൗനം ദീക്ഷിക്കാൻ പറയുക." റസൂൽ(സ) പറഞ്ഞു: "എനിക്ക് ശേഷം നിങ്ങൾ പരസ്പരം കഴുത്തറുക്കുന്ന സത്യ നിഷേധികളായി മാറരുത്." (ബു)', 'جَرِيرِ بْنِ عَبْدِ اللهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 858, 858, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَسِّرُوا وَلَا تُعَسِّرُوا وَبَشِّرُوا وَلَا تُنَفِّرُوا". (خ)', 'അനസ്(റ): നബി(സ) പറയുന്നു: "നിങ്ങൾ ആശ്വാസം വരുത്തിക്കൊടുക്കുക. ബുദ്ധിമുട്ടാക്കാതിരിക്കുക. നിങ്ങൾ സന്തുഷ്ടരാക്കുക. വെറുപ്പിക്കാതിരിക്കുക." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ عُقْبَةَ بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ أَنَّهُ تَزَوَّجَ ابْنَةً لِأَبِي إِهَابِ بْنِ عَزِيزِ فَأَتَتْهُ امْرَأَةٌ فَقَالَتْ إِنِّي قَدْ أَرْضَعْتُ عُقْبَةَ وَالَّتِي تَزَوَّجَ بِهَا. فَقَالَ لَهَا عُقْبَةُ: مَا أَعْلَمُ أَنَّكِ أَرْضَعْتِنِي وَلَا أَخْبَرْتِنِي. فَرَكِبَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ فَسَأَلَهُ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَيْفَ وَقَدْ قِيلَ!" فَفَارَقَهَا عُقْبَةُ وَنَكَحَتْ زَوْجًا غَيْرَهُ. (خ)', 'ഉഖ്ബതുബ്നുൽ ഹാരിസ്(റ): അദ്ദേഹം അബീ ഇഹാബുബ്നു അസീസിന്റെ മകളെ വിവാഹം ചെയ്തു. ഉടനെ ഒരു സ്ത്രീ വന്ന് ഞാൻ ഉഖ്ബതിനും അദ്ദേഹം വിവാഹം ചെയ്ത സ്ത്രീക്കും മുലകൊടുത്തിട്ടുണ്ടെന്നു പറഞ്ഞു. ഇത് കേട്ടപ്പോൾ നിങ്ങൾ എനിക്ക് മുല തന്നിട്ടുണ്ടെന്ന് എനിക്കറിയില്ലെന്നും നിങ്ങൾ അതെന്നോട് പറഞ്ഞിട്ടില്ലായെന്നും ഉഖ്ബത് മറുപടി നൽകി. ഉടനെ നബി(സ)യെ കാണാൻ അദ്ദേഹം മദീനയിലേക്ക് പുറപ്പെട്ടു. അവിടെയെത്തിയ ശേഷം അദ്ദേഹം നബി(സ)യോട് വിവരം ചോദിച്ചു. നബി(സ) അരുൾ ചെയ്തു: "ഇങ്ങനെ പറയപ്പെടുന്ന സ്ഥിതിക്ക് എങ്ങനെയാണ് (നിങ്ങൾ ഭാര്യാഭർത്താക്കൻമാരായി ജീവിക്കുക)." ഉടനെ ഉഖ്ബത് വിവാഹബന്ധം വേർപെടുത്തി. അവൾ മറ്റൊരു ഭർത്താവിനെ സ്വീകരിച്ചു. (ബു)', 'عُقْبَةَ بْنِ الْحَارِثِ', 'ഉഖ്ബതുബ്നുൽ ഹാരിസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ وَمَعَهُ بِلَالٌ فَظَنَّ أَنَّهُ لَمْ يُسْمِعْ فَوَعَظَهُنَّ وَأَمَرَهُنَّ بِالصَّدَقَةِ فَجَعَلَتِ الْمَرْأَةُ تُلْقِي الْقُرْطَ وَالْخَاتَمَ وَبِلَالٌ يَأْخُذُ فِي طَرَفِ ثَوْبِهِ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ബിലാൽ(റ)വിന്റെ കൂടെ പുറപ്പെട്ടു. സ്ത്രീകളെ അവിടുത്തെ പ്രസംഗം കേൾപ്പിച്ചിട്ടില്ലെന്ന് നബി(സ)ക്ക് തോന്നി. അപ്പോൾ നബി(സ) അവരെ ഉപദേശിക്കുകയും ദാനധർമ്മങ്ങൾ ചെയ്യാൻ കൽപ്പിക്കുകയും ചെയ്തു. ഉടനെ സ്ത്രീകൾ കാതിൽ തൂക്കിയിരിക്കുന്ന ആഭരണങ്ങളും വിരലിലെ മോതിരങ്ങളും ഊരിയെടുത്ത് ദാനം ചെയ്യാൻ സന്നദ്ധരായി. ഹസ്രത് ബിലാൽ(റ) വസ്ത്രത്തിന്റെ തല കാണിച്ച് അത് വാങ്ങിക്കൊണ്ടിരുന്നു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَتِ النِّسَاءُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَلَبَنَا عَلَيْكَ الرِّجَالُ، فَاجْعَلْ لَنَا يَوْمًا مِنْ نَفْسِكَ، فَوَعَدَهُنَّ يَوْمًا لَقِيَهُنَّ فِيهِ فَوَعَظَهُنَّ وَأَمَرَهُنَّ فَكَانَ فِيمَا قَالَ لَهُنَّ: "مَا مِنْكُنَّ امْرَأَةٌ تُقَدِّمُ ثَلَاثَةً مِنْ وَلَدِهَا إِلَّا كَانَ لَهَا حِجَابًا مِنَ النَّارِ". فَقَالَتِ امْرَأَةٌ مِنْهُنَّ: وَاثْنَتَيْنِ، قَالَ: "وَاثْنَتَيْنِ". وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ لَمْ يَبْلُغُوا الحِنْثَ. (خ)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): സ്ത്രീകൾ തിരുനബി(സ)യോട് അപേക്ഷിച്ചു: താങ്കളെ സമീപിക്കുന്നതിൽ പുരുഷൻമാർ ഞങ്ങളെ കവച്ചു വെച്ചിരിക്കുന്നു. അത് കൊണ്ട് അങ്ങയുടെ ഔദാര്യത്താൽ ഞങ്ങൾക്കൊരു ദിവസം ഉപദേശം കേൾക്കാൻ അങ്ങ് നിശ്ചയിച്ച് തന്നാലും. തിരുമേനി(സ) അവർക്ക് ഒരു ദിവസം നിശ്ചയിച്ച് കൊടുത്തു. ആ ദിവസം തിരുമേനി(സ) അവരെക്കണ്ട് ഉപദേശങ്ങളും കൽപ്പനകളും നൽകി. അവരെ ഉപദേശിച്ച കൂട്ടത്തിൽ നബി(സ) പറഞ്ഞു: "മൂന്ന് സന്താനങ്ങൾ നിങ്ങൾക്ക് മുമ്പ് മരിച്ചാൽ നരകത്തിനും ആ സ്ത്രീക്കുമിടയിൽ ആ സന്താനങ്ങൾ ഒരു മറയായി നിലകൊള്ളാതിരിക്കില്ല." അവരിലൊരു സ്ത്രീ ചോദിച്ചു: രണ്ട് പേരായാലോ? റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് പേരായാലും."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=11 and h.hadith_no=85), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ لَمْ يَبْلُغُوا الحِنْثَ. (خ)', 'മറ്റൊരു നിവേദനത്തിൽ കാണാം: "കുട്ടികൾക്ക് പ്രായപൂർത്തിയായിട്ടില്ലായെങ്കിൽ." (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتِ: اسْتَيْقَظَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَقَالَ: "سُبْحَانَ اللهِ! مَاذَا أُنْزِلَ اللَّيْلَةَ مِنَ الْفِتَنِ! وَمَاذَا فُتِحَ مِنَ الْخَزَائِنِ! أَيْقِظُوا صَوَاحِبَاتِ الْحُجَرِ، فَرُبَّ كَاسِيَةٍ فِي الدُّنْيَا عَارِيَةٍ فِي الْآخِرَةِ". (خ)', 'ഉമ്മുസലമ(റ): നബി(സ) ഒരു രാത്രി ഉണർന്ന് കൊണ്ട് പറഞ്ഞു: "സുബ്‌ഹാനല്ലാഹ്, ഇന്ന് രാത്രിയിൽ എന്ത് വിപത്താണ് ഇറങ്ങിയിരിക്കുന്നത്. എന്ത് ശേഖരങ്ങളാണ് തുറക്കപ്പെട്ടത്. വീട് നിവാസികളെ, നിങ്ങൾ ഉണരുക. ദുനിയാവിൽ വസ്ത്രം ധരിച്ച എത്ര പേരാണ് അന്ത്യനാളിൽ നഗ്നരാകുന്നത്." (ബു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عَبْدِاللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّى بِنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ فِي آخِرِ حَيَاتِهِ، فَلَمَّا سَلَّمَ قَامَ فَقَالَ: "أَرَأَيْتَكُمْ لَيْلَتَكُمْ هَذِهِ؟ فَإِنَّ رَأْسَ مِائَةِ سَنَةٍ مِنْهَا لَا يَبْقَى مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ". [أي من الحاضرين] (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) അവിടുത്തെ അവസാന ദിവസങ്ങളിൽ ഇശാ നമസ്കരിച്ചു. നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചുകൊണ്ട് നബി(സ) പറഞ്ഞു: "ഈ രാത്രി ഏതാണെന്ന് നിങ്ങൾക്കറിയുമോ? ഈ രാവ് മുതൽ നൂറ് കൊല്ലം തികയുമ്പോൾ ഇന്ന് ഭൂമുഖത്ത് ജീവിക്കുന്ന ഒരാളും മരിച്ചു പോകാതെ ശേഷിക്കില്ല." (ബു)', 'عَبْدِاللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'أي من الحاضرين', null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بِتُّ فِي بَيْتِ خَالَتِي مَيْمُونَةَ بِنْتِ الْحَارِثِ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِنْدَهَا فِي لَيْلَتِهَا، فَصَلَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ ثُمَّ جَاءَ إِلَى مَنْزِلِهِ، فَصَلَّى أَرْبَعَ رَكَعَاتٍ ثُمَّ نَامَ، ثُمَّ قَامَ ثُمَّ قَالَ: "نَامَ الْغُلَيِّمُ". أَوْ كَلِمَةً تُشْبِهُهَا ثُمَّ قَامَ فَقُمْتُ عَنْ يَسَارِهِ فَجَعَلَنِي عَنْ يَمِينِهِ، فَصَلَّى خَمْسَ رَكَعَاتٍ ثُمَّ صَلَّى رَكْعَتَيْنِ ثُمَّ نَامَ حَتَّى سَمِعْتُ غَطِيطَهُ أَوْ خَطِيطَهُ، ثُمَّ خَرَجَ إِلَى الصَّلَاةِ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ തിരുമേനി(സ)യുടെ പത്നിയും എന്റെ മാതൃസഹോദരിയുമായ മൈമൂന ബീവി(റ)യുടെ വീട്ടിൽ താമസിച്ചു. ആ രാത്രി നബി(സ) അവരുടെ അടുത്തായിരുന്നു. ഇശാ നിസ്കരിച്ച് നബി(സ) വീട്ടിലേക്ക് വന്നു. നാല് റക്അത്ത് നിസ്കരിച്ച് അവിടുന്ന് ഉറങ്ങി. പിന്നെ ഉറക്കമുണർന്ന് കൊണ്ട് നബി(സ) പറഞ്ഞു: "ചെറിയ കുഞ്ഞ് ഉറങ്ങിയിരിക്കുന്നു". അല്ലെങ്കിൽ അതുപോലെ ഒരു വാക്ക്. പിന്നെ നബി(സ) നിസ്കരിക്കാൻ നിന്നു. ഞാൻ നബി(സ)യുടെ ഇടത് ഭാഗത്ത് നിന്നു. അവിടന്ന് എന്നെ വലത് ഭാഗത്താക്കി. നബി(സ) അഞ്ച് റക്അത്ത് നിസ്കരിച്ചു. വീണ്ടും രണ്ട് റക്അത് നിസ്കരിച്ച് ഉറങ്ങി. ഞാൻ അവിടത്തെ ഉറക്കത്തിന്റെ ശബ്ദം കേട്ടു. വീണ്ടും നബി(സ) നിസ്കാരത്തിലേക്ക് മടങ്ങി. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 860, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَخَوَّلُنَا بِالْمَوْعِظَةِ فِي الْأَيَّامِ كَرَاهَةَ السَّآمَةِ عَلَيْنَا. (خ)', 'ഇബ്നുമസ്ഊദ്(റ): ഞങ്ങൾ മുഷിഞ്ഞു പോകുമോ എന്ന് വിചാരിച്ച് ചില പ്രത്യേക ദിവസങ്ങളിൽ മാത്രമാണ് നബി(സ) ഞങ്ങൾക്ക് ഉപദേശം തന്നിരുന്നത്. (ബു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 861, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ مَا الْقِتَالُ فِي سَبِيلِ اللَّهِ؟ فَإِنَّ أَحَدَنَا يُقَاتِلُ غَضَبًا وَيُقَاتِلُ حَمِيَّةً! فَقَالَ: "مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ". (خ)', 'അബൂമൂസ(റ): ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവിന്റെ മാർഗത്തിലുള്ള യുദ്ധമേതാണ്? ഞങ്ങളിൽ ചിലർ കോപം കൊണ്ടും അഭിമാനത്തിന് വേണ്ടിയും യുദ്ധം ചെയ്യാറുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിന്റെ വചനം ഉന്നതമാക്കാൻ വേണ്ടി യുദ്ധം ചെയ്താൽ അതാണ് അല്ലാഹുവിന്റെ മാർഗത്തിലുള്ള യുദ്ധം." (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 861, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَجُلًا سَأَلَهُ مَا يَلْبَسُ الْمُحْرِمُ؟ قَالَ: "لَا يَلْبَسُ الْقَمِيصَ وَلَا الْعِمَامَةَ وَلَا السَّرَاوِيلَ وَلَا الْبُرْنُسَ وَلَا ثَوْبًا مَسَّهُ الْوَرْسُ أَوِ الزَّعْفَرَانُ، فَإِنْ لَمْ يَجِدِ النَّعْلَيْنِ فَلْيَلْبَسِ الْخُفَّيْنِ وَلْيَقْطَعْهُمَا حَتَّى يَكُونَا تَحْتَ الْكَعْبَيْنِ". (خ)', 'ഇബ്നുഉമർ(റ) ഹജ്ജിൽ പ്രവേശിച്ചാൽ ഏത് വസ്ത്രമാണ് ധരിക്കേണ്ടതെന്ന് ഒരാൾ നബി(സ)യോട് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "നീളൻ കുപ്പായം, തലപ്പാവ്, പൈജാമ, തൊപ്പി, വർസോ കുങ്കുമമോ പൂശിയ വസ്ത്രം ഇവയൊന്നും അവൻ ധരിക്കരുത്. അവന് ചെരുപ്പില്ലെങ്കിൽ ഖുഫ്ഫ ധരിച്ച് കൊള്ളട്ടെ. രണ്ട് ഖുഫ്ഫയും ഞെരിയാണിയുടെ താഴ്ഭാഗത്ത് മുറിച്ചെടുക്കുക." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 861, 861, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ عَوْفِ بْنِ مَالِكِ الْأَشْجَعِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَقُصُّ إِلَّا أَمِيرٌ أَوْ مَأْمُورٌ أَوْ مُخْتَالٌ". (د)', 'ഔഫുബ്നു മാലികിൽ അശ്ജഇയ്യ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഭരണാധികാരിയും അധികാര മേൽപ്പിക്കപ്പെട്ടവനും സ്ഥാനമാനങ്ങൾ ആഗ്രഹിക്കുന്ന അഹങ്കാരിയും മാത്രമാണ് ഉപദേശങ്ങൾ നൽകുക." (ദ)', 'عَوْفِ بْنِ مَالِكِ الْأَشْجَعِيِّ', 'ഔഫുബ്നു മാലികിൽ അശ്ജഇയ്യ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 861, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَلَسْتُ فِي عِصَابَةٍ مِنْ ضُعَفَاءِ الْمُهَاجِرِينَ، وَإِنَّ بَعْضَهُمْ لَيَسْتَتِرُ بِبَعْضٍ مِنَ الْعُرْيِ، وَقَارِئُ يَقْرَأُ عَلَيْنَا، إِذْ جَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَامَ عَلَيْنَا، فَلَمَّا قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَكَتَ الْقَارِئُ، فَسَلَّمَ ثُمَّ قَالَ: "مَا كُنْتُمْ تَصْنَعُونَ". قُلْنَا: يَا رَسُولَ اللهِ، إِنَّهُ كَانَ قَارِئٌ لَنَا يَقْرَأُ عَلَيْنَا، فَكُنَّا نَسْتَمِعُ إِلَى كِتَابِ اللهِ. قَالَ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ مِنْ أُمَّتِي مَنْ أُمِرْتُ أَنْ أَصْبِرَ نَفْسِي مَعَهُمْ". قَالَ: فَجَلَسَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَسَطَنَا لِيَعْدِلَ بِنَفْسِهِ فِينَا، ثُمَّ قَالَ بِيَدِهِ هَكَذَا، فَتَحَلَّقُوا، وَبَرَزَتْ وُجُوهُهُمْ لَهُ، قَالَ: فَمَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَرَفَ مِنْهُمْ أَحَدًا غَيْرِي، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبْشِرُوا يَا مَعْشَرَ صَعَالِيكِ الْمُهَاجِرِينَ بِالنُّورِ التَّامِّ يَوْمَ الْقِيَامَةِ، تَدْخُلُونَ الْجَنَّةَ قَبْلَ أَغْنِيَاءِ النَّاسِ بِنِصْفِ يَوْمٍ، وَذَاكَ خَمْسُ مِائَةِ سَنَةٍ". (د,ت,جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): ഞാൻ ദരിദ്രരായ മുഹാജിറുകളുടെ സംഘത്തിലായിരുന്നു. അവരിൽ ചിലർ മറ്റു ചിലരെക്കൊണ്ട് ഔറത് മറക്കുന്നു. ഒരാൾ ഞങ്ങൾക്ക് ഖുർആൻ ഓതിക്കേൾപ്പിക്കുന്നുണ്ട്. അപ്പോൾ റസൂൽ(സ) വന്ന് ഞങ്ങളുടെ അടുത്ത് നിന്നു. നബി(സ) നിന്നപ്പോൾ ഓതുന്നവൻ ഓത്ത് നിർത്തി. നബി(സ) ഞങ്ങളോട് സലാം ചൊല്ലിയിട്ട് പറഞ്ഞു. "നിങ്ങളെന്താണ് ചെയ്തിരുന്നത്.” ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഖുർആൻ ഓതിത്തരുന്നയാൾ ഞങ്ങൾക്ക് ഓതിത്തരികയായിരുന്നു. ഞങ്ങൾ അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലേക്ക് ശ്രദ്ധിക്കുകയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആരുടെ കൂടെയാണോ എന്റെ ശരീരത്തെ ക്ഷമിപ്പിക്കാൻ കൽപ്പിക്കപ്പെട്ടത് അവരെ എന്റെ സമൂഹത്തിൽ നിയോഗിച്ച അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും.” പിന്നെ നബി(സ) ഞങ്ങൾക്കിടയിൽ നീതി ചെയ്യാൻ ഞങ്ങളുടെ കൂടെ ഇരുന്നു. പിന്നെ അവരോട് റസൂൽ(സ) ആംഗ്യം കാണിച്ചു: അവർ വട്ടമിട്ടിരിക്കുകയും അവരുടെ മുഖങ്ങൾ നബി(സ)ക്ക് വെളിവാകുകയും ചെയ്തു. അബൂസഈദുൽ ഖുദ്‌രി(റ) പറയുന്നു: അവരിൽ എന്നെഒഴിച്ച് നബി(സ) ആരെയും അറിയില്ലെന്ന് എനിക്ക് തോന്നി. റസൂൽ(സ) പറഞ്ഞു: "ദരിദ്രരായ മുഹാജിറുകളേ, നിങ്ങൾ അന്ത്യ ദിനത്തിലെ സമ്പൂർണ്ണ പ്രകാശം കൊണ്ട് സന്തോഷിക്കുക. ധനികരേക്കാൾ അര ദിവസം മുമ്പ് നിങ്ങൾ സ്വർഗത്തിൽ പ്രവേശിക്കും. അര ദിവസം എന്നത് അഞ്ഞൂറ് വർഷമാണ്.” (ദ,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَأَنْ أَقْعُدَ مَعَ قَوْمٍ يَذْكُرُونَ اللهَ تَعَالَى - مِنْ صَلَاةِ الْغَدَاةِ حَتَّى تَطْلُعَ الشَّمْسُ - أَحَبُّ إِلَيَّ مِنْ أَنْ أَعْتِقَ أَرْبَعَةً مِنْ وَلَدِ إِسْمَعِيلَ وَلَأَنْ أَقْعُدَ مَعَ قَوْمٍ يَذْكُرُونَ اللهَ - مِنْ صَلَاةِ الْعَصْرِ إِلَى أَنْ تَغْرُبَ الشَّمْسُ - أَحَبُّ إِلَيَّ مِنْ أَنْ أَعْتِقَ أَرْبَعَةً". (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രഭാതനിസ്കാരം മുതൽ സൂര്യൻ ഉദിക്കുന്നത് വരെ അല്ലാഹുവിനെ സ്മരിക്കുന്നവരുടെ കൂടെ ഇരിക്കുന്നത്, ഇസ്മാഈൽ സന്താനങ്ങളിലെ നാലു പേരെ മോചിപ്പിക്കുന്നതിനേക്കാൾ എനിക്ക് ഇഷ്ടമാണ്. അസർ നമസ്കാരം മുതൽ സൂര്യൻ അസ്തമിക്കുന്നത് വരെ അല്ലാഹുവിനെ സ്മരിക്കുന്നവരുടെ കൂടെ ഇരിക്കുന്നത് നാലുപേരെ മോചിപ്പിക്കുന്നതിനേക്കാൾ എനിക്ക് ഇഷ്ടമാണ്.” (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْرَأْ عَلَيَّ سُورَةَ النِّسَاءِ". قَالَ: قُلْتُ: أَقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ؟ قَالَ: "إِنِّي أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي". قَالَ: فَقَرَأْتُ عَلَيْهِ، حَتَّى إِذَا انْتَهَيْتُ إِلَى قَوْلِهِ: {فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ} الْآيَةَ [٤١] فَرَفَعْتُ رَأْسِي فَإِذَا عَيْنَاهُ تَهْمُلَانِ. (ق،د،ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): എന്നോട് റസൂൽ(സ) പറഞ്ഞു: “എനിക്ക് നിസാഅ് സൂറത് ഓതി കേൾപ്പിക്കുക.” ഞാൻ ചോദിച്ചു: അങ്ങേക്കല്ലേ അതവതരിക്കപ്പെട്ടത്. ഞാൻ എങ്ങനെയാണ് അങ്ങയെ ഓതിക്കേൾപ്പിക്കുക. റസൂൽ(സ) പറഞ്ഞു: “ഞാനല്ലാത്തവരിൽ നിന്ന് അത് കേൾക്കാൻ ഞാൻ ആഗ്രഹിക്കുന്നു.” അവിടത്തേക്ക് ഞാനത് ഓതിക്കേൾപ്പിച്ചു. അങ്ങനെ ‘ഞാൻ എല്ലാ സമൂഹത്തിൽ നിന്നും ഒരു സാക്ഷിയെ കൊണ്ടു വന്നാലുള്ള സന്ദർഭം എങ്ങനെയായിരിക്കും.'' (നിസാഅ്: 41) എന്ന സൂക്തം വരെ എത്തി. അപ്പോൾ ഞാൻ തലയുയർത്തി നോക്കി. റസൂൽ(സ)യുടെ രണ്ട് നയനങ്ങളും ഒഴുകുന്നുണ്ടായിരുന്നു. (ബു,മു,ദ,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], '٤١', null, 862, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: كَانَ مُعَاذُ رَدِيفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الرَّحْلِ فَقَالَ: "يَا مُعَاذُ". قَالَ: لَبَّيْكَ يَا رَسُولَ اللَّهِ وَسَعْدَيْكَ، ثَلَاثًا، قَالَ: "مَا مِنْ أَحَدٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ صِدْقًا مِنْ قَلْبِهِ إِلَّا حَرَّمَهُ اللَّهُ عَلَى النَّارِ". قَالَ: يَا رَسُولَ اللَّهِ أَفَلَا أُخْبِرُ بِهِ النَّاسَ فَيَسْتَبْشِرُونَ؟ قَالَ: "إِذًا يَتَّكِلُوا". وَأَخْبَرَ بِهَا مُعَاذٌ عِنْدَ مَوْتِهِ تَأَثُّمًا. (خ)', 'അനസ്(റ): മുആദ്(റ) ഒട്ടകപ്പുറത്ത് റസൂൽ(സ)യുടെ പിറകിൽ യാത്ര ചെയ്യുകയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) "മുആദേ" എന്ന് വിളിച്ചു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാനിതാ അങ്ങയുടെ വിളിക്ക് ഉത്തരം നൽകുന്നു. ഇത് മൂന്ന് പ്രാവശ്യം ആവർത്തിച്ചു. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ഒരാരാധ്യനില്ലെന്നും മുഹമ്മദ്(സ) അല്ലാഹുവിന്റെ ദൂതനാണെന്നും മനസ്സിലുറപ്പിച്ച് ആരെങ്കിലും സാക്ഷ്യം വഹിച്ചാൽ അവന് അല്ലാഹു നരകം നിഷിധമാക്കുക തന്നെ ചെയ്യും." മുആദ്(റ) പറഞ്ഞു: ജനങ്ങൾ സന്തുഷ്ടരാകാൻ ഇത് ഞാൻ അവരെ അറിയിക്കട്ടെയോ. നബി(സ) പറഞ്ഞു: "നീ അങ്ങനെ പറഞ്ഞാൽ ജനങ്ങൾ അതിന്മേൽ ഭരമേൽപ്പിക്കും." കുറ്റത്തിൽ നിന്ന് ഒഴിവാകാൻ വേണ്ടി മരണവേളയിൽ മാത്രമാണ് ഇക്കാര്യം മുആദ്(റ) തുറന്ന് പറഞ്ഞത്. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ لَا أَكَادُ أُدْرِكُ الصَّلَاةَ مِمَّا يُطَوِّلُ بِنَا فُلَانٌ. فَمَا رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَوْعِظَةٍ أَشَدَّ غَضَبًا مِنْ يَوْمِئِذٍ فَقَالَ: "أَيُّهَا النَّاسُ إِنَّكُمْ مُنَفِّرُونَ فَمَنْ صَلَّى بِالنَّاسِ فَلْيُخَفِّفْ فَإِنَّ فِيهِمُ الْمَرِيضَ وَالضَّعِيفَ وَذَا الحَاجَةِ". (خ)', 'അബൂ മസ്ഊദുൽ അൻസാരി(റ): ഒരാൾ റസൂൽ(സ)യോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇന്നയാൾ നിസ്കാരം ദീർഘിപ്പിക്കുന്നത് കാരണം എനിക്ക് ജമാഅത്തിൽ പങ്കെടുക്കാൻ കഴിയുന്നില്ല. അബൂമസ്ഊദ്(റ) പറയുന്നു: നബി(സ) ഉപദേശിക്കുമ്പോൾ ഇത്രയും കോപിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളേ, നിങ്ങൾ ആളുകളെ വെറുപ്പിക്കുന്നവരാണ്. ആരെങ്കിലും ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചാൽ അവൻ നിസ്കാരം ലഘൂകരിക്കട്ടെ. നിശ്ചയം അവരിൽ രോഗിയും പാവപ്പെട്ടവനും ആവശ്യക്കാരനുമുണ്ടാകും." (ബു)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂ മസ്ഊദുൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 863, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ سَأَلَهُ رَجُلٌ عَنِ اللُّقَطَةِ، فَقَالَ: "اعْرِفْ وِكَاءَهَا". أَوْ قَالَ: "وِعَاءَهَا وَعِفَاصَهَا ثُمَّ عَرِّفْهَا سَنَةً ثُمَّ اسْتَمْتِعْ بِهَا، فَإِنْ جَاءَ رَبُّهَا فَأَدِّهَا إِلَيْهِ". قَالَ: فَضَالَّةُ الْإِبِلِ؟ فَغَضِبَ حَتَّى احْمَرَّتْ وَجْنَتَاهُ، أَوْ قَالَ: احْمَرَّ وَجْهُهُ، فَقَالَ: "وَمَا لَكَ وَلَهَا مَعَهَا سِقَاؤُهَا وَحِذَاؤُهَا تَرِدُ الْمَاءَ وَتَرْعَى الشَّجَرَ فَذَرْهَا حَتَّى يَلْقَاهَا رَبُّهَا". قَالَ: فَضَالَّةُ الْغَنَمِ. قَالَ: "لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ". (خ)', 'സൈദുബ്നു ഖാലിദുൽ ജുഹനീ(റ): കളഞ്ഞ് കിട്ടിയ സാധനത്തെക്കുറിച്ച് നബി(സ)യോട് ഒരാൾ ചോദിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "നീ അതിന്റെ കെട്ട്, അല്ലെങ്കിൽ അതിന്റെ പാത്രം അതിന്റെ സഞ്ചി, ശരിക്ക് മനസ്സിലാക്കുക. ശേഷം ഒരു കൊല്ലം ജനങ്ങളുടെ ശ്രദ്ധയിൽ പെടുത്തുക. അതിനു ശേഷം നീ അത് ഉപയോഗിക്കുക. അതിന്റെ ഉടമസ്ഥൻ വന്നാൽ അവനത് വിട്ടുകൊടുത്തേക്കുക." അപ്പോൾ ഒരാൾ ചോദിച്ചു: ഒട്ടകം കളഞ്ഞ് കിട്ടിയാലോ. ഇത് കേട്ടപ്പോൾ റസൂൽ(സ)ക്ക് കോപം വന്നു. അവിടത്തെ മുഖം ചുവന്നു. തിരുമേനി(സ) പറഞ്ഞു: "നിനക്ക് ഒട്ടകവുമായി എന്തു ബന്ധം?. വെള്ളം കുടിക്കുവാനുള്ള പാത്രവും അതിന്റെ ചെരുപ്പും അതോടൊപ്പം തന്നെയുണ്ട്. അത് സ്വയം ജലാശയത്തിൽ ചെല്ലുന്നു. മരങ്ങളുടെ ഇല തിന്നുന്നു. അത്കൊണ്ട് അതിന്റെ ഉടമസ്ഥൻ അതിനെ കണ്ടുമുട്ടുന്നത് വരെ നീ അതിനെ അതിന്റെ വഴിക്ക് വിട്ടേക്കുക." ആ മനുഷ്യൻ ചോദിച്ചു: ഒരാടിനെ കളഞ്ഞ് കിട്ടിയാലോ? റസൂൽ(സ) പറഞ്ഞു: "ആട് നിനക്കോ നിന്റെ സഹോദരനോ ചെന്നായക്കോ ഉള്ളതാണ്." (ബു)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദുൽ ജുഹനീ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ عَنْ أَشْيَاءَ كَرِهَهَا فَلَمَّا أُكْثِرَ عَلَيْهِ غَضِبَ ثُمَّ قَالَ لِلنَّاسِ: سَلُونِي عَمَّا شِئْتُمْ قَالَ رَجُلٌ: مَنْ أَبِي؟ قَالَ: "أَبُوكَ حُذَافَةُ". فَقَامَ آخَرُ فَقَالَ: مَنْ أَبِي يَا رَسُولَ اللهِ؟ فَقَالَ: "أَبُوكَ سَالِمٌ مَوْلَى شَيْبَةَ". فَلَمَّا رَأَى عُمَرُ مَا فِي وَجْهِهِ قَالَ: يَا رَسُولَ اللهِ إِنَّا نَتُوبُ إِلَى اللهِ عَزَّ وَجَلَّ. (خ)', 'അബൂമൂസ(റ): നബി(സ) വെറുക്കുന്ന ചില കാര്യങ്ങളെക്കുറിച്ച് അവിടത്തോട് ചോദിക്കപ്പെട്ടു. ചോദ്യം അധികരിച്ചപ്പോൾ നബി(സ)ക്ക് ദേഷ്യം വന്നു. പിന്നെ അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ ഉദ്ദേശിക്കുന്നത് ചോദിച്ചു കൊള്ളുക." അപ്പോൾ ഒരാൾ ചോദിച്ചു: ആരാണ് എന്റെ പിതാവ്? നബി തിരുമേനി(സ) പ്രതിവചിച്ചു: "നിന്റെ പിതാവ് ഹുദാഫയാണ്." വേറൊരാൾ എണീറ്റ് കൊണ്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ പിതാവ് ആരാണ്? റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ പിതാവ് ശൈബയുടെ അടിമയായ സാലിമാണ്." ഉമർ(റ) റസൂൽ(സ)യുടെ വിഷമം കണ്ടപ്പോൾ ഇങ്ങനെ പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, ഞങ്ങൾ അല്ലാഹുവിലേക്ക് ഖേദിച്ചു മടങ്ങുന്നു. (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ- رِوَايَةً- قَالَ: "يُوشِكُ أَنْ يَضْرِبَ النَّاسُ أَكْبَادَ الْإِبِلِ، يَطْلُبُونَ الْعِلْمَ، فَلَا يَجِدُونَ أَحَدًا أَعْلَمَ مِنْ عَالِمِ الْمَدِينَةِ". حسن. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾ വിജ്ഞാനംതേടി യാത്രചെയ്യും. മദീനയിലെ പണ്ഡിതനേക്കാൾ ജ്ഞാനമുള്ള ഒരാളെയും അവർക്ക് കിട്ടുകയില്ല. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 864, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَامَ مُوسَى النَّبِيُّ خَطِيبًا فِي بَنِي إِسْرَائِيلَ، فَسُئِلَ أَيُّ النَّاسِ أَعْلَمُ؟ فَقَالَ: أَنَا أَعْلَمُ، فَعَتَبَ اللهُ عَلَيْهِ إِذْ لَمْ يَرُدَّ الْعِلْمَ إِلَى اللهِ، فَأَوْحَى اللهُ إِلَيْهِ أَنَّ عَبْدًا مِنْ عِبَادِي بِمَجْمَعِ الْبَحْرَيْنِ هُوَ أَعْلَمُ مِنْكَ، قَالَ يَا رَبِّ وَكَيْفَ بِهِ؟ فَقِيلَ لَهُ: احْمِلْ حُوتًا فِي مِكْتَلٍ، فَإِذَا فَقَدْتَهُ فَهُوَ ثَمَّ، فَانْطَلَقَ وَانْطَلَقَ بِفَتَاهُ يُوشَعَ بْنِ نُونٍ وَحَمَلَا حُوتًا فِي مِكْتَلٍ، حَتَّى كَانَا عِنْدَ الصَّخْرَةِ وَضَعَا رُءُوسَهُمَا فَنَامَا، فَانْسَلَّ الْحُوتُ مِنَ الْمِكْتَلِ، فَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ سَرَبًا، وَكَانَ لِمُوسَى وَفَتَاهُ عَجَبًا، فَانْطَلَقَا بَقِيَّةَ لَيْلَتِهِمَا وَيَوْمَهُمَا، فَلَمَّا أَصْبَحَ قَالَ مُوسَى لِفَتَاهُ: آتِنَا غَدَاءَنَا لَقَدْ لَقِينَا مِنْ سَفَرِنَا هَذَا نَصَبًا، وَلَمْ يَجِدْ مُوسَى مَسًّا مِنَ النَّصَبِ حَتَّى جَاوَزَ الْمَكَانَ الَّذِي أُمِرَ بِهِ، فَقَالَ لَهُ فَتَاهُ: أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ، قَالَ مُوسَى: ذَلِكَ مَا كُنَّا نَبْغِي فَارْتَدَّا عَلَى آثَارِهِمَا قَصَصًا، فَلَمَّا انْتَهَيَا إِلَى الصَّخْرَةِ إِذَا رَجُلٌ مُسَجًّى بِثَوْبٍ أَوْ قَالَ: تَسَجَّى بِثَوْبِهِ، فَسَلَّمَ مُوسَى، فَقَالَ الْخَضِرُ: وَأَنَّى بِأَرْضِكَ السَّلَامُ؟ فَقَالَ: أَنَا مُوسَى، فَقَالَ: مُوسَى بَنِي إِسْرَائِيلَ؟ قَالَ: نَعَمْ، قَالَ: هَلْ أَتَّبِعُكَ عَلَى أَنْ تُعَلِّمَنِي مِمَّا عُلِّمْتَ رَشَدًا؟ قَالَ: إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا، يَا مُوسَى إِنِّي عَلَى عِلْمٍ مِنْ عِلْمِ اللهِ عَلَّمَنِيهِ لَا تَعْلَمُهُ أَنْتَ وَأَنْتَ عَلَى عِلْمٍ عَلَّمَكَهُ لَا أَعْلَمُهُ، قَالَ: سَتَجِدُنِي إِنْ شَاءَ اللهُ صَابِرًا وَلَا أَعْصِي لَكَ أَمْرًا، فَانْطَلَقَا يَمْشِيَانِ عَلَى سَاحِلِ الْبَحْرِ لَيْسَ لَهُمَا سَفِينَةٌ، فَمَرَّتْ بِهِمَا سَفِينَةٌ فَكَلَّمُوهُمْ أَنْ يَحْمِلُوهُمَا، فَعُرِفَ الْخَضِرُ فَحَمَلُوهُمَا بِغَيْرِ نَوْلٍ، فَجَاءَ عُصْفُورٌ فَوَقَعَ عَلَى حَرْفِ السَّفِينَةِ فَنَقَرَ نَقْرَةً أَوْ نَقْرَتَيْنِ مِنَ الْبَحْرِ فَقَالَ الْخَضِرُ: يَا مُوسَى مَا نَقَصَ عِلْمِي وَعِلْمُكَ مِنْ عِلْمِ اللهِ إِلَّا كَنَقْرَةِ هَذَا الْعُصْفُورِ فِي الْبَحْرِ، فَعَمَدَ الْخَضِرُ إِلَى لَوْحٍ مِنْ أَلْوَاحِ السَّفِينَةِ فَنَزَعَهُ، فَقَالَ مُوسَى: قَوْمٌ حَمَلُونَا بِغَيْرِ نَوْلٍ عَمَدْتَ إِلَى سَفِينَتِهِمْ فَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا، قَالَ أَلَمْ أَقُلْ إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا، قَالَ لَا تُؤَاخِذْنِي بِمَا نَسِيتُ وَلَا تُرْهِقْنِي مِنْ أَمْرِي عُسْرًا، فَكَانَتِ الْأُولَى مِنْ مُوسَى نِسْيَانًا، فَانْطَلَقَا فَإِذَا غُلَامٌ يَلْعَبُ مَعَ الْغِلْمَانِ، فَأَخَذَ الْخَضِرُ بِرَأْسِهِ مِنْ أَعْلَاهُ فَاقْتَلَعَ رَأْسَهُ بِيَدِهِ، فَقَالَ مُوسَى: أَقَتَلْتَ نَفْسًا زَكِيَّةً بِغَيْرِ نَفْسٍ، قَالَ أَلَمْ أَقُلْ لَكَ إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا، فَانْطَلَقَا حَتَّى إِذَا أَتَيَا أَهْلَ قَرْيَةٍ اسْتَطْعَمَا أَهْلَهَا فَأَبَوْا أَنْ يُضَيِّفُوهُمَا، فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ، قَالَ الْخَضِرُ بِيَدِهِ فَأَقَامَهُ فَقَالَ لَهُ مُوسَى: لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْرًا، قَالَ: هَذَا فِرَاقُ بَيْنِي وَبَيْنِكَ". قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَرْحَمُ اللهُ مُوسَى لَوَدِدْنَا لَوْ صَبَرَ حَتَّى يُقَصَّ عَلَيْنَا مِنْ أَمْرِهِمَا". (خ)', 'ഉബയ്യുബ്‌നു കഅ്ബ്(റ): നബി(സ)പറഞ്ഞു: "മൂസാനബി(അ) ഒരിക്കൽ ഇസ്രയേലിയർക്കിടയിൽ പ്രസംഗിക്കാൻ എഴുന്നേറ്റ് നിന്നു. അപ്പോൾ ചോദിക്കപ്പെട്ടു: മനുഷ്യരിൽ ഏറ്റവും വലിയ ജ്ഞാനി ആരാണ്? മൂസാ(അ) പറഞ്ഞു: ഞാനാണ് കൂടുതൽ അറിവുള്ളയാൾ. കൂടുതൽ ജ്ഞാനം അല്ലാഹുവിനാണുള്ളതെന്ന് അദ്ദേഹം പറയാത്ത കാരണം അല്ലാഹു അദ്ദേഹത്തെ കുറ്റപ്പെടുത്തി. അല്ലാഹു മൂസാ(അ)മിന് ദിവ്യബോധനം നൽകി: രണ്ട് സമുദ്രങ്ങൾ സമ്മേളിക്കുന്നിടത്ത് നമ്മുടെ ഒരു ദാസൻ ഇരിക്കുന്നുണ്ട്, അദ്ദേഹം നിങ്ങളേക്കാൾ ജ്ഞാനിയാണ്. മൂസാനബി(അ) ചോദിച്ചു: രക്ഷിതാവേ, അദ്ദേഹവുമായി കണ്ടുമുട്ടാൻ എന്തുണ്ട് മാർഗം? അല്ലാഹു പറഞ്ഞു: നീ കുട്ടയിൽ ഒരു മത്സ്യം കരുതുക. അത് നിനക്ക് നഷ്ടപ്പെടുന്നിടത്ത് അദ്ദേഹം ഉണ്ടാകും. മൂസാ(അ) പോയി. നൂനിന്റെ പുത്രൻ യൂശഅ് എന്ന് പേരുള്ള ഒരു ഭൃത്യനെയും കൊണ്ടാണ് അദ്ദേഹം പോയത്. രണ്ട് പേരും ഒരു മത്സ്യത്തെ കുട്ടയിലിട്ട് കൊണ്ടുപോയി. ഒരു പാറക്കല്ലിനടുത്തെത്തിയപ്പോൾ ഇരുവരും അതിൻമേൽ കിടന്നുറങ്ങി. അതിനിടക്ക് മത്സ്യം കുട്ടയിൽ നിന്ന് പുറത്ത് ചാടി. സമുദ്രത്തിൽ അതിന്റെ വഴിക്ക് പാഞ്ഞുപോയി. ആ സംഭവം മൂസാ(അ)നും ഭൃത്യനും അത്ഭുതമായിത്തോന്നി. രണ്ട് പേരും ഒരു പകലും രാത്രി ബാക്കിയുള്ള സമയവും നടന്നു. നമ്മുടെ ആഹാരം കൊണ്ട് വരൂ. ഈ രാത്രിയിൽ നാം വല്ലാതെ ക്ഷീണിച്ച് പോയി. പ്രഭാതമായപ്പോൾ മൂസാനബി(അ) ഭൃത്യനോട് പറഞ്ഞു: മൂസാനബി(അ)മിന് നിർദ്ദേശിച്ച് കൊടുത്തിരുന്ന സ്ഥലം കടന്നു പോകും വരെ യാതൊരു ക്ഷീണവും തോന്നിയിരുന്നില്ല. ഭൃത്യൻ പറഞ്ഞു: കഥയറിയാമോ? നാം പാറയിൽ അഭയം പ്രാപിച്ചപ്പോൾ മത്സ്യത്തിന്റെ കാര്യം ഞാൻ മറന്നു പോയി. മൂസാ(അ) പറഞ്ഞു: അത് തന്നെയാണ് നാം അന്വേഷിച്ചു കൊണ്ടിരുന്ന സ്ഥലം. രണ്ട്പേരും ചുവടടികൾ സൂക്ഷിച്ച് നോക്കി കൊണ്ട് മടങ്ങി. പാറക്കല്ലിനടുത്തെത്തിയപ്പോ അതാ ഒരു മനുഷ്യൻ, വസ്ത്രം കൊണ്ട് മൂടിപ്പുതച്ചിരിക്കുന്നു. മൂസാ(അ) സലാം ചൊല്ലി. ഖിള്ർ(അ) പ്രതിവചിച്ചു: നിങ്ങളുടെ നാട്ടിലെവിടെയാണ് സലാം? അപ്പോൾ മൂസാ(അ) പറഞ്ഞു: ഞാൻ മൂസ(അ)യാണ്: അപ്പോൾ ഖിള്ർ(അ) ചോദിച്ചു: ഇസ്രായേല്യരുടെ മൂസയാണോ? മൂസാ(അ) പറഞ്ഞു: അതെ. ശേഷം മൂസാ(അ) ചോദിച്ചു: ''താങ്കളെ അഭ്യസിപ്പിച്ചിരിക്കുന്ന നേർമാർഗം എനിക്ക് പഠിപ്പിച്ച് തരുമെന്ന വ്യവസ്ഥയിൽ ഞാൻ താങ്കളെ പിന്തുടരട്ടെയോ? ഖിള്ർ(അ) പറഞ്ഞു: ഓ മൂസ, നിങ്ങൾക്ക് എന്റെ കൂടെ ക്ഷമിച്ചിരിക്കാൻ കഴിയില്ല. അല്ലാഹുവിങ്കൽ നിന്നുള്ള ഒരറിവിലാണ് ഞാനുള്ളത്, അത് നിങ്ങൾക്കറിയില്ല. അല്ലാഹു നിങ്ങൾക്ക് പഠിപ്പിച്ച് തന്ന ഒരു അറിവിലാണ് നിങ്ങളുള്ളത് അത് എനിക്കറിയുകയുമില്ല. അത് കേട്ടപ്പോൾ മൂസാ(അ) പറഞ്ഞു: ഞാൻ ക്ഷമാ ശീലനാണ്. അല്ലാഹു അനുഗ്രഹിച്ചെങ്കിൽ അടുത്ത്തന്നെ താങ്കൾക്ക് അത് ദർശിക്കാനാകും. താങ്കളുടെ ഒരു കൽപ്പനയും ഞാൻ ലംഘിക്കുകയില്ല. അവസാനം രണ്ടുപേരും സമുദ്ര തീരത്തിലൂടെ നടന്നു പോയി. രണ്ട് പേർക്കും കപ്പലില്ല. അതിനിടെ അവരുടെ അരികിലൂടെ ഒരു കപ്പൽ വന്നു. അവരെ കപ്പലിൽ കയറ്റാൻ ആവശ്യപ്പെട്ടു കപ്പലിലുള്ളവരോട് അവർ സംസാരിച്ചു. ഖിള്റ്(അ)വിനെ മനസ്സിലാക്കിയിരുന്നത് കൊണ്ട് ഒരു പ്രതിഫലവും വാങ്ങാതെ അവർ രണ്ടുപേരെയും കപ്പലിൽ കയറ്റി. അന്നേരം ഒരു കുരുവി വന്ന് കപ്പലിന്റെ ഓരത്തിരുന്നു. ഒന്നോ രണ്ടോ കൊത്ത് വെള്ളത്തിൽ കൊത്തി. അത് ചൂണ്ടിക്കാണിച്ച് കൊണ്ട് ഖിള്ർ(അ) പറഞ്ഞു: മൂസാ, ഈ കുരുവി സമുദ്രത്തിൽ ചുണ്ട് താഴ്ത്തിയത് കൊണ്ട് എത്ര വെള്ളം കുറഞ്ഞിട്ടുണ്ടോ അത്രയും ജ്ഞാനം മാത്രമേ അല്ലാഹുവിന്റെ ജ്ഞാനത്തിൽ നിന്ന് എനിക്കും നിങ്ങൾക്കും കിട്ടിയിട്ടുള്ളൂ. പിന്നീട് ഖിള്ർ(അ) ഒരു പലകയുടെ നേരെ നോക്കി. എന്നിട്ട് അത് ഊരിയെടുത്തു. മൂസാ(അ) പറഞ്ഞു: ഒരു കൂട്ടർ യാതൊരു പ്രതിഫലവും കൂടാതെ നമ്മെ കയറ്റി. താങ്കൾ അവരുടെ കപ്പലിൽ കയറി. അതിലെ യാത്രക്കാരെ മുക്കിക്കൊല്ലുകയായിരിക്കും അതിന്റെ ഫലം. ഖിള്ർ(അ) പറഞ്ഞു: നിങ്ങൾക്ക് എന്റെ കൂടെ ക്ഷമിച്ചിരിക്കാൻ കഴിയില്ലെന്ന് ഞാൻ പറഞ്ഞില്ലേ. മൂസാ(അ) പറഞ്ഞു. ഞാൻ മറന്നു പോയതിന് താങ്കൾ എന്നെ ശിക്ഷിക്കരുത്. വിഷമകരമായ കാര്യങ്ങൾക്ക് നിങ്ങളെന്നെ നിർബന്ധിക്കരുത്. ഇത് മൂസാ(അ)മിൽ നിന്നുള്ള ഒന്നാമത്തെ മറവിയായിരുന്നു. പിന്നീട് രണ്ട് പേരും കപ്പലിൽ നിന്ന് ഇറങ്ങി. മറ്റു കുട്ടികളോടൊപ്പം കളിക്കുന്ന ഒരു കുട്ടിയെ കണ്ടുമുട്ടി. ഖിള്ർ(അ) ആ കുട്ടിയുടെ തല പിടിച്ച് കൈകൊണ്ട് പിഴുതെടുത്തു. മൂസാനബി(അ) ചോദിച്ചു: ഒരു പരിശുദ്ധ ജീവനെ അകാരണമായി താങ്കൾ വധിച്ച് കളഞ്ഞല്ലോ. ഖിള്ർ(അ) പറഞ്ഞു: നിങ്ങൾക്ക് എന്റെ കൂടെ ക്ഷമിച്ചിരിക്കാൻ കഴിയില്ലെന്ന് ഞാൻ പറഞ്ഞിട്ടില്ലേ. അങ്ങനെ അവർ ഗ്രാമീണരുടെ അടുക്കൽ എത്തിച്ചേർന്നു. രണ്ട് പേരും തങ്ങളെ അതിഥികളായി എടുക്കണമെന്ന് ആ ഗ്രാമീണരോട് ആവശ്യപ്പെട്ടു. പക്ഷേ, അവരത് നിരസിച്ച് കളഞ്ഞു. അനന്തരം വീഴാനടുത്ത ഒരു മതിൽ അവർ കണ്ടു. ഖിള്ർ(അ) സ്വന്തം കൈ കൊണ്ട് ആ മതിലിന്റെ ചെരുവ് തീർത്ത് ശരിക്കു നിർത്തി. മൂസാ(അ) ഖിള്ർ(അ)നോട് പറഞ്ഞു: നിങ്ങൾ ഉദ്ദേശിച്ചെങ്കിൽ മതിൽ നന്നാക്കിയതിനും കൂലിവാങ്ങാമായിരുന്നു. ഖിള്ർ(അ) പറഞ്ഞു: ഇത് നിങ്ങൾക്കും എനിക്കുമിടയിലെ വേർപാടാണ്. നബി(സ) പറയുന്നു: അല്ലാഹു മൂസാ(അ)നെ അനുഗ്രഹിക്കട്ടെ. അദ്ദേഹം കുറച്ചു കൂടി ക്ഷമിച്ചിരുന്നെങ്കിൽ അവർ രണ്ട് പേരുടെയും സംഭവം നമുക്ക് വിശദമായി മനസ്സിലാക്കാമായിരുന്നുവെന്ന് നാം ആശിച്ചു പോകുന്നു. (ബു)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്‌നു കഅ്ബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 865, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا أَنَا أَمْشِي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي خَرَبِ الْمَدِينَةِ وَهُوَ يَتَوَكَّأُ عَلَى عَسِيبٍ مَعَهُ فَمَرَّ بِنَفَرٍ مِنَ الْيَهُودِ، فَقَالَ بَعْضُهُمْ لِبَعْضٍ: سَلُوهُ عَنِ الرُّوحِ، وَقَالَ بَعْضُهُمْ: لَا تَسْأَلُوهُ لَا يَجِيءُ فِيهِ بِشَيْءٍ تَكْرَهُونَهُ، فَقَالَ بَعْضُهُمْ: لَنَسْأَلَنَّهُ، فَقَامَ رَجُلٌ مِنْهُمْ فَقَالَ: يَا أَبَا الْقَاسِمِ مَا الرُّوحُ؟ فَسَكَتَ فَقُلْتُ: إِنَّهُ يُوحَى إِلَيْهِ فَقُمْتُ، فَلَمَّا انْجَلَى عَنْهُ قَالَ: {وَيَسْأَلُونَكَ عَنِ الرُّوحِ قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّي وَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلَّا قَلِيلًا}. (خ)', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ): ഞാൻ നബി(സ)യോടൊപ്പം മദീനയിലെ ജനവാസമില്ലാത്ത പ്രദേശത്തു കൂടെ നടക്കുകയായിരുന്നു. തിരുമേനി(സ) ഈത്തപ്പനയുടെ ഒരു വടി നിലത്തൂന്നിക്കൊണ്ടാണ് നടന്നത്. അവിടന്ന് ഒരു സംഘം ജൂതരുടെ അടുത്തുകൂടെ നടന്ന് പോയി. നിങ്ങളദ്ദേഹത്തോട് ആത്മാവിനെക്കുറിച്ച് ചോദിക്കുകയെന്ന് ചിലർ മറ്റു ചിലരോട് പറഞ്ഞു. അവരിൽ ചിലർ പറഞ്ഞു: നിങ്ങളദ്ദേഹത്തോട് ചോദിക്കേണ്ട. അദ്ദേഹം നിങ്ങൾക്ക് ഇഷ്ടപ്പെടാത്തത് പറഞ്ഞേക്കില്ല. മറ്റു ചിലർ പറഞ്ഞു: ഞങ്ങളദ്ദേഹത്തോട് ചോദിക്കുക തന്നെ ചെയ്യും. അവരിൽ ഒരാൾ എണീറ്റ് ചോദിച്ചു. ഓ അബൂ ഖാസിം, ആത്മാവിന്റെ യാഥാർത്ഥ്യമെന്താണ്? നബി(സ) മൗനം ദീക്ഷിച്ചു. അപ്പോൾ നബി(സ)ക്ക് ദിവ്യബോധനം (വഹ്‌യ്) ലഭിച്ചുകൊണ്ടിരിക്കുകയാണെന്ന് എനിക്ക് തോന്നി. ഞാനവിടുന്ന് എണീറ്റു. അങ്ങനെ ആ പ്രത്യേക പരിതസ്ഥിതി വിട്ട് മാറിയപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ആത്മാവിനെക്കുറിച്ച് അവർ അങ്ങയോട് ചോദിക്കുന്നു. നബിയേ, അങ്ങ് പറഞ്ഞേക്കുക, ആത്മാവ് എന്റെ നാഥന്റെ അംറിൽ(കാര്യത്തിൽ) പെട്ടതാണ്. നിങ്ങൾക്ക് അൽപജ്ഞാനം മാത്രമേ നൽകപ്പെട്ടിട്ടുള്ളൂ." (ബു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 867, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَعَظَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بَعْدَ صَلَاةِ الْغَدَاةِ مَوْعِظَةً بَلِيغَةً، ذَرَفَتْ مِنْهَا الْعُيُونُ، وَوَجِلَتْ مِنْهَا الْقُلُوبُ، فَقَالَ رَجُلٌ: إِنَّ هَذِهِ مَوْعِظَةُ مُوَدِّعٍ، فَمَاذَا تَعْهَدُ إِلَيْنَا يَا رَسُولَ اللَّهِ؟ قَالَ: "أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ، وَإِنْ عَبْدٌ حَبَشِيٌّ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ يَرَى اخْتِلَافًا كَثِيرًا. وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ، فَإِنَّهَا ضَلَالَةٌ. فَمَنْ أَدْرَكَ ذَلِكَ مِنْكُمْ فَعَلَيْهِ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ". حَسَنٌ صَحِيحٌ. (ت)', 'ഇർബാളുബ്നു സാരിയ(റ): പ്രഭാത നമസ്കാര ശേഷം ഒരു ദിവസം നബി(സ) ഞങ്ങളെ ഗൗരവമായി ഉപദേശിച്ചു. കണ്ണുകൾ അതുമൂലം നിറഞ്ഞൊലിച്ചു. ഹൃദയങ്ങൾ വിറച്ചു പോയി. ഒരാൾ പറഞ്ഞു: ഇതൊരു വിടവാങ്ങൽ പ്രസംഗം തന്നെയാണ്, അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ഞങ്ങളോട് എന്താണ് കൽപ്പിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിനെ ഭയപ്പെടണമെന്നും നീഗ്രോയായ അടിമയാണെങ്കിലും അനുസരണയും വഴിപ്പെടലും പുലർത്തണമെന്നും ഞാൻ ഉപദേശിക്കുകയാണ്. ആരെങ്കിലും എന്റെ ശേഷം ജീവിക്കുകയാണെങ്കിൽ അവർക്ക് ഒരുപാട് അഭിപ്രായഭിന്നതകൾ കാണാം. നിങ്ങൾ പുത്തൻ കാര്യങ്ങളെ സൂക്ഷിക്കുക. അത് മാർഗഭ്രംശം തന്നെയാണ്. അക്കാലത്ത് ആരെങ്കിലും ജീവിച്ചിരിക്കുന്നുണ്ടെങ്കിൽ എന്റെ ചര്യയും സൻമാർഗദർശികളും സൻമാർഗസിദ്ധരുമായ അനന്തരാവകാശികളുടെ ചര്യയും അനുധാവനം ചെയ്യട്ടെ. അത് നിങ്ങളുടെ അണപ്പല്ല് കൊണ്ട് മുറുകെപ്പിടിക്കുക." (തു)', 'الْعِرْبَاضِ بْنِ سَارِيَةَ', 'ഇർബാളുബ്നു സാരിയ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 867, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَمْرِو بْنِ عَوْفٍ الْمُزَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِبِلَالِ بْنِ الْحَارِثِ: "اعْلَمْ". قَالَ: مَا أَعْلَمُ يَا رَسُولَ اللَّهِ؟ قَالَ: "اعْلَمْ يَا بِلَالُ". قَالَ: مَا أَعْلَمُ يَا رَسُولَ اللَّهِ؟ قَالَ: "إِنَّهُ مَنْ أَحْيَا سُنَّةً مِنْ سُنَّتِي، قَدْ أُمِيتَتْ بَعْدِي، فَإِنَّ لَهُ مِنَ الْأَجْرِ مِثْلَ مَنْ عَمِلَ بِهَا، مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أُجُورِهِمْ شَيْئًا. وَمَنِ ابْتَدَعَ بِدْعَةَ ضَلَالَةٍ لَا تُرْضِي اللَّهَ وَرَسُولَهُ، كَانَ عَلَيْهِ مِثْلُ آثَامِ مَنْ عَمِلَ بِهَا، لَا يَنْقُصُ ذَلِكَ مِنْ أَوْزَارِ النَّاسِ شَيْئًا". حَسَنٌ. (ت,جه)', 'അംറുബ്നു ഔഫ്(റ): നബി(സ) ബിലാലുബ്നു ഹാരിസ്(റ)വിനോട് പറഞ്ഞു: "നീ അറിയുക." ബിലാൽ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാനെന്താണ് അറിയേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "ബിലാലേ, നീ അറിയണം." ബിലാൽ(റ) വീണ്ടും ചോദിച്ചു. അല്ലാഹുവിന്റെ റസൂലേ, ഞാനെന്താണ് അറിയേണ്ടത്. അവിടുന്ന് പറഞ്ഞു. "എന്റെ ശേഷം നിർജ്ജീവമാക്കപ്പെട്ട എന്റെ ചര്യകളിൽ ഒന്നിന് ആരെങ്കിലും ജീവൻ നൽകിയാൽ അവന് അതനുഷ്ഠിച്ചവന്റെ പ്രതിഫലമുണ്ട്. അനുഷ്ഠിച്ചവരുടെ പ്രതിഫലത്തിൽ നിന്ന് ഒന്നും കുറയില്ല. അല്ലാഹുവിനെയും അവന്റെ ദൂതനെയും തൃപ്തിപ്പെടുത്താത്ത വല്ല പുത്തനാശയവും ആരെങ്കിലും സൃഷ്ടിച്ചാൽ അവന് അത് ചെയ്തവരുടെ ശിക്ഷ ലഭിക്കുന്നതാണ്. അത് ചെയ്തവരുടെ കുറ്റം അത് കുറക്കുകയുമില്ല." (തു,ജ)', 'عَمْرِو بْنِ عَوْفٍ الْمُزَنِيِّ', 'അംറുബ്നു ഔഫ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 868, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا بُنَيَّ، إِنْ قَدَرْتَ أَنْ تُصْبِحَ وَتُمْسِيَ لَيْسَ فِي قَلْبِكَ غِشٌّ لِأَحَدٍ فَافْعَلْ". ثُمَّ قَالَ لِي: "يَا بُنَيَّ، وَذَلِكَ مِنْ سُنَّتِي، وَمَنْ أَحْيَا سُنَّتِي فَقَدْ أَحَبَّنِي، وَمَنْ أَحَبَّنِي كَانَ مَعِي فِي الْجَنَّةِ". حَسَنٌ. (ت)', 'അനസുബ്നു മാലിക്(റ): എന്നോട് അല്ലാഹുവിന്റെ ദൂതർ പറഞ്ഞു: "പൊന്നുമോനേ, നിനക്ക് പ്രഭാതത്തിലും പ്രദോഷത്തിലും ആരോടും ഹൃദയത്തിൽ പകയില്ലാതെ നിലകൊള്ളാൻ കഴിഞ്ഞാൽ നീ അത് ചെയ്ത് കൊള്ളുക." പിന്നെ നബി(സ) എന്നോട് പറഞ്ഞു "പൊന്നുമോനേ, അതെന്റെ ചര്യയിലുള്ളതാണ്. ആരെങ്കിലും എന്റെ ചര്യയെ ജീവിപ്പിച്ചാൽ അവൻ എന്നെ ഇഷ്ടപ്പെട്ടു. ആരെങ്കിലും എന്നെ ഇഷ്ടപ്പെട്ടാൽ അവൻ എന്റെ കൂടെ സ്വർഗത്തിൽ ഉണ്ടാകും." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 868, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اتْرُكُونِي مَا تَرَكْتُكُمْ، فَإِذَا حَدَّثْتُكُمْ فَخُذُوا عَنِّي، فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِكَثْرَةِ سُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ". حَسَنٌ صَحِيحٌ. (م,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്ക് വിട്ടുതന്നതിൽ നിങ്ങളെന്നെ വെറുതെ വിടുക. ഞാൻ നിങ്ങളോട് ഹദീസ് പറഞ്ഞാൽ നിങ്ങൾ എന്നിൽ നിന്ന് അത് സ്വീകരിക്കുക. നിങ്ങൾക്കു മുമ്പുള്ളവർ നശിച്ചത് അവരുടെ ചോദ്യങ്ങളുടെ ആധിക്യം കൊണ്ടും അവരുടെ പ്രവാചകരോടുള്ള അഭിപ്രായഭിന്നത കൊണ്ടുമായിരുന്നു." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 868, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ نَاسٌ مِنَ الْأَعْرَابِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِمُ الصُّوفُ، فَرَأَى سُوءَ حَالِهِمْ قَدْ أَصَابَتْهُمْ حَاجَةٌ، فَحَثَّ النَّاسَ عَلَى الصَّدَقَةِ، فَأَبْطَئُوا عَنْهُ حَتَّى رُئِيَ ذَلِكَ فِي وَجْهِهِ، قَالَ: ثُمَّ إِنَّ رَجُلًا مِنَ الْأَنْصَارِ جَاءَ بِصُرَّةٍ مِنْ وَرِقٍ، ثُمَّ جَاءَ آخَرُ، ثُمَّ تَتَابَعُوا حَتَّى عُرِفَ السُّرُورُ فِي وَجْهِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً حَسَنَةً، فَعُمِلَ بِهَا بَعْدَهُ، كُتِبَ لَهُ مِثْلُ أَجْرِ مَنْ عَمِلَ بِهَا، وَلَا يَنْقُصُ مِنْ أُجُورِهِمْ شَيْءٌ. وَمَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً سَيِّئَةً، فَعُمِلَ بِهَا بَعْدَهُ، كُتِبَ عَلَيْهِ مِثْلُ وِزْرِ مَنْ عَمِلَ بِهَا، وَلَا يَنْقُصُ مِنْ أَوْزَارِهِمْ شَيْءٌ." (م)', 'ജരീറുബ്നു അബ്ദില്ല(റ): ചില ഗ്രാമീണ അറബികൾ റസൂൽ(സ)യുടെ അടുത്തുവന്നു. അവർ രോമ വസ്ത്രം ധരിച്ചിരുന്നു. നബി(സ) അവരുടെ ദാരിദ്ര്യത്തിന്റെ ശോചനീയാവസ്ഥ മനസ്സിലാക്കി. ജനങ്ങളോട് അവർക്ക് ധർമ്മം ചെയ്യാൻ റസൂൽ(സ) കൽപ്പിച്ചു. അവർ നബി(സ)യിൽ നിന്നും പിന്മാറി. നബി(സ)യുടെ മുഖത്ത് അത് നിഴലിച്ചു. പിന്നെ അൻസാറുകളിൽപ്പെട്ടൊരാൾ ഒരു സഞ്ചി വെള്ളിയുമായി വന്നു. പിന്നെ വേറൊരാൾ വന്നു. പിന്നെ ജനങ്ങൾ തുടർന്നുചെയ്തു. നബി(സ)യുടെ മുഖത്ത് സന്തോഷം പ്രകടമായി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഇസ്‌ലാമിൽ നല്ല ചര്യ സ്ഥാപിച്ച് ശേഷം ആരെങ്കിലും അത് അനുഷ്ഠിച്ചാൽ അനുഷ്ഠിച്ചവന്റെ പ്രതിഫലം അവന് ലഭിക്കും. അനുഷ്ഠിച്ചവരുടെ പ്രതിഫലത്തിൽ നിന്ന് ഒന്നും കുറയില്ല. ആരെങ്കിലും ഇസ്‌ലാമിൽ ദുഷിച്ച ചര്യ സ്ഥാപിച്ച് അത് അവന് ശേഷം അനുഷ്ഠിക്കപ്പെട്ടാൽ അനുഷ്ഠിച്ചവന്റെ പാപം അവനു ലഭിക്കും. കുറ്റം ചെയ്തവന്റെ പാപത്തിൽ നിന്ന് ഒന്നും കുറയുകയില്ല." (മു)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 869, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ نَفْسٍ تُقْتَلُ ظُلْمًا إِلَّا كَانَ عَلَى ابْنِ آدَمَ كِفْلٌ مِنْ دَمِهَا، وَذَلِكَ لِأَنَّهُ أَوَّلُ مَنْ أَسَنَّ الْقَتْلَ." حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അകാരണമായി ഓരോ ശരീരം വധിക്കപ്പെടുമ്പോഴും ആദമിന്റെ പുത്രന് ആ രക്തത്തിൽ പങ്കുണ്ട്. കാരണം അവനാണ് ആദ്യമായി കൊലനടത്തിയത്." (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 869, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الْأَجْرِ مِثْلُ أُجُورِ مَنْ يَتَّبِعُهُ، لَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا. وَمَنْ دَعَا إِلَى ضَلَالَةٍ كَانَ عَلَيْهِ مِنَ الْإِثْمِ مِثْلُ آثَامِ مَنْ يَتَّبِعُهُ، لَا يَنْقُصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും സന്മാർഗത്തിലേക്ക് ക്ഷണിച്ചാൽ അവനെ പിൻപറ്റുന്നവരുടെ പ്രതിഫലത്തിന് സമാനമായത് അവന് ലഭിക്കും. ഇതവരുടെ പ്രതിഫലത്തിൽ നിന്ന് ഒന്നും കുറക്കുകയില്ല. ആരെങ്കിലും വഴികേടിലേക്ക് ക്ഷണിച്ചാൽ അവനെ പിൻപറ്റുന്നവരുടെ പാപത്തിന് സമാനമായത് അവന് ലഭിക്കും." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 869, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَنَّ سُنَّةً خَيْرٍ، فَاتُّبِعَ عَلَيْهَا، فَلَهُ أَجْرُهُ وَمِثْلُ أُجُورِ مَنِ اتَّبَعَهُ، غَيْرَ مَنْقُوصٍ مِنْ أُجُورِهِمْ شَيْئًا. وَمَنْ سَنَّ سُنَّةَ شَرٍّ، فَاتُّبِعَ عَلَيْهَا، كَانَ عَلَيْهِ وِزْرُهُ وَمِثْلُ أَوْزَارِ مَنِ اتَّبَعَهُ، غَيْرَ مَنْقُوصٍ مِنْ أَوْزَارِهِمْ شَيْئًا". حَسَنٌ صَحِيحٌ. (م,ت,ن,جه)', 'ജരീറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ നല്ല ചര്യ സ്ഥാപിച്ച് അവനെ ആരെങ്കിലും പിൻപറ്റിയാൽ അവന് തന്റെ പ്രതിഫലവും തന്നെ പിൻപറ്റിയവരുടെ പ്രതിഫലവുമുണ്ട്, അവരുടെ പ്രതിഫലത്തിൽ നിന്ന് ഒന്നും കുറയാതെ. ഒരാൾ ദുഷിച്ച ചര്യ സ്ഥാപിച്ച് അവനെ ആരെങ്കിലും പിൻപറ്റിയാൽ അവന് തന്റെ പാപവും തന്നെ പിൻപറ്റിയവരുടെ പാപവും ലഭിക്കും, അവരുടെ പാപങ്ങളിൽ നിന്ന് ഒന്നും കുറയാതെ." (മു,തു,ന,ജ)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ يَسْتَحْمِلُهُ فَلَمْ يَجِدْ عِنْدَهُ مَا يَحْمِلُهُ، فَدَلَّهُ عَلَى آخَرَ فَحَمَلَهُ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، فَقَالَ: "إِنَّ الدَّالَّ عَلَى الْخَيْرِ كَفَاعِلِهِ". (م,د,ت)', 'അനസുബ്നുമാലിക്(റ): നബി(സ)യുടെ അടുക്കൽ വന്ന് ഒരാൾ എനിക്ക്(യാത്രചെയ്യാൻ) എന്തെങ്കിലും വേണമെന്ന് പറഞ്ഞു: നബി(സ)യുടെ പക്കൽ അദ്ദേഹത്തിന് യാത്രചെയ്യാൻ പറ്റിയ ഒന്നുമുണ്ടായിരുന്നില്ല. അപ്പോൾ നബി(സ) മറ്റൊരാളെ പറഞ്ഞുകൊടുത്തു. അദ്ദേഹം അയാൾക്ക് ഒരു വാഹനം കൊടുത്തു. അയാൾ നബി(സ)യുടെ അടുത്ത് വന്നു വിഷയം ധരിപ്പിച്ചു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നന്മ പറഞ്ഞുകൊടുത്തവൻ അത് ചെയ്യുന്നവനെപ്പോലെയാണ്". (മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي مَسْعُودٍ الْبَدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَحْمِلُهُ، فَقَالَ: إِنَّهُ قَدْ أُبْدِعَ بِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ائْتِ فُلَانًا". فَأَتَاهُ فَحَمَلَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ. أَوْ قَالَ: عَامِلِهِ" حَسَنٌ صَحِيحٌ. (م,د,ت)', 'അബൂമസ്ഊദുൽ ബദ്‌രി(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് യാത്ര ചെയ്യാൻ എന്തെങ്കിലും വേണമെന്ന് പറഞ്ഞു. അയാൾ പറഞ്ഞു: എന്റെ വാഹനം നഷ്ടപ്പെട്ടിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഇന്നയാളുടെ അടുത്ത് പോവുക". അയാൾ അദ്ദേഹത്തിന്റെയടുത്ത് പോയി. അദ്ദേഹത്തിന് ഒരു വാഹനം നൽകി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും വല്ല നന്മയും അറിയിച്ചു കൊടുത്താൽ അവന് അത് ചെയ്തവന്റെ പ്രതിഫലം പോലുള്ളതുണ്ട്." (മു,ദ,തു)', 'أَبِي مَسْعُودٍ الْبَدْرِيِّ', 'അബൂമസ്ഊദുൽ ബദ്‌രി(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اشْفَعُوا وَلْتُؤْجَرُوا، وَلْيَقْضِ اللَّهُ عَلَى لِسَانِ نَبِيِّهِ مَا شَاءَ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ശിപാർശ ചെയ്യുക. നിങ്ങൾക്ക് പ്രതിഫലം ലഭിക്കട്ടെ. അല്ലാഹു അവന്റെ പ്രവാചകന്റെ നാവിൻമേൽ അവനുദ്ദേശിക്കുന്നത് വിധിക്കട്ടെ." (ബു,മു,ദ,തു,ന)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 870, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ يُرْفَعَ الْعِلْمُ وَيَثْبُتَ الْجَهْلُ وَيُشْرَبَ الْخَمْرُ وَيَظْهَرَ الزِّنَا". (خ)', 'അനസ്(റ): റസൂൽ(സ) പറയുന്നു: "അന്ത്യദിനത്തിന്റെ അടയാളത്തിൽപെട്ടതാണ് വിജ്ഞാനം ഉയർത്തപ്പെടലും അജ്ഞത പ്രാബല്യത്തിൽ വരലും കള്ളുകുടിക്കലും വ്യഭിചാരം പ്രത്യക്ഷമാവലും." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَأُحَدِّثَنَّكُمْ حَدِيثًا لَا يُحَدِّثُكُمْ أَحَدٌ بَعْدِي، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مِنْ أَشْرَاطِ السَّاعَةِ أَنْ يَقِلَّ الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَيَظْهَرَ الزِّنَا وَتَكْثُرَ النِّسَاءُ وَيَقِلَّ الرِّجَالُ حَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً الْقَيِّمُ الْوَاحِدُ". (ق)', 'അനസ്(റ): ഞാൻ നിങ്ങൾക്ക് ഒരു ഹദീസ് പറഞ്ഞുതരാം. അതെനിക്ക് ശേഷം നിങ്ങൾക്കാരും പറഞ്ഞുതരില്ല. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "വിജ്ഞാനം കുറയലും അജ്ഞതയും വ്യഭിചാരവും പ്രത്യക്ഷമാവലും സ്ത്രീകൾ അധികരിക്കലും അമ്പത് സ്ത്രീകൾക്ക് ഒരു പുരുഷനാകുന്ന വിധം പുരുഷന്മാർ കുറയലും അന്ത്യദിനത്തിന്റെ അടയാളമാണ്." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق']::text[], array['ബു']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْتَزِعُهُ مِنَ الْعِبَادِ وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ حَتَّى إِذَا لَمْ يُبْقِ عَالِمًا اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالًا فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ فَضَلُّوا وَأَضَلُّوا". (ق،ت)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹു ജ്ഞാനത്തെ ഒറ്റയടിക്ക് ജനങ്ങളിൽ നിന്ന് എടുത്തുകളയുകയില്ല. പണ്ഡിതരുടെ മരണം മുഖേന വിദ്യയെ ക്രമേണ ജനങ്ങളിൽ നിന്ന് പിടിച്ചെടുക്കും. അവസാനം ഭൂമുഖത്ത് ഒരു പണ്ഡിതനും അവശേഷിക്കാത്ത അവസരം വരുമ്പോൾ ചില മൂഢന്മാരെ മനുഷ്യർ നേതാക്കളാക്കും. എന്നിട്ട് തങ്ങളുടെ പ്രശ്നങ്ങൾ അവരുടെ മുമ്പിൽ വെക്കും. അവർ യാതൊരു ജ്ഞാനവുമില്ലാതെ പ്രശ്നങ്ങൾക്ക് മറുപടി നൽകും. അവസാനം അവർ സ്വയം വഴിതെറ്റും, മറ്റുള്ളവരെ വഴിതെറ്റിക്കും." (ബു,മു,തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَتَقَارَبُ الزَّمَانُ، وَيُقْبَضُ الْعِلْمُ، وَتَظْهَرُ الْفِتَنُ، وَيُلْقَى الشُّحُّ، وَيَكْثُرُ الْهَرْجُ". قَالُوا: وَمَا الْهَرْجُ؟ قَالَ: "الْقَتْلُ". (ق)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "കാലം അടുക്കും. വിജ്ഞാനം പിടിക്കപ്പെടും. പ്രശ്നങ്ങൾ പ്രത്യക്ഷമാകും. പിശുക്ക് പെരുകും. ''ഹർജ്'' അധികരിക്കും." അവർ ചോദിച്ചു: എന്താണ് ''ഹർജ്?'' നബി(സ) പറഞ്ഞു: "കൊല." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَشَخَصَ بِبَصَرِهِ إِلَى السَّمَاءِ، ثُمَّ قَالَ: "هَذَا أَوَانُ يُخْتَلَسُ الْعِلْمُ مِنَ النَّاسِ، حَتَّى لَا يَقْدِرُوا مِنْهُ عَلَى شَيْءٍ". فَقَالَ زِيَادُ بْنُ لَبِيدٍ الْأَنْصَارِيُّ رَضِيَ اللَّهُ عَنْهُ: كَيْفَ يُخْتَلَسُ مِنَّا، وَقَدْ قَرَأْنَا الْقُرْآنَ؟ فَوَاللَّهِ لَنَقْرَأَنَّهُ وَلَنُقْرِئَنَّهُ نِسَاءَنَا وَأَبْنَاءَنَا. فَقَالَ: ثَكِلَتْكَ أُمُّكَ يَا زِيَادُ، إِنْ كُنْتُ لَأَعُدُّكَ مِنْ فُقَهَاءِ أَهْلِ الْمَدِينَةِ، هَذِهِ التَّوْرَاةُ وَالْإِنْجِيلُ عِنْدَ الْيَهُودِ وَالنَّصَارَى، فَمَاذَا تُغْنِي عَنْهُمْ؟ قَالَ جُبَيْرُ بْنُ نُفَيْرٍ: فَلَقِيتُ عُبَادَةَ بْنَ الصَّامِتِ رَضِيَ اللهُ عَنْهُ، قُلْتُ: أَلَا تَسْمَعُ إِلَى مَا يَقُولُ أَخُوكَ أَبُو الدَّرْدَاءِ؟ فَأَخْبَرْتُهُ بِالَّذِي قَالَ أَبُو الدَّرْدَاءِ، قَالَ: صَدَقَ أَبُو الدَّرْدَاءِ، إِنْ شِئْتَ لَأُحَدِّثَنَّكَ بِأَوَّلِ عِلْمٍ يُرْفَعُ مِنَ النَّاسِ: الْخُشُوعُ، يُوشِكُ أَنْ تَدْخُلَ مَسْجِدَ جَمَاعَةٍ فَلَا تَرَى فِيهِ رَجُلًا خَاشِعًا. حَسَنٌ. (ت)', 'അബൂദ്ദർദാഅ്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെയായിരുന്നു. തിരുമേനി(സ) ആകാശത്തേക്ക് കണ്ണുകളുയർത്തി. എന്നിട്ട് പറഞ്ഞു: "ഇത് ജനങ്ങളിൽ നിന്ന് വിജ്ഞാനം പിടിക്കുന്ന സമയമാണ്, അങ്ങനെ അവർക്കൊന്നും കഴിയുകയില്ല." സിയാദുബ്നു ലബീദുൽ അൻസാരി(റ) പറഞ്ഞു: ഞങ്ങൾ ഖുർആൻ പഠിച്ചല്ലോ, പിന്നെയെങ്ങനെയാണ് അത് ഞങ്ങളിൽ നിന്ന് പിടിക്കപ്പെടുക? അല്ലാഹു തന്നെ സത്യം, ഞങ്ങളത് ഓതുകയും ഞങ്ങളുടെ കുട്ടികൾക്കും ഭാര്യമാർക്കും ഓതിക്കൊടുക്കുകയും ചെയ്യും. റസൂൽ(സ) പറഞ്ഞു: "സിയാദേ, നീ എന്താണ് പറയുന്നത്? നിന്നെ ഞാൻ വേണമെങ്കിൽ മദീനയിലെ പണ്ഡിതരിൽ എണ്ണാം. ജൂതർക്ക് തൗറാത്തും ക്രിസ്ത്യാനികൾക്ക് ബൈബിളുമുണ്ട്. പക്ഷേ, അവർക്കതു കൊണ്ട് എന്ത് ഉപകാരം?" ജുബൈറുബ്നു നുഫൈൽ(റ) പറയുന്നു: ഞാൻ ഉബാദതുബ്നു സ്വാമിത്(റ)വിനെ കണ്ടു. ഞാനദ്ദേഹത്തോട് ചോദിച്ചു: നിങ്ങളുടെ സഹോദരൻ അബൂദ്ദർദാഅ്(റ) പറയുന്നത് നിങ്ങൾ കേൾക്കുന്നില്ലേ? അബൂദ്ദർദാഅ്(റ) പറഞ്ഞത് ഞാനദ്ദേഹത്തിന് പറഞ്ഞ് കൊടുത്തു. അദ്ദേഹം പറഞ്ഞു: അബൂദ്ദർദാഅ്(റ) സത്യം പറഞ്ഞിരിക്കുന്നു. നിനക്ക് വേണമെങ്കിൽ, ജനങ്ങളിൽ നിന്ന് ഉയർത്തപ്പെടുന്ന ആദ്യജ്ഞാനം ഏതെന്ന് ഞാൻ പറഞ്ഞുതരാം. ഭക്തിയാണത്. ഒരു കൂട്ടരുടെ പള്ളിയിൽ പ്രവേശിച്ചാൽ അവിടെ നിനക്ക് ഭക്തിയുള്ള ആരെയും കാണാൻ സാധിക്കാത്ത സമയം വരും. (തു)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 871, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُكُمْ - وفي رواية: أَفْضَلُكُمْ - مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ". (خ,د,ت,جه)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഏറ്റവും നല്ലവൻ - ഒരു നിവേദനത്തിൽ: നിങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠൻ - ഖുർആൻ പഠിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്യുന്നവനാണ്." (ബു,ദ,തു,ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 872, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=11 and h.hadith_no=119), 1, 'وَفِي رِوَايَةٍ: أَفْضَلُكُمْ - مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ". (خ,د,ت,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَنَسِ بْنِ مَالِكٍ، عَنْ أَبِي مُوسَى الأَشْعَرِيِّ، رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قال مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الأُتْرُجَّةِ: طَعْمُهَا طَيِّبٌ وَرِيحُهَا طَيِّبٌ. وَمَثَلُ الْمُؤْمِنِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ التَّمْرَةِ: طَعْمُهَا طَيِّبٌ وَلَا رِيحَ لَهَا. وَمَثَلُ الْمُنَافِقِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الرَّيْحَانَةِ: رِيحُهَا طَيِّبٌ وَطَعْمُهَا مُرٌّ. وَمَثَلُ الْمُنَافِقِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ الحَنْظَلَةِ: طَعْمُهَا مُرٌّ وَلَا رِيحَ لَهَا". (ق,د,ت,ن,جه)', 'അബൂ മൂസൽ അശ്അരി(റ)വിൽ നിന്ന് അനസുബ്നു മാലിക്(റ): നബി(സ) പറയുന്നു: "ഖുർആൻ പാരായണം ചെയ്യുന്ന സത്യവിശ്വാസിയുടെ ഉപമ ഓറഞ്ച് പോലെയാണ്. അതിന്റെ രുചി നല്ലതാണ്. അതിന്റെ വാസനയും നല്ലതാണ്. ഖുർആൻ പാരായണം ചെയ്യാത്ത സത്യവിശ്വാസിയുടെ ഉപമ കാരക്കപോലെയാണ്. അതിന് നല്ല രുചിയാണ്, വാസനയില്ല. ഖുർആൻ ഓതുന്ന കപടവിശ്വാസിയുടെ ഉപമ ഒരു ചെട്ടിപ്പൂവ് പോലെയാണ്. അതിന്റെ വാസന നല്ലതാണ്, രുചി കൈപ്പും. ഖുർആൻ ഓതാത്ത കപടവിശ്വാസുടെ ഉപമ ആട്ടങ്ങ പോലെയാണ്. അതിന്റെ രുചി കൈപ്പാണ്, അതിന് വാസനയുണ്ടായില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ، عَنْ أَبِي مُوسَى الأَشْعَرِيِّ،', 'അബൂ മൂസൽ അശ്അരി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 872, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِلَّهِ أَهْلِينَ مِنَ النَّاسِ". قَالُوا: يَا رَسُولَ اللهِ، مَنْ هُمْ؟ قَالَ: "هُمْ أَهْلُ الْقُرْآنِ، أَهْلُ اللهِ وَخَاصَّتُهُ". (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹുവിന് ജനങ്ങളിൽ ചില സ്വന്തക്കാരുണ്ട്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ആരാണവർ? അവിടുന്ന് പറഞ്ഞു: "അവർ ഖുർആനിന്റെ ആളുകളാണ്, അല്ലാഹുവിന്റെ സ്വന്തക്കാരും പ്രത്യേകക്കാരുമാണ്." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 872, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَرَأَ الْقُرْآنَ وَحَفِظَهُ أَدْخَلَهُ اللهُ الْجَنَّةَ وَشَفَّعَهُ فِي عَشَرَةٍ مِنْ أَهْلِ بَيْتِهِ، كُلُّهُمْ قَدِ اسْتَوْجَبُوا النَّارَ". (ت,جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഖുർആൻ പാരായണം ചെയ്യുകയും അത് മനഃപാഠമാക്കുകയും ചെയ്താൽ അവനെ അല്ലാഹു സ്വർഗത്തിൽ കടത്തുകയും, നരകം നിർബന്ധമായ തന്റെ കുടുംബത്തിലെ പത്ത് പേർക്ക് ശഫാഅത്ത് ചെയ്യിക്കുകയും ചെയ്യുന്നതാണ്." (തു,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَعَلَّمُوا الْقُرْآنَ وَاقْرَءُوهُ وَارْقُدُوا، فَإِنَّ مَثَلَ الْقُرْآنِ وَمَنْ تَعَلَّمَهُ فَقَامَ بِهِ: كَمَثَلِ جِرَابٍ مَحْشُوٍّ مِسْكًا، يَفُوحُ رِيحُهُ كُلَّ مَكَانٍ. وَمَثَلُ مَنْ تَعَلَّمَهُ فَرَقَدَ وَهُوَ فِي جَوْفِهِ: كَمَثَلِ جِرَابٍ أُوكِيَ عَلَى مِسْكٍ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഖുർആൻ പഠിക്കുക. അത് പാരായണം ചെയ്യുക. (എന്നിട്ട്) ഉറങ്ങുക. കാരണം ഖുർആനിന്റെയും, അത് പഠിച്ച് അതിന്റെ കർത്തവ്യം നിർവ്വഹിക്കുകയും ചെയ്തവന്റെയും ഉപമ: കസ്തൂരി നിറക്കപ്പെട്ട തോൽസഞ്ചി പോലെയാണ്. അതിന്റെ പരിമളം അതിൽ നിന്നും സർവ്വ ഭാഗങ്ങളിലും പരക്കും. അതുപോലെ ഖുർആൻ പഠിക്കുകയും അത് ഹൃദിസ്ഥമായിരിക്കെ കിടന്നുറങ്ങുകയും ചെയ്തവന്റെ ഉപമ, കസ്തൂരി വെച്ച് വായ് കെട്ടിബന്ധിക്കപ്പെട്ട തോൽസഞ്ചി പോലെയാണ്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ عَامِرِ بْنِ وَاثِلَةَ أَبِي الطُّفَيْلِ رَضِيَ اللهُ عَنْهُ: أَنَّ نَافِعَ بْنَ عَبْدِ الْحَارِثِ لَقِيَ عُمَرَ بْنَ الْخَطَّابِ بِعُسْفَانَ، وَكَانَ عُمَرُ اسْتَعْمَلَهُ عَلَى مَكَّةَ، فَقَالَ عُمَرُ: مَنِ اسْتَخْلَفْتَ عَلَى أَهْلِ الْوَادِي؟ قَالَ: اسْتَخْلَفْتُ عَلَيْهِمُ ابْنَ أَبْزَى. قَالَ: وَمَنِ ابْنُ أَبْزَى؟ قَالَ: رَجُلٌ مِنْ مَوَالِينَا. قَالَ عُمَرُ: فَاسْتَخْلَفْتَ عَلَيْهِمْ مَوْلًى؟ قَالَ: إِنَّهُ قَارِئٌ لِكِتَابِ اللهِ تَعَالَى، عَالِمٌ بِالْفَرَائِضِ، قَاضٍ. قَالَ عُمَرُ: أَمَا إِنَّ نَبِيَّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ يَرْفَعُ بِهَذَا الْكِتَابِ أَقْوَامًا وَيَضَعُ بِهِ آخَرِينَ". (م,جه)', 'ആമിറുബ്നു വാസില അബുത്വഫൈൽ(റ): ഉസ്ഫാനിൽ വെച്ച് നാഫിഉബ്നു അബ്ദിൽ ഹാരിസ്(റ) ഉമറുബ്നുൽ ഖത്താബ്(റ)വിനെ കണ്ടുമുട്ടി. ഉമർ(റ) അദ്ദേഹത്തെ മക്കയുടെ ഗവർണ്ണറായി നിയമിച്ചതായിരുന്നു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: താഴ്വരയിലെ ആളുകൾക്ക് താങ്കൾ ആരെയാണ് പ്രതിനിധിയാക്കിയിട്ടുള്ളത്? അദ്ദേഹം പറഞ്ഞു: ഞാൻ ഇബ്നു അബ്സയെയാണ് അവരുടെ പ്രതിനിധിയാക്കിയിട്ടുള്ളത്. ഉമർ(റ) ചോദിച്ചു: ആരാണ് ഇബ്നു അബ്സ? അദ്ദേഹം പറഞ്ഞു: നാം (അടിമത്വത്തിൽ നിന്നും) മോചിപ്പിച്ചവരിൽപെട്ട ഒരാളാണത്. ഉമർ(റ) ചോദിച്ചു: താങ്കൾ അവർക്ക് ഒരു അടിമയെയാണോ പ്രതിനിധിയാക്കിയത്? അദ്ദേഹം പറഞ്ഞു: അയാൾ ഉന്നതനായ അല്ലാഹുവിന്റെ ഗ്രന്ഥം പാരായണം ചെയ്യുന്ന ആളാണ്, ഫറാഇള് (അനന്തരാവകാശ നിയമങ്ങൾ പ്രതിപാദിക്കുന്ന ശാസ്ത്രം) അറിയുന്നയാളാണ്, ഖാളി (വിധികർത്താവും) ആണ്. ഉമർ(റ) പറഞ്ഞു: നിശ്ചയം നിങ്ങളുടെ പ്രവാചകർ(സ) ഇപ്രകാരം പറഞ്ഞിട്ടില്ലേ: "തീർച്ചയായും, അല്ലാഹു ഈ ഗ്രന്ഥം കൊണ്ട് ചിലയാളുകളെ ഉയർത്തുകയും ചിലരെ താഴ്ത്തുകയും ചെയ്യും." (മു,ജ)', 'عَامِرِ بْنِ وَاثِلَةَ أَبِي الطُّفَيْلِ', 'ആമിറുബ്നു വാസില അബുത്വഫൈൽ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا ذَرٍّ، لَأَنْ تَغْدُوَ فَتُعَلَّمَ آيَةً مِنْ كِتَابِ اللهِ خَيْرٌ لَكَ مِنْ أَنْ تُصَلِّيَ مِائَةَ رَكْعَةٍ. وَلَأَنْ تَغْدُوَ فَتُعَلَّمَ بَابًا مِنَ الْعِلْمِ، عُمِلَ بِهِ أَوْ لَمْ يُعْمَلْ، خَيْرٌ لَكَ مِنْ أَنْ تُصَلِّيَ أَلْفَ رَكْعَةٍ". (جه)', 'അബുദർറ്(റ): റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "ഓ അബുദർറ്, താങ്കൾ പ്രഭാതത്തിലിറങ്ങി, അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ നിന്നുള്ള ഒരു സൂക്തം പഠിക്കൽ, താങ്കൾ നൂറ് റക്അത്ത് നിസ്കരിക്കുന്നതിനേക്കാൾ ഉത്തമമാണ്. എന്നാൽ താങ്കൾ പ്രഭാതത്തിലിറങ്ങി ജ്ഞാനത്തിന്റെ ഒരു അധ്യായം പഠിക്കൽ, അതനുസരിച്ച് പ്രവർത്തിക്കപ്പെട്ടാലും പ്രവർത്തിക്കപ്പെട്ടിട്ടില്ലെങ്കിലും, താങ്കൾ ആയിരം റക്അത്ത് നമസ്കരിക്കുന്നതിനേക്കാൾ ശ്രേഷ്ഠമായത്." (ജ)', 'أَبِي ذَرٍّ', 'അബുദർറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 873, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "الْخَيْرُ عَادَةٌ، وَالشَّرُّ لَجَاجَةٌ، وَمَنْ يُرِدِ اللهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ". (جه)', 'മുആവിയതുബ്നു അബീസുഫ്‌യാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "നന്മ സ്വാഭാവികമായുണ്ടാകുന്നതാണ്, തിന്മയാകട്ടെ (ദുർവാശിയാൽ) ഉണ്ടാക്കിത്തീർക്കുന്നതാണ്. അല്ലാഹു ആരെക്കൊണ്ടെങ്കിലും നന്മ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവനെ, ദീനിൽ ജ്ഞാനമുള്ളവനാക്കും." (ജ)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയതുബ്നു അബീസുഫ്‌യാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَقِيهٌ وَاحِدٌ أَشَدُّ عَلَى الشَّيْطَانِ مِنْ أَلْفِ عَابِدٍ". (ت,جه)', 'ഇബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരാധിച്ച് കൊണ്ടിരിക്കുന്ന ആയിരം ആളുകളേക്കാൾ, ജ്ഞാനമുള്ള ഒരൊറ്റയാൾ ആണ് പിശാചിന് (നേരിടാൻ) ഏറ്റവും ദുഷ്കരമായത്." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللهُ لَهُ طَرِيقًا إِلَى الْجَنَّةِ. وَإِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا رِضًا لِطَالِبِ الْعِلْمِ، وَإِنَّ طَالِبَ الْعِلْمِ يَسْتَغْفِرُ لَهُ مَنْ فِي السَّمَاءِ وَالْأَرْضِ، حَتَّى الْحِيتَانِ فِي الْمَاءِ. وَإِنَّ فَضْلَ الْعَالِمِ عَلَى الْعَابِدِ كَفَضْلِ الْقَمَرِ عَلَى سَائِرِ الْكَوَاكِبِ، إِنَّ الْعُلَمَاءَ هُمْ وَرَثَةُ الْأَنْبِيَاءِ، إِنَّ الْأَنْبِيَاءَ لَمْ يُوَرِّثُوا دِينَارًا وَلَا دِرْهَمًا، إِنَّمَا وَرَّثُوا الْعِلْمَ، فَمَنْ أَخَذَهُ أَخَذَ بِحَظٍّ وَافِرٍ". (د,ت,جه)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു ജ്ഞാനം അന്വേഷിച്ചുകൊണ്ട് ആരെങ്കിലും ഒരു വഴിയിൽ കടന്നാൽ അല്ലാഹു അവന് സ്വർഗ്ഗത്തിലേക്കൊരു വഴി എളുപ്പമാക്കിക്കൊടുക്കും. നിശ്ചയം, ജ്ഞാനം തേടുന്നവരോടുള്ള പ്രീതി കാരണം മാലാഖമാർ തങ്ങളുടെ ചിറകുകൾ അവർക്ക് താഴ്ത്തിക്കൊടുക്കുന്നതാണ്. ജ്ഞാനം തേടുന്നവർക്ക് ആകാശഭൂമികളിലുള്ളവരെല്ലാം പൊറുക്കൽ തേടും, വെള്ളത്തിലെ മീനുകൾ പോലും. ചന്ദ്രന് മറ്റു നക്ഷത്രങ്ങളേക്കാളുള്ള ശ്രേഷ്ഠത പോലെതന്നെയാണ് ആരാധിച്ചുകൊണ്ടിരിക്കുന്നവനേക്കാൾ ഒരു ജ്ഞാനിക്കുള്ള ശ്രേഷ്ഠത. നിശ്ചയം, ജ്ഞാനികൾ പ്രവാചകൻമാരുടെ അനന്തരാവകാശികളാണ്. നബിമാർ ദീനാറോ ദിർഹമോ അനന്തരമാക്കിയിട്ടില്ല, ജ്ഞാനം മാത്രമാണവർ അനന്തരമാക്കിയത്. ആരെങ്കിലും അത് നേടിയാൽ, അവൻ മതിയായ ഓഹരി കരഗതമാക്കി." (ദ,തു,ജ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ. وَوَاضِعُ الْعِلْمِ عِنْدَ غَيْرِ أَهْلِهِ كَمُقَلِّدِ الْخَنَازِيرِ الْجَوْهَرَ وَاللُّؤْلُؤَ وَالذَّهَبَ". (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജ്ഞാനം തേടൽ എല്ലാ മുസ്‌ലിമിനും നിർബന്ധമാണ്. ജ്ഞാനം അതിന്റെ അർഹർക്കല്ലാതെ നൽകുന്നവർ, പന്നികൾക്ക് മുത്തും മാണിക്യവും സ്വർണ്ണവും കൊണ്ട് മാലയണിയിക്കുന്നവനെപ്പോലെയാണ്." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 874, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ نَفَّسَ عَنْ مُسْلِمٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ. وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ. وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللهِ، يَتْلُونَ كِتَابَ اللهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ، إِلَّا حَفَّتْهُمُ الْمَلَائِكَةُ وَنَزَلَتْ عَلَيْهِمُ السَّكِينَةُ وَغَشِيَتْهُمُ الرَّحْمَةُ وَذَكَرَهُمُ اللهُ فِيمَنْ عِنْدَهُ. وَمَنْ أَبْطَأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ". (م,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും, ഒരു മുസ്‌ലിമിൽ നിന്ന് ഐഹിക ബുദ്ധിമുട്ടുകളിൽ പെട്ട വല്ല ബുദ്ധിമുട്ടും അകറ്റിയാൽ, അല്ലാഹു അവനിൽ നിന്ന് അന്ത്യനാളിലെ ബുദ്ധിമുട്ടുകളിൽ നിന്ന് ഒരു ബുദ്ധിമുട്ട് അകറ്റുന്നതാണ്. ഒരു മുസ്‌ലിമിനെ (അഥവാ, അവന്റെ ന്യൂനതയെ) വല്ലവനും മറച്ചുവെച്ചാൽ അല്ലാഹു ഇഹത്തിലും പരത്തിലും അവനെ (അവന്റെ ന്യൂനതയെ) മറച്ചുവെക്കുന്നതാണ്. ഒരു ദരിദ്രനെ വല്ലവനും അഭിവൃദ്ധിയുള്ളവനാക്കിയാൽ അവന് ഇഹത്തിലും പരത്തിലും അല്ലാഹു അഭിവൃദ്ധി നൽകുന്നതാണ്. അടിമ തന്റെ സഹോദരനെ സഹായിച്ചുകൊണ്ടിരിക്കുമ്പോഴെല്ലാം അല്ലാഹു അവനെ സഹായിച്ചുകൊണ്ടിരിക്കും. ജ്ഞാനം തേടി ആരെങ്കിലും ഒരു വഴിയിൽ പ്രവേശിച്ചാൽ, അത് കാരണം അല്ലാഹു അയാൾക്ക് സ്വർഗ്ഗത്തിലേക്ക് ഒരു വഴി സൗകര്യപ്പെടുത്തിക്കൊടുക്കുന്നതാണ്. അല്ലാഹുവിന്റെ ഭവനങ്ങളിൽ ഏതെങ്കിലുമൊരു ഭവനത്തിൽ ഒരു കൂട്ടർ ഒരുമിക്കുകയും, അവർ അല്ലാഹുവിന്റെ ഗ്രന്ഥം പാരായണം ചെയ്യുകയും അത് പരസ്പരം പഠിക്കുകയും ചെയ്താൽ മാലാഖമാർ അവരെ പൊതിയുകയും അവർക്ക് സമാധാനം ഇറങ്ങുകയും കാരുണ്യം അവരെ ചുറ്റുകയും, അല്ലാഹു തന്റെ കൂടെയുള്ളവരുടെ കൂട്ടത്തിൽ അവരെ സ്മരിക്കുകയും ചെയ്യുന്നതാണ്. ആരുടെയെങ്കിലും കർമ്മം പിന്തിയാൽ അവന്റെ തറവാടിത്തം ഉളരുകയില്ല." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ زِرِّ بْنِ حُبَيْشٍ قَالَ: أَتَيْتُ صَفْوَانَ بْنَ عَسَّالٍ الْمُرَادِيَّ رَضِيَ اللهُ عَنْهُ، فَقَالَ: مَا جَاءَ بِكَ؟ قُلْتُ: أَنْبَطُ الْعِلْمَ. قَالَ: فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ خَارِجٍ خَرَجَ مِنْ بَيْتِهِ فِي طَلَبِ الْعِلْمِ إِلَّا وَضَعَتْ لَهُ الْمَلَائِكَةُ أَجْنِحَتَهَا، رِضًا بِمَا يَصْنَعُ". (جه)', 'സുർറുബ്നു ഹുബൈഷ്(റ): ഞാൻ സ്വഫ്വാനുബ്നു അസ്സാലിൽ മുറാദീ(റ)വിന്റെയടുക്കൽ ചെന്നു. അദ്ദേഹം ചോദിച്ചു: താങ്കൾ എന്തിനാണ് വന്നത്? ഞാൻ പറഞ്ഞു: ജ്ഞാനം നുകരാൻ (ജ്ഞാനജലം കോരാൻ). അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ജ്ഞാനം തേടി തന്റെ വീട്ടിൽ നിന്നാരെങ്കിലും പുറപ്പെട്ടാൽ, അവന്റെ പ്രവർത്തിയിലുള്ള തൃപ്തി കാരണം, മാലാഖമാർ തങ്ങളുടെ ചിറകുകൾ അയാൾക്ക് വേണ്ടി താഴ്ത്തിക്കൊടുക്കുക തന്നെ ചെയ്യും." (ജ)', 'زِرِّ بْنِ حُبَيْشٍ قَالَ', 'സുർറുബ്നു ഹുബൈഷ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِهَذَا الْعِلْمِ قَبْلَ أَنْ يُقْبَضَ، وَقَبْضُهُ أَنْ يُرْفَعَ". وَجَمَعَ بَيْنَ إِصْبَعَيْهِ الْوُسْطَى وَالَّتِي تَلِي الْإِبْهَامَ هَكَذَا، ثُمَّ قَالَ: "الْعَالِمُ وَالْمُتَعَلِّمُ شَرِيكَانِ فِي الْأَجْرِ، وَلَا خَيْرَ فِي سَائِرِ النَّاسِ". [ز: في إسناده ضعيف] (جه)', 'അബൂഉമാമ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ ജ്ഞാനത്തിന്റെ തിരോധാനത്തിന് മുമ്പേ നിങ്ങളത് നേടിയിരിക്കണം. അതിന്റെ തിരോധാനം അതുയർത്തപ്പെടലാണ്." അവിടന്ന് തന്റെ രണ്ട് വിരലുകൾ, നടുവിരലും ചൂണ്ടുവിരലും, ഇങ്ങിനെ ഒരുമിച്ച് പിടിച്ചിട്ട് പറഞ്ഞു: "ജ്ഞാനിയും ജ്ഞാനം പഠിക്കുന്നവനും പ്രതിഫലത്തിൽ പങ്കുകാരാണ്. മറ്റു ജനങ്ങളിൽ ഒരു നന്മയുമില്ല." ഇതിന്റെ സനദിൽ ഒരു ദുർബ്ബലനുണ്ട്. (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ مِنْ بَعْضِ حُجَرِهِ فَدَخَلَ الْمَسْجِدَ، فَإِذَا هُوَ بِحَلْقَتَيْنِ: إِحْدَاهُمَا يَقْرَءُونَ الْقُرْآنَ وَيَدْعُونَ اللَّهَ، وَالْأُخْرَى يَتَعَلَّمُونَ وَيُعَلِّمُونَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلٌّ عَلَى خَيْرٍ: هَؤُلَاءِ يَقْرَءُونَ الْقُرْآنَ وَيَدْعُونَ اللَّهَ، فَإِنْ شَاءَ أَعْطَاهُمْ وَإِنْ شَاءَ مَنَعَهُمْ، وَهَؤُلَاءِ يَتَعَلَّمُونَ وَيُعَلِّمُونَ، وَإِنَّمَا بُعِثْتُ مُعَلِّمًا". فَجَلَسَ مَعَهُمْ. [ز: في إسناده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ): റസൂൽ(സ) ഒരു ദിവസം തന്റെ റൂമിൽ നിന്ന് പുറപ്പെട്ട് പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോഴതാ അവിടെ രണ്ടു കൂട്ടങ്ങൾ. ഒരു കൂട്ടം ഖുർആൻ പാരായണം ചെയ്യുകയും അല്ലാഹുവോട് പ്രാർത്ഥിക്കുകയും ചെയ്യുന്നു. മറ്റൊരു കൂട്ടം ജ്ഞാനം പഠിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്യുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എല്ലാം നന്മതന്നെയാണ്. ഇക്കൂട്ടർ ഖുർആൻ ഓതുകയും അല്ലാഹുവോട് പ്രാർത്ഥിക്കുകയും ചെയ്യുന്നു. അവൻ ഉദ്ദേശിക്കുന്ന പക്ഷം അവർക്ക് നൽകുകയും അവൻ ഉദ്ദേശിച്ചാൽ അവർക്ക് തഴയുകയും ചെയ്യും. ഇക്കൂട്ടരാകട്ടെ, ജ്ഞാനം പഠിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്യുന്നു. നിശ്ചയം ഞാൻ, ജ്ഞാനം പഠിപ്പിക്കുന്നവനായി മാത്രമാണ് അയക്കപ്പെട്ടിട്ടുള്ളത്." എന്നിട്ട് അവിടുന്ന് അക്കൂട്ടരിൽ ഇരിക്കുകയും ചെയ്തു. (സനദിൽ ഒരു ബലഹീനനുണ്ട്.) (ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَضَّرَ اللَّهُ امْرَأً سَمِعَ مَقَالَتِي فَبَلَّغَهَا، فَرُبَّ حَامِلِ فِقْهٍ غَيْرِ فَقِيهٍ، وَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ". وفي رواية: "ثَلَاثٌ لَا يُغِلُّ عَلَيْهِنَّ قَلْبُ امْرِئٍ مُسْلِمٍ: إِخْلَاصُ الْعَمَلِ لِلَّهِ، وَالنُّصْحُ لِأَئِمَّةِ الْمُسْلِمِينَ، وَلُزُومُ جَمَاعَتِهِمْ". (جه)', 'സൈദുബ്നു സാബിത്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സംസാരം കേൾക്കുകയും അത് പ്രബോധനം ചെയ്യുകയും ചെയ്തവന്റെ മുഖം അല്ലാഹു പ്രകാശിപ്പിക്കട്ടെ. വിജ്ഞാനം പേറുന്ന എത്രയെത്രയാളുകളാണ് (യഥാർത്ഥ) ജ്ഞാനിയല്ലാതെയുള്ളത്. എത്രയെത്രയാളുകളാണ് തന്നെക്കാൾ ജ്ഞാനമുള്ളവർക്ക് വിജ്ഞാനം പകർന്ന് കൊടുക്കുന്നത്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=11 and h.hadith_no=134), 1, 'وَفِي رِوَايَةٍ: "ثَلَاثٌ لَا يُغِلُّ عَلَيْهِنَّ قَلْبُ امْرِئٍ مُسْلِمٍ: إِخْلَاصُ الْعَمَلِ لِلَّهِ، وَالنُّصْحُ لِأَئِمَّةِ الْمُسْلِمِينَ، وَلُزُومُ جَمَاعَتِهِمْ". (جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نَضَّرَ اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثًا فَبَلَّغَهُ، فَرُبَّ مُبَلَّغٍ أَحْفَظُ مِنْ سَامِعٍ". (ت،جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "നമ്മിൽ നിന്ന് ഒരു ഹദീസ് കേൾക്കുകയും അത് എത്തിച്ചുകൊടുക്കുകയും ചെയ്തവന്റെ മുഖം അല്ലാഹു പ്രകാശിപ്പിക്കട്ടെ. (നമ്മിൽ നിന്ന്) കേട്ടവരേക്കാൾ മനഃപാഠമാക്കുന്ന എത്രയെത്ര പേർക്കാണ് എത്തിക്കപ്പെട്ടിട്ടുള്ളത്." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَطَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ، فَقَالَ: "لِيُبَلِّغِ الشَّاهِدُ الْغَائِبَ، فَإِنَّهُ رُبَّ مُبَلَّغٍ يُبَلِّغُهُ أَوْعَى لَهُ مِنْ سَامِعٍ". (جه)', 'അബുബക്റ(റ): ബലിപെരുന്നാൾ ദിനം റസൂൽ(സ) ഖുത്ബ നടത്തിക്കൊണ്ട് പറഞ്ഞു: "സാക്ഷിയായവർ അസന്നിഹിതർക്ക് എത്തിച്ചുകൊടുക്കട്ടെ. (ഹദീസ്) എത്തിക്കപ്പെട്ട എത്രയെത്രയാളുകൾ (അത്) കേട്ടയാളേക്കാൾ സൂക്ഷ്മതയുള്ളവരായുണ്ട്." (ജ)', 'أَبِي بَكْرَةَ', 'അബുബക്റ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 876, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ مُعَاوِيَةَ الْقُشَيْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا لِيُبَلِّغِ الشَّاهِدُ الْغَائِبَ". (د,ت,جه)', 'മുആവിയതുൽ ഖുശൈരി(റ): റസൂൽ(സ) പറഞ്ഞു: "അറിയുക, സാക്ഷിയായവർ അസന്നിഹിതർക്ക് എത്തിച്ചുകൊടുക്കട്ടെ." (ദ,തു,ജ)', 'مُعَاوِيَةَ الْقُشَيْرِيِّ', 'മുആവിയതുൽ ഖുശൈരി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ النَّاسِ مَفَاتِيحَ لِلْخَيْرِ مَغَالِيقَ لِلشَّرِّ، وَإِنَّ مِنَ النَّاسِ مَفَاتِيحَ لِلشَّرِّ مَغَالِيقَ لِلْخَيْرِ. فَطُوبَى لِمَنْ جَعَلَ اللهُ مَفَاتِيحَ الْخَيْرِ عَلَى يَدَيْهِ، وَوَيْلٌ لِمَنْ جَعَلَ اللهُ مَفَاتِيحَ الشَّرِّ عَلَى يَدَيْهِ". [ز: فِي إِسْنَادِهِ ضَعِيفٌ] (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും ജനങ്ങളിൽ നന്മയുടെ താക്കോലുകളും തിന്മയുട അന്തകരുമായവരുണ്ട്. നിശ്ചയം ജനങ്ങളിൽ തിന്മയുടെ താക്കോലുകളും നന്മയുടെ അന്തകരുമായവരുമുണ്ട്. അല്ലാഹു ആരുടെ കരങ്ങളിലാണോ നന്മയുടെ താക്കോലുകൾ വെച്ചതെങ്കിൽ അവന് സൗഭാഗ്യമുണ്ട്. ആരുടെയെങ്കിലും കരങ്ങളിൽ തിന്മയുടെ താക്കോലുകൾ അല്ലാഹു വെച്ചിട്ടുണ്ടെങ്കിൽ അവനാണ് നാശം." (സനദിൽ ഒരു ബലഹീനനുണ്ട്.) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ ضَعِيفٌ', null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ هَذَا الْخَيْرَ خَزَائِنُ، وَلِتِلْكَ الْخَزَائِنِ مَفَاتِيحُ، فَطُوبَى لِعَبْدٍ جَعَلَهُ اللهُ مِفْتَاحًا لِلْخَيْرِ مِغْلَاقًا لِلشَّرِّ، وَوَيْلٌ لِعَبْدٍ جَعَلَهُ اللهُ مِفْتَاحًا لِلشَّرِّ مِغْلَاقًا لِلْخَيْرِ". [فِي إِسْنَادِهِ ضَعِيفٌ] (جه)', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ നന്മകൾ ഖജനാവുകളാണ്. ആ ഖജനാവുകൾക്ക് താക്കോലുകളുമുണ്ട്. അപ്പോൾ ഒരടിമയെ അല്ലാഹു നന്മയുടെ താക്കോലും തിന്മയുടെ താഴും ആക്കുകയാണെങ്കിൽ അവന് സൗഭാഗ്യം, ഒരടിമയെ അല്ലാഹു തിന്മയുടെ താക്കോലും നന്മയുടെ താഴും ആക്കുന്നുവെങ്കിൽ അവനാണ് നാശം." (സനദിൽ ഒരു ദുർബ്ബലനുണ്ട്.) (ജ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فِي إِسْنَادِهِ ضَعِيفٌ', 'സനദിൽ ഒരു ദുർബ്ബലനുണ്ട്.', 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّهُ لَيَسْتَغْفِرُ لِلْعَالِمِ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ، حَتَّى الْحِيتَانُ فِي الْبَحْرِ". (جه)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം ഒരു ജ്ഞാനിക്ക് ആകാശങ്ങളിലുള്ളവരും ഭൂമിയിലുള്ളവരും പൊറുക്കൽ തേടുന്നതാണ്, കടലിലെ മീനുകൾ പോലും." (ജ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ مُعَاذِ بْنِ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ عَلَّمَ عِلْمًا فَلَهُ أَجْرُ مَنْ عَمِلَ بِهِ، لَا يَنْقُصُ مِنْ أَجْرِ الْعَامِلِ". (جه)', 'മുആദുബ്നു അനസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു ജ്ഞാനം പകർന്ന് കൊടുത്താൽ അവന് അതനുസരിച്ച് കർമ്മം ചെയ്യുന്നവന്റെ പ്രതിഫലമുണ്ട്, (അപ്രകാരം) പ്രവർത്തിക്കുന്നവന്റെ പ്രതിഫലത്തിൽ നിന്നൊന്നും കുറയാതെത്തന്നെ.” (ജ)', 'مُعَاذِ بْنِ أَنَسٍ', 'മുആദുബ്നു അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 877, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”خَيْرُ مَا يُخَلِّفُ الرَّجُلُ مِنْ بَعْدِهِ ثَلَاثٌ: وَلَدٌ صَالِحٌ يَدْعُو لَهُ، وَصَدَقَةٌ تَجْرِي يَبْلُغُهُ أَجْرُهَا، وَعِلْمٌ يُعْمَلُ بِهِ مِنْ بَعْدِهِ“. (جه)', 'അബൂഖതാദ(റ): റസൂൽ(സ) പറഞ്ഞു: “തനിക്ക് ശേഷം ഒരാൾ അവശേഷിപ്പിക്കുന്നവയിൽ ഏറ്റവും നല്ലത് മൂന്ന് കാര്യങ്ങളാണ്: അവന് വേണ്ടി പ്രാർത്ഥിക്കുന്ന ഒരു കുട്ടി, അവനിലേക്ക് പ്രതിഫലമെത്തുന്ന സ്ഥിരമായദാനം, തനിക്ക് ശേഷവും കർമ്മം ചെയ്യപ്പെടുന്ന ജ്ഞാനം.” (ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”إِنَّ مِمَّا يَلْحَقُ الْمُؤْمِنَ مِنْ عَمَلِهِ وَحَسَنَاتِهِ بَعْدَ مَوْتِهِ: عِلْمًا عَلَّمَهُ وَنَشَرَهُ، وَوَلَدًا صَالِحًا تَرَكَهُ، وَمُصْحَفًا وَرَّثَهُ، أَوْ مَسْجِدًا بَنَاهُ، أَوْ بَيْتًا لِابْنِ السَّبِيلِ بَنَاهُ، أَوْ نَهْرًا أَجْرَاهُ، أَوْ صَدَقَةً أَخْرَجَهَا مِنْ مَالِهِ فِي صِحَّتِهِ وَحَيَاتِهِ، يَلْحَقُهُ مِنْ بَعْدِ مَوْتِهِ“. (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: “തന്റെ മരണശേഷവും, സത്യവിശ്വാസിയിലേക്ക്, തന്റെ കർമ്മത്തിൽ നിന്നും നന്മകളിൽ നിന്നും വന്നുചേരുന്നവയിൽ പെട്ടവയാണ് (ശേഷം പറയുന്ന കാര്യങ്ങൾ): അവൻ പഠിപ്പിക്കുകയും പ്രചരിപ്പിക്കുകയും ചെയ്ത ജ്ഞാനം, അവൻ അവശേഷിപ്പിച്ച് പോയ നല്ല കുട്ടി, അവൻ അനന്തരമാക്കിയ മുസ്ഹഫ്, അവൻ പണിത പള്ളി, വഴിയാത്രികന് വേണ്ടി അവൻ നിർമ്മിച്ച വീട്, അവനൊഴുക്കിയ പുഴ, തന്റെ ജീവിതത്തിലും ആരോഗ്യത്തിലും അവൻ ചെലവഴിച്ച ദാനം. (ഇവയെല്ലാം) അവന്റെ മരണശേഷം അവനിലേക്ക് ചേരുന്നതാണ്.” (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ”أَفْضَلُ الصَّدَقَةِ أَنْ يَتَعَلَّمَ الْمَرْءُ الْمُسْلِمُ عِلْمًا، ثُمَّ يُعَلِّمَهُ أَخَاهُ الْمُسْلِمَ“. [في إسناده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: “മുസ്‌ലിമായ ഒരു മനുഷ്യൻ ഒരു ജ്ഞാനം പഠിക്കുകയും, തന്റെ മുസ്‌ലിമായ സുഹൃത്തിന് അത് പഠിപ്പിക്കുകയും ചെയ്യലാണ് ഏറ്റവും ശ്രേഷ്ഠമായ ദാനം.” (ഇതിന്റെ സനദിൽ ഒരു ദുർബ്ബലനുണ്ട്) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده ضعيف', 'ഇതിന്റെ സനദിൽ ഒരു ദുർബ്ബലനുണ്ട്', 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَا رُئِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مُتَّكِئًا قَطُّ، وَلَا يَطَأُ عَقِبَيْهِ رَجُلَانِ. (د،جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരിക്കലും ചാരിനിന്ന് ഭക്ഷിക്കുന്നതായും തനിക്ക് പിറകിൽ ആരെങ്കിലും നടക്കുന്നതായും റസൂൽ(സ)യെ കാണപ്പെട്ടിട്ടില്ല. (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي يَوْمٍ شَدِيدِ الْحَرِّ نَحْوَ بَقِيعِ الْغَرْقَدِ، وَكَانَ النَّاسُ يَمْشُونَ خَلْفَهُ، فَلَمَّا سَمِعَ صَوْتَ النِّعَالِ وَقَرَ ذَلِكَ فِي نَفْسِهِ، فَجَلَسَ حَتَّى قَدَّمَهُمْ أَمَامَهُ، لِئَلَّا يَقَعَ فِي نَفْسِهِ شَيْءٌ مِنَ الْكِبْرِ. [ز: في إسناده ضعيف] (جه)', 'അബൂഉമാമ(റ): അത്യുഷ്ണമുള്ള ഒരു ദിനം. തിരുനബി(സ) ബഖീഉൽ ഗർഖദിന്റെ ഭാഗത്തേക്ക് നടക്കുകയുണ്ടായി. അവിടത്തെ പിന്നിലായി ജനങ്ങളും സഞ്ചരിക്കുന്നുണ്ടായിരുന്നു. ചെരിപ്പുകളുടെ ശബ്ദം അവിടന്ന് ശ്രവിച്ചപ്പോൾ അവിടത്തേക്കൊരു ബുദ്ധിമുട്ടായി തോന്നി. അപ്പോൾ അവരെ തനിക്ക് മുന്നിലാക്കുന്നത് വരെ അവിടന്ന് ഇരുന്നു. അവിടത്തേക്ക് തന്റെ മനസ്സിൽ അൽപം പോലും ഗർവ് തോന്നാതിരിക്കാൻ. (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്.) (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 878, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, '.١٤٧ عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا مَشَى مَشَى أَصْحَابُهُ أَمَامَهُ، وَتَرَكُوا ظَهْرَهُ لِلْمَلَائِكَةِ. (جه)', 'ജാബിറുബ്‌നു അബ്ദില്ല(റ): തിരുനബി(സ) സഞ്ചരിക്കുമ്പോൾ അവിടുത്തെ അനുചരർ അവിടുത്തെ മുൻപിൽ നടക്കുകയും അവിടുത്തെ പുറഭാഗം അവർ മാലാഖമാർക്കായി ഒഴിച്ചിടുകയും ചെയ്യുമായിരുന്നു. (ജ)', null, 'ജാബിറുബ്‌നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, '.١٤٨ عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَيَأْتِيكُمْ أَقْوَامٌ يَطْلُبُونَ الْعِلْمَ، فَإِذَا رَأَيْتُمُوهُمْ فَقُولُوا لَهُمْ: مَرْحَبًا مَرْحَبًا بِوَصِيَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَاقْنُوهُمْ". (ت,جه)', 'അബൂസഈദിനിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: “ജ്ഞാനവും തേടി നിങ്ങളിലേക്ക് ജനങ്ങൾ വരിക തന്നെ ചെയ്യും. നിങ്ങളവരെ കണ്ടാൽ അവരോട് റസൂൽ(സ)യുടെ വസിയ്യത്തിന് സ്വാഗതം, സ്വാഗതം എന്ന് പറയുകയും അവരെ നിങ്ങൾ അറിവ് പഠിപ്പിച്ച് കൊടുക്കുകയും ചെയ്യുക. (തു,ജ)', null, 'അബൂസഈദിനിൽ ഖുദ്‌രി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, '.١٤٩ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى مَلَأْنَا الْبَيْتَ، وَهُوَ مُضْطَجِعٌ لِجَنْبِهِ، فَلَمَّا رَآنَا قَبَضَ رِجْلَيْهِ، ثُمَّ قَالَ: "إِنَّهُ سَيَأْتِيكُمْ أَقْوَامٌ مِنْ بَعْدِي يَطْلُبُونَ الْعِلْمَ، فَرَحِّبُوا بِهِمْ، وَحَيُّوهُمْ وَعَلِّمُوهُمْ". [ز: في إسناده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുത്തേക്ക് കടന്നുവന്നു. അങ്ങനെ വീട് നിറഞ്ഞു. അവിടന്നാണെങ്കിൽ ഒരു വശത്തേക്ക് ചെരിഞ്ഞ് കിടക്കുകയാണ്. അവിടന്ന് ഞങ്ങളെ കണ്ടപ്പോൾ അവിടത്തെ ഇരുകാലുകളും പിടിച്ചിട്ട് പറഞ്ഞു: “നിശ്ചയം എനിക്ക് ശേഷം നിങ്ങളിലേക്ക് ജ്ഞാനം തേടി ജനങ്ങൾ വരുന്നതാണ്. അപ്പോൾ നിങ്ങൾ അവരെ സ്വീകരിക്കുകയും സ്വാഗതമരുളുകയും അവരെ പഠിപ്പിക്കുകയും ചെയ്യണം.” (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഒരു ദുർബലനുണ്ട്.) (ജ)', null, 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഒരു ദുർബലനുണ്ട്.', 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, '.١٥٠ عَنْ أَبِي هَارُونَ الْعَبْدِيِّ قَالَ: كُنَّا إِذَا أَتَيْنَا أَبَا سَعِيدٍ الْخُدْرِيَّ قَالَ: مَرْحَبًا بِوَصِيَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَنَا: "إِنَّ النَّاسَ لَكُمْ تَبَعٌ، وَإِنَّهُمْ سَيَأْتُونَكُمْ مِنْ أَقْطَارِ الْأَرْضِ يَتَفَقَّهُونَ فِي الدِّينِ، فَإِذَا جَاءُوكُمْ فَاسْتَوْصُوا بِهِمْ خَيْرًا". (جه)', 'അബൂഹാറൂനൽ അബ്ദി(റ): ഞങ്ങൾ അബൂസഈദിനിൽ ഖുദ്‌രി(റ)വിന്റെയടുത്ത് ചെന്നാൽ അദ്ദേഹം പറയുമായിരുന്നു. റസൂൽ(സ)യുടെ ഉത്തരവിന് സ്വാഗതം. നിശ്ചയം, റസൂൽ(സ) ഞങ്ങളോട് പറഞ്ഞിട്ടുണ്ട്: “ജനങ്ങൾ നിങ്ങളുടെ അനുയായികളാണ്. ദീനിൽ ജ്ഞാനമുള്ളവരാവാനായി അവർ ഭൂമിയുടെ പലഭാഗങ്ങളിൽ നിന്നും നിങ്ങളിലേക്ക് വരുന്നതാണ്. അവർ നിങ്ങളിലേക്ക് വന്നാൽ നിങ്ങളവരോട് നന്മയുപദേശിക്കുക.” (ജ)', null, 'അബൂഹാറൂനൽ അബ്ദി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 879, 879, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, '.١٥١ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ مِنْ دُعَاءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ دُعَاءٍ لَا يُسْمَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ". (ن,جه)', 'അബൂഹുറൈറ(റ): തിരുനബി(സ)യുടെ പ്രാർത്ഥനയിൽ പെട്ടതായിരുന്നു: "അല്ലാഹുവേ, ഉപകാരമില്ലാത്ത ജ്ഞാനത്തിൽ നിന്നും, (സ്വീകാര്യമാം വിധം) കേൾക്കപ്പെടാത്ത പ്രാർത്ഥനയിൽ നിന്നും, വയർ നിറയാത്ത ശരീരത്തിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ തേടുന്നു." (ന,ജ)', null, 'അബൂഹുറൈറ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 879, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَزِدْنِي عِلْمًا. وَالْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുമായിരുന്നു: "അല്ലാഹുവേ, നീ എനിക്ക് പഠിപ്പിച്ച് തന്ന ജ്ഞാനം കൊണ്ട് എനിക്ക് ഉപകാരം നൽകണേ, എനിക്ക് ഉപകാരമാകുന്നവ എന്നെ പഠിപ്പിക്കണേ, എനിക്ക് ജ്ഞാനം ധാരാളമാക്കുകയും ചെയ്യേണമേ. സർവ്വ അവസ്ഥകളിലും മുഴുവൻ സ്തുതികളും അല്ലാഹുവിനാണ്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَعَلَّمَ عِلْمًا مِمَّا يُبْتَغَى بِهِ وَجْهُ اللَّهِ، لَا يَتَعَلَّمُهُ إِلَّا لِيُصِيبَ بِهِ عَرَضًا مِنَ الدُّنْيَا، لَمْ يَجِدْ عَرْفَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ". يَعْنِي رِيحَهَا. (د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ തിരുമുഖം പ്രതീക്ഷിക്കപ്പെടേണ്ട ജ്ഞാനം ആരെങ്കിലും ഇഹലോക ലക്ഷ്യസാക്ഷാൽക്കാരത്തിന് വേണ്ടി മാത്രമായി നേടിയാൽ, അവന് അന്ത്യനാളിൽ സ്വർഗ്ഗത്തിന്റെ പരിമളം ലഭിക്കുകയില്ല." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ طَلَبَ الْعِلْمَ لِيُمَارِيَ بِهِ السُّفَهَاءَ، أَوْ لِيُبَاهِيَ بِهِ الْعُلَمَاءَ، أَوْ لِيَصْرِفَ وُجُوهَ النَّاسِ إِلَيْهِ، فَهُوَ فِي النَّارِ". [ز: في إسناده ضعيف] (جه)', 'ഇബ്നു ഉമർ(റ): തിരുനബി(സ) പറഞ്ഞു: "വിഡ്ഢികളോട് ശണ്ഠകൂടാനോ, ജ്ഞാനികളോട് പെരുമ കാണിക്കാനോ, തന്നിലേക്ക് ജനശ്രദ്ധ തിരിക്കാനോ വേണ്ടി വല്ലവനും ജ്ഞാനം തേടിയാൽ അവൻ നരകത്തിലാണ്." (ഈ ഹദീസിന്റെ പരമ്പരയിൽ പ്രബലനല്ലാത്ത നിവേദകനുണ്ട്) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ جَابِرِ ابْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَعَلَّمُوا الْعِلْمَ لِتُبَاهُوا بِهِ الْعُلَمَاءَ، وَلَا لِتُمَارُوا بِهِ السُّفَهَاءَ، وَلَا تَخَيَّرُوا بِهِ الْمَجَالِسَ. فَمَنْ فَعَلَ ذَلِكَ فَالنَّارُ النَّارُ". (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ജ്ഞാനികളോട് പെരുമകാണിക്കാൻ വേണ്ടിയോ വിഡ്ഢികളോട് തർക്കിക്കാൻ വേണ്ടിയോ നിങ്ങൾ ജ്ഞാനം നേടരുത്. അതുമായി നിങ്ങൽ സദസ്സുകൾ തിരയരുത്. ആരെങ്കിലും അങ്ങനെ ചെയ്താൽ (അവർക്ക്) നരകമാണ്, നരകമാണ്." (ജ)', 'جَابِرِ ابْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أُنَاسًا مِنْ أُمَّتِي سَيَتَفَقَّهُونَ فِي الدِّينِ، وَيَقْرَءُونَ الْقُرْآنَ، وَيَقُولُونَ: نَأْتِي الْأُمَرَاءَ فَنُصِيبُ مِنْ دُنْيَاهُمْ وَنَعْتَزِلُهُمْ بِدِينِنَا. وَلَا يَكُونُ ذَلِكَ، كَمَا لَا يُجْتَنَى مِنَ الْقَتَادِ إِلَّا الشَّوْكُ، كَذَلِكَ لَا يُجْتَنَى مِنْ قُرْبِهِمْ إِلَّا". [ز: في إسناده ضعيف] (جه)', 'ഇബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, എന്റെ സമുദായത്തിലെ ചില ജനങ്ങൾ ദീനിൽ അറിവ് നേടുകയും ഖുർആൻ പാരായണം ചെയ്യുകയും ചെയ്യും. അവർ നമുക്ക് നേതാക്കന്മാരുടെയടുത്ത് ചെന്ന് അവരുടെ ഭൗതിക സമ്പാദ്യങ്ങൾ നേടുകയും നമ്മുടെ ദീനുമായി (ദുർബ്ബലമാവാതെ) നമുക്കവരെ ഒഴിവാക്കുകയും ചെയ്യാം, എന്ന് വിചാരിക്കുകയും ചെയ്യും. അത് നടക്കുകയില്ല, ഖതാദിൽ നിന്ന് (ഖതാദ്: സൂചിപോലുള്ള മുള്ളുകളുള്ള ഒരുതരം ചെടി) മുള്ളല്ലാതെ ഒന്നും തന്നെ പറിച്ചെടുക്കാവതല്ല എന്നത് പോലെ. അവരോടുള്ള അടുപ്പത്തിൽ നിന്ന് (പിഴവ്) അല്ലാതെ നേടാവതല്ല." (ഇതിന്റെ പരമ്പരയിൽ ഒരു ദുർബ്ബലനുണ്ട്.) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ഒരു ദുർബ്ബലനുണ്ട്.', 880, 880, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَعَوَّذُوا بِاللَّهِ مِنْ جُبِّ الْحَزَنِ". قَالُوا: يَا رَسُولَ اللهِ، وَمَا جُبُّ الْحَزَنِ؟ قَالَ: "وَادٍ فِي جَهَنَّمَ، تَعَوَّذُ مِنْهُ جَهَنَّمُ كُلَّ يَوْمٍ أَرْبَعَ مِائَةِ مَرَّةٍ". قَالُوا: يَا رَسُولَ اللهِ، مَنْ يَدْخُلُهُ؟ قَالَ: "أُعِدَّ لِلْقُرَّاءِ الْمُرَائِينَ بِأَعْمَالِهِمْ، وَإِنَّ مِنْ أَبْغَضِ الْقُرَّاءِ إِلَى اللَّهِ الَّذِينَ يَزُورُونَ الْأُمَرَاءَ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിഷമത്തിന്റെ ആഴക്കിണറ്റിൽ നിന്നും നിങ്ങൾ അല്ലാഹുവോട് കാവൽ തേടുവീൻ." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, വ്യഥയുടെ ആഴക്കിണർ എന്താണ്? അവിടന്നരുളി: "നരകത്തിലെ ഒരു ചെരുവാണത്. എല്ലാ ദിവസവും നാനൂറ് പ്രാവശ്യം നരകം അതിൽ നിന്ന് കാവൽ തേടുന്നുണ്ട്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ആരാണതിൽ പ്രവേശിക്കുക? അവിടന്ന് പറഞ്ഞു: "തങ്ങളുടെ കർമ്മങ്ങൾ കൊണ്ട് ലോകമാന്യം കാണിക്കുന്ന വേദഗ്രന്ഥപാരായണക്കാർക്കായി തയ്യാർ ചെയ്യപ്പെട്ടതാണത്. നേതാക്കന്മാരെ സന്ദർശിക്കുന്ന വേദഗ്രന്ഥപാരായണക്കാരാണ് അല്ലാഹുവിന് ഏറ്റവും വെറുപ്പുള്ളവർ." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَوْ أَنَّ أَهْلَ الْعِلْمِ صَانُوا الْعِلْمَ وَوَضَعُوهُ عِنْدَ أَهْلِهِ لَسَادُوا بِهِ أَهْلَ زَمَانِهِمْ، وَلَكِنَّهُمْ بَذَلُوهُ لِأَهْلِ الدُّنْيَا لِيَنَالُوا بِهِ مِنْ دُنْيَاهُمْ، فَهَانُوا عَلَيْهِمْ. سَمِعْتُ نَبِيَّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ جَعَلَ الْهُمُومَ هَمًّا وَاحِدًا، هَمَّ آخِرَتِهِ، كَفَاهُ اللَّهُ هَمَّ دُنْيَاهُ. وَمَنْ تَشَعَّبَتْ بِهِ الْهُمُومُ فِي أَحْوَالِ الدُّنْيَا، لَمْ يُبَالِ اللَّهُ فِي أَيِّ أَوْدِيَتِهَا هَلَكَ". [ز: في إسناده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ജ്ഞാനത്തിന്റെയാളുകൾ ജ്ഞാനത്തെ കാത്തുസൂക്ഷിക്കുകയും അതിന്റെ അർഹർക്ക് നൽകുകയും ചെയ്യുന്ന പക്ഷം അവർ തങ്ങളുടെ കാലക്കാർക്ക് നേതാക്കളാകുന്നതാണ്. പക്ഷെ, ദുൻയാവിന്റെയാളുകൾക്ക് അവരുടെ ലൗകികതയിൽ നിന്ന് നേടാനായി, അവർ ജ്ഞാനം ചെലവഴിച്ചാൽ, അവർ അവർക്കിടയിൽ (തങ്ങളുടെ കാലക്കാർക്കിടയിൽ) വിലക്കെട്ടവരാവുകയും ചെയ്യും. നിങ്ങളുടെ പ്രവാചകൻ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും തന്റെ താത്പര്യങ്ങൾ ഒരൊറ്റ താൽപര്യമായി മടക്കിയാൽ, അഥവാ, പരലോക താത്പര്യമാക്കിയാൽ, അവന്റെ ഉൽക്കണ്ഠകളിൽ അല്ലാഹു അവനെ സംരക്ഷിക്കുന്നതാണ്. ആരുടെയെങ്കിലും താൽപര്യങ്ങൾ ലൗകികാവസ്ഥകളിൽ പടർന്ന് വന്നാൽ, ലൗകികതയുടെ ഏത് കോണിൽ അവൻ നശിച്ചാലും അല്ലാഹു അവനെ സംരക്ഷിക്കുന്നതല്ല." (ഇതിന്റെ പരമ്പരയിൽ പ്രബലനല്ലാത്ത ഒരു നിവേദകനുണ്ട്.) (ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ طَلَبَ الْعِلْمَ لِغَيْرِ اللَّهِ، أَوْ أَرَادَ بِهِ غَيْرَ اللَّهِ، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (ت,جه)', 'ഇബ്നു ഉമർ(റ): തിരുനബി(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാത്തതിന് വേണ്ടി വല്ലവനും ജ്ഞാനം തേടിയാൽ, അല്ലെങ്കിൽ അവൻ അല്ലാഹുവല്ലാത്തതിനെ അത്കൊണ്ട് ഉദ്ദേശിച്ചാൽ, അവൻ തനിക്ക് നരകത്തിൽ ഇരിപ്പിടം തയ്യാറാക്കിക്കൊള്ളട്ടെ." (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 881, 881, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ رَجُلٍ يَحْفَظُ عِلْمًا فَيَكْتُمُهُ، إِلَّا أُتِيَ بِهِ يَوْمَ الْقِيَامَةِ مُلْجَمًا بِلِجَامٍ مِنَ النَّارِ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു ജ്ഞാനം മനഃപാഠമാക്കുകയും അത് മറച്ചുവെക്കുകയും ചെയ്ത ഏതൊരാളെയും, അന്ത്യനാളിൽ നരകത്തിൽ നിന്നുള്ള കടിഞ്ഞാൺ കൊണ്ട് കടിഞ്ഞാണിട്ടു കൊണ്ടുവരപ്പെടുക തന്നെചെയ്യുക." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 881, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَاللَّهِ، لَوْلَا آيَتَانِ فِي كِتَابِ اللَّهِ تَعَالَى مَا حَدَّثْتُ عَنْهُ - يَعْنِي عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - شَيْئًا أَبَدًا. لَوْلَا قَوْلُ اللَّهِ: {إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلَ اللَّهُ مِنَ الْكِتَابِ...} إِلَى آخِرِ الْآيَتَيْنِ. (ق،جه)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവാണ‌് സത്യം, ഉന്നതനായ അല്ലാഹുവിൻ്റെ ഗ്രന്ഥത്തിൽ രണ്ട് സൂക്തങ്ങൾ ഇല്ലായിരുന്നുവെങ്കിൽ ഞാൻ ഒരിക്കലും നബി(സ)യിൽ നിന്ന് ഒരു ഹദീസും ഉദ്ധരിക്കുമായിരുന്നില്ല. അല്ലാഹുവിൻ്റെ വചനമായ വേദഗ്രന്ഥത്തിൽ നിന്ന് അല്ലാഹു അവതരിപ്പിച്ചവ മറച്ചുവെക്കുന്നവർ... ) തുടങ്ങിയുള്ള രണ്ട് സൂക്തങ്ങളാണവ. (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 882, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا لَعَنَ آخِرُ هَذِهِ الْأُمَّةِ أَوَّلَهَا، فَمَنْ كَتَمَ حَدِيثًا فَقَدْ كَتَمَ مَا أَنْزَلَ اللَّهُ". [ز: في إسناده انقطاع] (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ സമുദായത്തിലെ അവസാന കാലക്കാർ ഇതിലെ ആദ്യ കാലക്കാരെ ശപിക്കുകയും, അന്നേരം വല്ലവനും വല്ല ഹദീസും മറച്ചുവെക്കുകയും ചെയ്താൽ തീർച്ചയായും അവൻ അല്ലാഹു അവതരിപ്പിച്ചതിനെയാണ് മറച്ചുവെച്ചത്." (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഇൻഖിതാഉണ്ട്.) (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده انقطاع', null, 882, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ أُلْجِمَ يَوْمَ الْقِيَامَةِ بِلِجَامٍ مِنْ نَارٍ". [ز: في إسناده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരോടെങ്കിലും ഒരു ജ്ഞാനത്തെക്കുറിച്ച് ചോദിക്കപ്പെടുകയും അവനത് മറച്ചുവെക്കുകയും ചെയ്താൽ, അന്ത്യനാളിൽ നരകത്തിലെ കടിഞ്ഞാൺ കൊണ്ട് അവനെ കടിഞ്ഞാണിടപ്പെടുന്നതാണ്. (ഇതിന്റെ പരമ്പരയിൽ പ്രബലനല്ലാത്ത ഒരു നിവേദകനുണ്ട്.) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 882, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَتَمَ عِلْمًا مِمَّا يَنْفَعُ اللَّهُ بِهِ فِي أَمْرِ النَّاسِ - أَمْرِ الدِّينِ - أَلْجَمَهُ اللَّهُ يَوْمَ الْقِيَامَةِ بِلِجَامٍ مِنَ النَّارِ". [ز: في إسناده ضعيف] (جه)', 'അബൂസഈദിനിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ജനങ്ങൾക്ക് - ദീനിന് - ഉപകാരമായി നൽകിയ ഒരു ജ്ഞാനം ആരെങ്കിലും മറച്ചുവെച്ചാൽ, അവനെ അല്ലാഹു അന്ത്യനാളിൽ നരകത്തിലെ കടിഞ്ഞാൺ കൊണ്ട് കടിഞ്ഞാണിടുന്നതാണ്." (ഇതിന്റെ പരമ്പരയിൽ പ്രബലനല്ലാത്ത ഒരു നിവേദകനുണ്ട്.) (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിനിൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 882, 882, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
